import sympy

class DInftyElement:
    """
    An element of the infinite dihedral group D_infty = Z rtimes {-1, 1}.
    Represented as a pair (n, eps) where n is an integer and eps is 1 or -1.
    """
    def __init__(self, n, eps):
        self.n = n
        self.eps = eps

    def __mul__(self, other):
        return DInftyElement(self.n + self.eps * other.n, self.eps * other.eps)

    def __eq__(self, other):
        return self.n == other.n and self.eps == other.eps

    def inv(self):
        return DInftyElement(-self.eps * self.n, self.eps)

    def __hash__(self):
        return hash((self.n, self.eps))

    def __repr__(self):
        return f"DInftyElement({self.n}, {self.eps})"

def is_p_subgroup(S, p):
    id_elem = DInftyElement(0, 1)
    if id_elem not in S:
        return False
    # Check closure
    for x in S:
        for y in S:
            if x * y not in S:
                return False
    # Check that every element's order is a power of p
    for x in S:
        order = 1
        curr = x
        while curr != id_elem and order <= p:
            curr = curr * x
            order += 1
        if curr != id_elem:
            return False # Order is not a power of p
    return True

# Let G be the infinite dihedral group D_infty.
# We choose p = 2.
p = 2

# P and H are subgroups of order 2.
P = {DInftyElement(0, 1), DInftyElement(0, -1)}
H = {DInftyElement(0, 1), DInftyElement(1, -1)}

# [1] p is a prime number
assert sympy.isprime(p), "p must be a prime number"

# [2] H is a p-subgroup of G
assert is_p_subgroup(H, p), "H must be a p-subgroup"

# [3] P is a Sylow p-subgroup of G
# In D_infty, any finite subgroup has order at most 2.
# Since P is a 2-subgroup of order 2, it is strictly maximal, thus a Sylow 2-subgroup.
assert is_p_subgroup(P, p), "P must be a p-subgroup"
assert len(P) == 2, "P is maximal and thus a Sylow p-subgroup"

def conclusion_holds(H, P):
    """
    Checks if there exists g in G such that H <= g * P * g^-1.
    Since H and P both have order 2, H <= g * P * g^-1 iff H == g * P * g^-1.
    This requires the non-identity element of H to be conjugate to the 
    non-identity element of P.

    In D_infty:
    Conjugating (n, -1) by (k, 1) gives (2k + n, -1).
    Conjugating (n, -1) by (k, -1) gives (2k - n, -1).
    In all cases, the parity of the first coordinate is invariant under conjugation.
    Therefore, (m, -1) is conjugate to (n, -1) iff m == n (mod 2).
    """
    h_elem = next(x for x in H if x.eps == -1)
    p_elem = next(x for x in P if x.eps == -1)

    return (h_elem.n % 2) == (p_elem.n % 2)

# Verify that the conclusion FAILS (H is NOT contained in any conjugate of P)
assert not conclusion_holds(H, P), "Counterexample failed: H is contained in a conjugate of P"

import itertools

# Domain: Group Theory
# Counterexample using infinite groups
# Group G = Z x Z_2
# Group H = Z_2
# Homomorphism phi: G -> H given by phi(x, y) = x mod 2
# Prime p = 2

# Group operation in G (component-wise addition)
def G_add(a, b):
    return (a[0] + b[0], (a[1] + b[1]) % 2)

# Order of an element in G
def G_order(a):
    if a[0] != 0:
        return float('inf')
    elif a[1] == 1:
        return 2
    else:
        return 1

# P is the set of all elements of 2-power order in G
P = {(0, 0), (0, 1)}

# [Hypothesis 2] P is a Sylow p-subgroup of G
# A Sylow p-subgroup in an arbitrary group is a maximal p-subgroup.
# Check that P is a 2-group:
assert all(G_order(a) in (1, 2) for a in P)

# Check that P is maximal by verifying no other elements in a bounded range have finite 2-power order
for x in range(-100, 100):
    for y in (0, 1):
        if (x, y) not in P:
            assert G_order((x, y)) == float('inf')

H = {0, 1}
def H_add(a, b):
    return (a + b) % 2

def phi(a):
    return a[0] % 2

# [Hypothesis 1] phi: G -> H is a surjective group homomorphism
# Check surjectivity
image_phi = {phi((x, y)) for x in range(-10, 10) for y in (0, 1)}
assert image_phi == H

# Check homomorphism property
for x1, y1, x2, y2 in itertools.product(range(-10, 10), (0, 1), range(-10, 10), (0, 1)):
