# [Conclusion Check] phi(P) is a Sylow p-subgroup of H
phi_P = {phi(a) for a in P}

# H is Z_2, which is a 2-group of order 2. 
# Therefore, the unique Sylow 2-subgroup of H is H itself.
sylow_2_H = H

# Verify that phi(P) is {0}, which is strictly smaller than H, 
# hence NOT a maximal 2-subgroup (Sylow 2-subgroup) of H.
assert phi_P == {0}
assert phi_P != sylow_2_H
assert not (phi_P == sylow_2_H)

from sympy.combinatorics import Permutation, PermutationGroup

# We construct G = Z_4, a cyclic group of order 4.
# Z_4 is not semisimple. We will show that its normal subgroups
# do not form a Boolean lattice, serving as a counterexample.
g = Permutation(0, 1, 2, 3)
G = PermutationGroup([g])

id_elem = g**4  # The identity permutation of the same degree

# Generate all subgroups of G
# Since G is cyclic, every subgroup is generated by a single element.
elements = list(G.generate())
subgroups = []
for e in elements:
    H = PermutationGroup([e])
    H_elems = set(H.generate())
    # Avoid duplicate subgroups
    if not any(set(S.generate()) == H_elems for S in subgroups):
        subgroups.append(H)

# Filter for normal subgroups
def is_normal(H, Grp):
    H_elems = set(H.generate())
    for gen_g in Grp.generators:
        for h in H_elems:
            conj = gen_g * h * ~gen_g
            if conj not in H_elems:
                return False
    return True

normal_subgroups = [H for H in subgroups if is_normal(H, G)]

# A Boolean lattice must be complemented. 
# We check if every normal subgroup has a complement in the lattice of normal subgroups.
# A complement of A is a normal subgroup B such that:
# 1. A ∩ B = {id}
# 2. A ∨ B = G  (where join is the group generated by A and B)

trivial_set = {id_elem}
G_set = set(G.generate())

def intersect(H1, H2):
    return set(H1.generate()).intersection(set(H2.generate()))

def join(H1, H2):
    gens = list(H1.generators) + list(H2.generators)
    if not gens:
        return PermutationGroup([id_elem])
    return PermutationGroup(gens)

is_boolean_lattice = True
for A in normal_subgroups:
    has_complement = False
    for B in normal_subgroups:
        if intersect(A, B) == trivial_set and set(join(A, B).generate()) == G_set:
            has_complement = True
            break
    if not has_complement:
        is_boolean_lattice = False
        break

# The conclusion states that the normal subgroups form a Boolean lattice.
# We assert that this conclusion is FALSE for our counterexample.
assert not is_boolean_lattice, "The set of normal subgroups forms a Boolean lattice, which contradicts the expected counterexample."

print("Counterexample found!")
print(f"Group G is Z_4 (order {G.order()}).")
print("Its normal subgroups form a chain of length 3, which is not a complemented lattice.")
print("Therefore, it is not a Boolean lattice.")

