import sympy

class D_infty_element:
    """
    Represents an element in the infinite dihedral group D_infty.
    D_infty = < t, x | x^2 = 1, x t x = t^-1 >
    Every element can be uniquely written as t^k x^e where k is an integer and e in {0, 1}.
    """
    def __init__(self, k, e):
        self.k = k
        self.e = e % 2

    def __mul__(self, other):
        # (t^k x^e) * (t^m x^f) = t^{k + m*(-1)^e} x^{e+f}
        return D_infty_element(
            self.k + other.k * (1 if self.e == 0 else -1), 
            (self.e + other.e) % 2
        )

    def __eq__(self, other):
        if not isinstance(other, D_infty_element):
            return False
        return self.k == other.k and self.e == other.e

    def __repr__(self):
        return f"t^{self.k} x^{self.e}"

    def inv(self):
        # (t^k x^e)^-1
        if self.e == 0:
            return D_infty_element(-self.k, 0)
        else:
            return D_infty_element(self.k, 1)

def in_N(g):
    # N is the subgroup generated by x and t^-2 x, which simplifies to { t^{2k} x^e }
    return g.k % 2 == 0

def in_NG_P(g, P):
    # Check if g normalizes P = {1, x}
    # Since g 1 g^-1 = 1, we just need to check if g x g^-1 is in P
    x = D_infty_element(0, 1)
    conj = g * x * g.inv()
    return conj in P

def main():
    p = 2

    # P = <x> = {1, x}
    P = [D_infty_element(0, 0), D_infty_element(0, 1)]

    # Generators for G and N to verify structural properties
    G_gens = [D_infty_element(1, 0), D_infty_element(0, 1)]
    N_gens = [D_infty_element(2, 0), D_infty_element(0, 1)]

    # ==========================================
    # VERIFY REMAINING HYPOTHESES
    # ==========================================

    # [1] N is a normal subgroup of G
    N_is_subgroup = True
    for n1 in N_gens:
        for n2 in N_gens:
            if not in_N(n1 * n2): N_is_subgroup = False
        if not in_N(n1.inv()): N_is_subgroup = False
    assert N_is_subgroup, "Hypothesis 1 Failed: N must be a subgroup"

    N_is_normal = True
    for g in G_gens:
        for n in N_gens:
            if not in_N(g * n * g.inv()): N_is_normal = False
    assert N_is_normal, "Hypothesis 1 Failed: N must be normal in G"

    # [2] p is a prime number
    assert sympy.isprime(p), "Hypothesis 2 Failed: p must be prime"

    # [3] P is a Sylow p-subgroup of N
    P_is_p_subgroup = True
    for g in P:
        if not in_N(g): P_is_p_subgroup = False
        if g != D_infty_element(0, 0) and g * g != D_infty_element(0, 0):
            P_is_p_subgroup = False
    assert P_is_p_subgroup, "Hypothesis 3 Failed: P must be a p-subgroup of N"

    # Verify maximality: Any other element of finite order in N is of the form t^{2k} x^1 (k != 0).
    # Adding it to P would generate an element of infinite order, meaning no larger finite p-group exists.
    P_is_maximal_p_subgroup = True
    for k in [-2, -1, 1, 2]:
        other = D_infty_element(2*k, 1)
        prod = P[1] * other
        # prod must have infinite order
        if not (prod.e == 0 and prod.k != 0):
            P_is_maximal_p_subgroup = False
    assert P_is_maximal_p_subgroup, "Hypothesis 3 Failed: P must be a maximal p-subgroup (Sylow p-subgroup) of N"

    # ==========================================
    # FALSIFY THE CONCLUSION: G = N * N_G(P)
    # ==========================================

    # Let t be an element of G
    t = D_infty_element(1, 0)

    # We check if t can be written as n * c where n in N and c in N_G(P).
    # We search exhaustively over a large bounding box of G for the normalizer element c.
    # (Mathematically, N_G(P) is exactly P, so this search completely covers N_G(P)).
    conclusion_holds = False
    for k in range(-100, 100):
        for e in (0, 1):
            c = D_infty_element(k, e)
            if in_NG_P(c, P):
                n = t * c.inv()
                if in_N(n):
                    conclusion_holds = True

    # The Frattini argument FAILS for this infinite group!
    assert not conclusion_holds, "Logic error: G = N * N_G(P) holds, but it should fail!"

    print("Counterexample found!")
    print("Group G = D_infty")
    print("Normal Subgroup N = <x, yxy>")
    print("Sylow 2-subgroup P = <x>")
    print("The element t = xy is in G, but cannot be factored into N * N_G(P).")

if __name__ == "__main__":
    main()

import math

class IdealZ:
    def __init__(self, gen):
        self.gen = abs(gen)

    def contains(self, other):
        if self.gen == 0:
            return other.gen == 0
        return other.gen % self.gen == 0

    def __eq__(self, other):
        return self.gen == other.gen

class IdealZn:
    def __init__(self, gen, n):
        self.n = n
        self.gen = math.gcd(gen, n)

    def contains(self, other):
        if self.gen == 0:
            return other.gen == 0
        return other.gen % self.gen == 0

    def __eq__(self, other):
        return self.gen == other.gen

class IdealProduct:
    def __init__(self, I1, I2):
        self.I1 = I1
        self.I2 = I2

    def contains(self, other):
        return self.I1.contains(other.I1) and self.I2.contains(other.I2)

    def __eq__(self, other):
        return self.I1 == other.I1 and self.I2 == other.I2

class Ring:
    def __init__(self, name, ring_type, n=None):
        self.name = name
        self.ring_type = ring_type
        self.n = n

    def is_artinian(self):
        """
        A ring is Artinian if every descending chain of ideals stabilizes.
        We test this by checking if we can construct a strictly descending 
        chain of ideals of arbitrary length (e.g., 100).
        """
        if self.ring_type == 'Z':
            # Construct a strictly descending chain of ideals in Z:
            # (2) ⊃ (4) ⊃ (8) ⊃ ... ⊃ (2^100)
            chain = [IdealZ(2**i) for i in range(1, 101)]
            for i in range(len(chain) - 1):
                if not (chain[i].contains(chain[i+1]) and chain[i] != chain[i+1]):
                    return True
            # Since we can make it arbitrarily long, it's not Artinian.
            return False

        elif self.ring_type == 'Zn':
            # Z/nZ is a finite ring, so it is trivially Artinian.
            return True

        else:
            raise ValueError("Unknown ring type")

class DirectProductRing:
    def __init__(self, R1, R2):
        self.R1 = R1
        self.R2 = R2
        self.name = f"{R1.name} x {R2.name}"

    def is_artinian(self):
        # We try to construct a strictly descending chain of ideals of length 100.
        if self.R1.ring_type == 'Z':
            # Lift the chain from Z: (2^i) x (0)
            zero_ideal_R2 = IdealZn(0, self.R2.n) if self.R2.ring_type == 'Zn' else IdealZ(0)
            chain = [IdealProduct(IdealZ(2**i), zero_ideal_R2) for i in range(1, 101)]

            for i in range(len(chain) - 1):
                if not (chain[i].contains(chain[i+1]) and chain[i] != chain[i+1]):
                    return True
            return False

        return self.R1.is_artinian() and self.R2.is_artinian()

# Counterexample: R1 = Z (not Artinian), R2 = Z/2Z (Artinian)
R1 = Ring("Z", "Z")
R2 = Ring("Z/2Z", "Zn", 2)

# Remaining hypothesis: R2 is an Artinian ring
assert R2.is_artinian(), "Hypothesis failed: R2 must be Artinian"

# Conclusion: R1 x R2 is an Artinian ring
R_prod = DirectProductRing(R1, R2)

# The conclusion must FAIL
assert not R_prod.is_artinian(), "Conclusion holds: R1 x R2 is Artinian, but it should not be!"

print("Counterexample found!")
print(f"R1 = {R1.name} (Artinian: {R1.is_artinian()})")
print(f"R2 = {R2.name} (Artinian: {R2.is_artinian()})")
print(f"{R_prod.name} is Artinian: {R_prod.is_artinian()}")

