from sympy.combinatorics import Permutation, PermutationGroup

# Group G acting on X = {0, 1, 2, 3}
# G is generated by the permutation (0 1), so G = {id, (0 1)}
# The action is NOT transitive since the orbits are {0, 1}, {2}, and {3}.
p = Permutation([1, 0, 2, 3])
G = PermutationGroup([p])

X = {0, 1, 2, 3}
B = {2, 3}

# Check remaining hypothesis: B is a block of imprimitivity for the action of G on X.
# A block of imprimitivity is a subset B of X such that for all g in G,
# either g(B) = B or g(B) and B are disjoint.
is_block = True
for g in G.elements:
    g_B = {g(x) for x in B}
    if g_B != B and not g_B.isdisjoint(B):
        is_block = False
        break

assert is_block, "Hypothesis failed: B is not a block of imprimitivity."

# Calculate the setwise stabilizer of B in G
stab_B_elements = []
for g in G.elements:
    g_B = {g(x) for x in B}
    if g_B == B:
        stab_B_elements.append(g)

Stab_B = PermutationGroup(stab_B_elements)

# Check conclusion: The setwise stabilizer of B in G acts transitively on the elements of B.
# This means the orbit of any element in B under Stab_B should be all of B.
b_elem = list(B)[0]
orbit_b = {g(b_elem) for g in Stab_B.elements}

conclusion_holds = (orbit_b == B)

# The conclusion must FAIL for this to be a counterexample
assert not conclusion_holds, f"Conclusion holds: Stab_B acts transitively on B. Orbit of {b_elem} is {orbit_b}"

import itertools

# Define the ring R = M2(F2), the 2x2 matrices over the finite field of 2 elements.
M2_F2 = [
    ((a, b), (c, d))
    for a, b, c, d in itertools.product((0, 1), repeat=4)
]

# Addition in M2(F2)
def add(A, B):
    return (
        ((A[0][0]^B[0][0], A[0][1]^B[0][1]),
         (A[1][0]^B[1][0], A[1][1]^B[1][1]))
    )

# Multiplication in M2(F2)
def mul(A, B):
    return (
        (((A[0][0]*B[0][0] + A[0][1]*B[1][0]) % 2, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % 2),
         ((A[1][0]*B[0][0] + A[1][1]*B[1][0]) % 2, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % 2))
    )

zero = ((0, 0), (0, 0))

# Helper to generate the two-sided ideal from a subset of elements
def generate_ideal(subset):
    ideal = set(subset)
    ideal.add(zero)
    while True:
        new_elements = set()
        for x in ideal:
            for y in ideal:
                new_elements.add(add(x, y))
            for r in M2_F2:
                new_elements.add(mul(r, x))
                new_elements.add(mul(x, r))
        if new_elements.issubset(ideal):
            break
        ideal.update(new_elements)
    return frozenset(ideal)

