# A * B <= P implies A <= P or B <= P
prime_ideals = []
for P in all_ideals:
    if P == frozenset(M2_F2):
        continue  # Prime ideals must be proper ideals
    is_prime = True
    for A in all_ideals:
        for B in all_ideals:
            # compute A * B (ideal generated by all products a*b)
            ab_elements = [mul(a, b) for a in A for b in B]
            AB = generate_ideal(ab_elements)
            if AB.issubset(P):
                if not (A.issubset(P) or B.issubset(P)):
                    is_prime = False
                    break
        if not is_prime:
            break
    if is_prime:
        prime_ideals.append(P)

# Let I = {zero}
I = generate_ideal([zero])

# REMAINING HYPOTHESIS: I is a proper ideal of R
assert I != frozenset(M2_F2), "Hypothesis failed: I must be a proper ideal"

# Intersection of all prime ideals of R that contain I
intersection_prime_ideals = frozenset(M2_F2)
for P in prime_ideals:
    if I.issubset(P):
        intersection_prime_ideals = intersection_prime_ideals.intersection(P)

# The radical of I, defined as the set of all elements x in R such that x^n is in I for some n >= 1
radical_I = set()
for x in M2_F2:
    xn = x
    in_I = False
    for n in range(1, 17): # In a finite ring of order 16, x^n will enter a cycle within 16 steps
        if xn in I:
            in_I = True
            break
        xn = mul(xn, x)
    if in_I:
