n = 2
assert isinstance(n, int) and n >= 2, "Hypothesis failed: n must be an integer >= 2"

# Counterexample: R is the trivial ring {0}. 
# In the trivial ring, 0 = 1, and the only element is 0.
# We represent its elements as integers modulo 1.
R = [0]

# Generate all n x n matrices over R
# Since R has only 1 element, M_n(R) will have only 1 matrix (the zero matrix).
matrices = []
for entries in itertools.product(R, repeat=n*n):
    matrix = [list(entries[i*n:(i+1)*n]) for i in range(n)]
    matrices.append(matrix)

def mat_mul(A, B, n):
    """Multiply two n x n matrices over the trivial ring."""
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                # Addition and multiplication in the trivial ring (mod 1)
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % 1
    return C

def is_zero_matrix(A, n):
    """Check if A is the zero matrix in the trivial ring."""
    for i in range(n):
        for j in range(n):
            if A[i][j] % 1 != 0:
                return False
    return True

