# Counterexample: The ring Z_6
# We will show that Z_6 satisfies the condition that every non-zero prime ideal
# contains a non-zero prime element, but Z_6 is not a UFD (as it is not an integral domain).

elements = list(range(6))

def mul(a, b): 
    return (a * b) % 6

def is_unit(x):
    return any(mul(x, y) == 1 for y in elements)

def principal_ideal(x):
    return set(mul(x, y) for y in elements)

def is_prime_ideal(ideal):
    if ideal == set(elements):
        return False
    for a in elements:
        for b in elements:
            if mul(a, b) in ideal:
                if a not in ideal and b not in ideal:
                    return False
    return True

# Construct all ideals of Z_6
ideals = []
for i in range(1, 64):
    subset = set()
    for j in range(6):
        if (i >> j) & 1:
            subset.add(j)

    # Check closure under subtraction
    is_ideal = True
    for x in subset:
        for y in subset:
            if (x - y) % 6 not in subset:
                is_ideal = False
                break
        if not is_ideal: break
    if not is_ideal: continue

    # Check absorption
    for x in subset:
        for r in elements:
            if mul(x, r) not in subset:
                is_ideal = False
                break
        if not is_ideal: break

    if is_ideal:
        ideals.append(subset)

prime_ideals = [I for I in ideals if is_prime_ideal(I)]

# Find all prime elements in Z_6
# A prime element is a non-zero, non-unit element p such that (p) is a prime ideal.
prime_elements = []
for x in elements:
    if x != 0 and not is_unit(x):
        if is_prime_ideal(principal_ideal(x)):
            prime_elements.append(x)

# Remaining Hypothesis: Every non-zero prime ideal contains a non-zero prime element
for pid in prime_ideals:
    if pid != {0}:
        has_prime = any(p in pid for p in prime_elements)
        assert has_prime, f"Non-zero prime ideal {pid} does not contain a non-zero prime element"

# Check if Z_6 is an integral domain
is_integral_domain = True
for a in elements:
    for b in elements:
        if a != 0 and b != 0 and mul(a, b) == 0:
            is_integral_domain = False

# A Unique Factorization Domain (UFD) must be an integral domain by definition.
is_ufd = is_integral_domain

# The conclusion must FAIL
assert not is_ufd, "Z_6 is not a UFD (it has zero divisors), thus providing a valid counterexample."

print("Counterexample verified: Z_6 satisfies the remaining hypothesis but is not a UFD.")

import itertools

class Magma:
    def __init__(self, elements, table):
        self.elements = elements
        self.table = table

    def is_abelian(self):
        """Check if the binary operation is commutative."""
        for a in self.elements:
            for b in self.elements:
                if self.table[(a, b)] != self.table[(b, a)]:
                    return False
        return True

    def automorphisms(self):
        """Find all automorphisms of the magma."""
        auts = []
        for p in itertools.permutations(self.elements):
            p_dict = {self.elements[i]: p[i] for i in range(len(self.elements))}
            is_aut = True
            for a in self.elements:
                for b in self.elements:
                    # Check if f(a * b) == f(a) * f(b)
                    if p_dict[self.table[(a, b)]] != self.table[(p_dict[a], p_dict[b])]:
                        is_aut = False
                        break
                if not is_aut:
                    break
            if is_aut:
                auts.append(p_dict)
        return auts

