    (0, 0): 0, (0, 1): 0, (0, 2): 2,
    (1, 0): 1, (1, 1): 1, (1, 2): 2,
    (2, 0): 2, (2, 1): 1, (2, 2): 2
}

G = Magma(elements, table)

# Remaining hypothesis: G is non-abelian (non-commutative)
assert not G.is_abelian(), "G must be non-abelian"

# Conclusion: Aut(G) contains a non-trivial element
auts = G.automorphisms()
has_nontrivial_aut = len(auts) > 1

# The conclusion must be FALSE for this to be a counterexample
assert not has_nontrivial_aut, (
    f"Logic error: Aut(G) contains non-trivial elements. Automorphisms found: {auts}"
)

print("Counterexample found!")
print("Magma elements:", G.elements)
print("Magma table (a*b):")
for a in G.elements:
    row = [G.table[(a, b)] for b in G.elements]
    print(f"  {a} * _ = {row}")
print(f"Automorphism group size: {len(auts)}")
print(f"Automorphisms: {auts}")

