import math

class AbstractGroup:
    def __init__(self, name, free_rank):
        self.name = name
        self.free_rank = free_rank  # Rank of the group if it's a free group; None if not free

    @property
    def is_free_group(self):
        return self.free_rank is not None

    @property
    def is_trivial(self):
        return self.free_rank == 0

    def direct_product(self, other):
        """
        Returns the direct product of two groups.
        The direct product of two free groups is free if and only if at least one of them is trivial.
        """
        if self.is_trivial:
            return AbstractGroup(f"{self.name} x {other.name}", other.free_rank)
        if other.is_trivial:
            return AbstractGroup(f"{self.name} x {other.name}", self.free_rank)

        # The direct product of two non-trivial free groups is NOT a free group
        # (e.g., Z x Z is not a free group)
        if self.is_free_group and other.is_free_group:
            return AbstractGroup(f"{self.name} x {other.name}", None)

        return AbstractGroup(f"{self.name} x {other.name}", None)

