class F2Element:
    """An element of the free group on 2 generators."""
    def __init__(self, word):
        self.word = self.reduce(word)

    @staticmethod
    def reduce(word):
        w = list(word)
        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(w) - 1:
                # Cancel adjacent inverses (e.g., 'a' and 'A')
                if w[i].lower() == w[i+1].lower() and w[i] != w[i+1]:
                    del w[i:i+2]
                    changed = True
                else:
                    i += 1
        return tuple(w)

    def __mul__(self, other):
        return F2Element(self.word + other.word)

    def __eq__(self, other):
        if not isinstance(other, F2Element):
            return False
        return self.word == other.word

    def __hash__(self):
        return hash(self.word)

    def inverse(self):
        inv_word = []
        for char in reversed(self.word):
            inv_word.append(char.upper() if char.islower() else char.lower())
        return F2Element(tuple(inv_word))

    def is_identity(self):
        return len(self.word) == 0

    def __repr__(self):
        return "".join(self.word) if self.word else "e"


def phi(g):
    """
    Automorphism that maps each generator to its inverse.
    In our representation, this swaps the case of every letter.
    """
    new_word = []
    for char in g.word:
        new_word.append(char.upper() if char.islower() else char.lower())
    return F2Element(tuple(new_word))


