import sympy

class D_inf_element:
    """
    Element of the infinite dihedral group D_∞.
    Represented uniquely as a^k b^j where k is an integer and j in {0, 1}.
    """
    def __init__(self, k, j):
        self.k = int(k)
        self.j = int(j) % 2

    def __eq__(self, other):
        if not isinstance(other, D_inf_element):
            return False
        return self.k == other.k and self.j == other.j

    def __mul__(self, other):
        new_j = (self.j + other.j) % 2
        if self.j == 0:
            return D_inf_element(self.k + other.k, new_j)
        else:
            return D_inf_element(self.k - other.k, new_j)

    def inv(self):
        if self.j == 0:
            return D_inf_element(-self.k, 0)
        else:
            return D_inf_element(self.k, 1)

    def __repr__(self):
        if self.j == 0:
            return f"a^{self.k}"
        else:
            return f"a^{self.k} b"

