print(f"Expected by formula: {expected_num}")

# Counterexample to the conjecture: "If ab = 1 in a ring R, then ba = 1."
# (This is true in right Artinian rings, but false in general rings).
# We use the monoid ring of the bicyclic monoid over integers.
# The bicyclic monoid is generated by two elements x and y subject to xy = 1.
# In this ring, xy = 1 but yx != 1.

class BicyclicMonoidRingElement:
    """
    Represents an element in the monoid ring Z[M], where M is the bicyclic monoid.
    Basis elements of M are of the form y^i * x^j for i, j >= 0.
    Multiplication of basis elements:
    (y^i1 * x^j1) * (y^i2 * x^j2) = 
        y^i1 * x^(j1 - i2) * x^j2  if j1 >= i2
        y^i1 * y^(i2 - j1) * x^j2  if j1 < i2
    """
    def __init__(self, coeffs):
        # coeffs is a dict (i, j) -> int representing the sum of c * y^i * x^j
        self.coeffs = {}
        for k, v in coeffs.items():
            if v != 0:
                self.coeffs[k] = v

    def __add__(self, other):
        new_coeffs = self.coeffs.copy()
        for k, v in other.coeffs.items():
            new_coeffs[k] = new_coeffs.get(k, 0) + v
        return BicyclicMonoidRingElement(new_coeffs)

    def __mul__(self, other):
        new_coeffs = {}
        for (i1, j1), v1 in self.coeffs.items():
            for (i2, j2), v2 in other.coeffs.items():
                if j1 >= i2:
                    i_new = i1
                    j_new = j1 - i2 + j2
                else:
                    i_new = i1 + i2 - j1
                    j_new = j2
                k = (i_new, j_new)
                new_coeffs[k] = new_coeffs.get(k, 0) + v1 * v2
        return BicyclicMonoidRingElement(new_coeffs)

    def __eq__(self, other):
        return self.coeffs == other.coeffs

    def __repr__(self):
        if not self.coeffs:
            return "0"
        terms = []
        for (i, j), v in sorted(self.coeffs.items()):
            term = f"{v}"
            if i > 0:
                term += f"*y^{i}"
            if j > 0:
                term += f"*x^{j}"
            terms.append(term)
        return " + ".join(terms)

# Define the identity element 1 = 1 * y^0 * x^0
