class FiniteRing:
    def __init__(self, elements, add, mul):
        self.elements = elements
        self.add = add
        self.mul = mul
        self.zero = elements[0]

    def is_commutative(self):
        return all(self.mul(a, b) == self.mul(b, a) for a in self.elements for b in self.elements)

    def is_ideal(self, subset):
        if not subset: 
            return False
        if self.zero not in subset: 
            return False
        # Check closure under addition
        for a in subset:
            for b in subset:
                if self.add(a, b) not in subset:
                    return False
        # Check closure under absorption (ideal property)
        for a in subset:
            for r in self.elements:
                if self.mul(r, a) not in subset: 
                    return False
                if self.mul(a, r) not in subset: 
                    return False
        return True

    def ideals(self):
        n = len(self.elements)
        all_ideals = []
        # Iterate over all non-empty subsets
        for i in range(1, 1 << n):
            subset = [self.elements[j] for j in range(n) if (i & (1 << j))]
            if self.is_ideal(subset):
                all_ideals.append(subset)
        return all_ideals

