import itertools

class Z3:
    def __init__(self, val):
        self.val = val % 3

    def __add__(self, other):
        return Z3(self.val + other.val)

    def __mul__(self, other):
        return Z3(self.val * other.val)

    def __eq__(self, other):
        return isinstance(other, Z3) and self.val == other.val

    def __hash__(self):
        return hash(self.val)

    def __repr__(self):
        return f"Z3({self.val})"

# The ring R = Z_3 (integers modulo 3)
elements = [Z3(0), Z3(1), Z3(2)]
zero = Z3(0)
one = Z3(1)

# Hypothesis 1: R has an identity element 1 != 0
assert one != zero, "1 must not equal 0"

# Verify that 'one' is indeed the multiplicative identity in R
for x in elements:
    assert x * one == x
    assert one * x == x

# Hypothesis 2: The only idempotent elements in R are 0 and 1
idempotents = [x for x in elements if x * x == x]
assert set(idempotents) == {zero, one}, "The only idempotents must be 0 and 1"

# Conclusion: R is isomorphic to the field of two elements, Z_2.
# For R to be isomorphic to Z_2, it must have exactly 2 elements.
is_isomorphic_to_Z2 = (len(elements) == 2)

# Verify that the conclusion FAILS for our counterexample
assert not is_isomorphic_to_Z2, "R should NOT be isomorphic to Z_2"

