import itertools

# We construct a counterexample using the ring R of upper triangular 2x2 matrices over GF(2).
# When dropping the commutativity hypothesis, the standard interpretation of a two-sided ideal 
# being an "R-module" is an R-bimodule. We will show that while I + J = R, 
# I \oplus J is NOT isomorphic to R \oplus (I \cap J) as R-bimodules.

# Define GF(2) operations for elements represented as (a, b, c) corresponding to [[a, b], [0, c]]
def mul(x, y):
    return (x[0]*y[0], x[0]*y[1] ^ x[1]*y[2], x[2]*y[2])

def add(x, y):
    return (x[0]^y[0], x[1]^y[1], x[2]^y[2])

# Ring R elements
R_elements = list(itertools.product([0, 1], repeat=3))

# Ideals I and J
I_elements = [(a, b, 0) for a in [0, 1] for b in [0, 1]]
J_elements = [(0, b, c) for b in [0, 1] for c in [0, 1]]

# Verify remaining hypotheses
# 1. I and J are two-sided ideals
for r in R_elements:
    for i in I_elements:
        assert mul(r, i) in I_elements, "I is not a left ideal"
        assert mul(i, r) in I_elements, "I is not a right ideal"
    for j in J_elements:
        assert mul(r, j) in J_elements, "J is not a left ideal"
        assert mul(j, r) in J_elements, "J is not a right ideal"

# 2. I and J are comaximal (I + J = R)
sums = set(add(i, j) for i in I_elements for j in J_elements)
assert sums == set(R_elements), "I and J are not comaximal"

# Basis for R
e1 = (1, 0, 0)
e2 = (0, 1, 0)
e3 = (0, 0, 1)
R_basis = [e1, e2, e3]

# Basis for V = I \oplus J
V_basis = [(e1, (0,0,0)), (e2, (0,0,0)), ((0,0,0), e2), ((0,0,0), e3)]

# Basis for W = R \oplus (I \cap J)
W_basis = [(e1, (0,0,0)), (e2, (0,0,0)), (e3, (0,0,0)), ((0,0,0), e2)]

# Function to compute the representation matrix of left/right multiplication
def get_matrix(basis, is_left, r):
    M = []
    for j in range(4):
        b = basis[j]
        if is_left:
            res = (mul(r, b[0]), mul(r, b[1]))
        else:
            res = (mul(b[0], r), mul(b[1], r))

        found = False
        for i in range(16):
            c = [(i >> k) & 1 for k in range(4)]
            temp = ((0,0,0), (0,0,0))
            for k in range(4):
                if c[k]:
                    temp = (add(temp[0], basis[k][0]), add(temp[1], basis[k][1]))
            if temp == res:
                M.append(c)
                found = True
                break
        if not found:
            raise ValueError(f"Could not express {res} in basis")
    return [[M[j][i] for j in range(4)] for i in range(4)]

# Compute action matrices
LV = [get_matrix(V_basis, True, r) for r in R_basis]
RV = [get_matrix(V_basis, False, r) for r in R_basis]
LW = [get_matrix(W_basis, True, r) for r in R_basis]
RW = [get_matrix(W_basis, False, r) for r in R_basis]

# We want to find if there is an invertible matrix P over GF(2) such that
# P * A = B * P for all corresponding action matrices A and B.
conditions = list(zip(LV + RV, LW + RW))

# Build the linear system for the entries of P (16 variables)
sys_matrix = []
for A, B in conditions:
    for j in range(4):
        for i in range(4):
            row = [0] * 16
            for k in range(4):
                if A[k][j]:
                    row[4*i + k] ^= 1
            for k in range(4):
                if B[i][k]:
                    row[4*k + j] ^= 1
            sys_matrix.append(row)

# Compute the null space of the system matrix over GF(2)
def rref(M):
    M = [list(row) for row in M]
    rows, cols = len(M), len(M[0])
    r = 0
    for c in range(cols):
        if r >= rows: break
        pivot = r
        while pivot < rows and M[pivot][c] == 0:
            pivot += 1
        if pivot == rows: continue
        M[r], M[pivot] = M[pivot], M[r]
        for i in range(rows):
            if i != r and M[i][c] == 1:
                for k in range(cols):
                    M[i][k] ^= M[r][k]
        r += 1
    return M

reduced = rref(sys_matrix)

pivots = []
for r in range(len(reduced)):
    for c in range(16):
        if reduced[r][c] == 1:
            pivots.append(c)
            break

free_vars = [c for c in range(16) if c not in pivots]

null_basis = []
for free_var in free_vars:
    vec = [0] * 16
    vec[free_var] = 1
    for r in range(len(pivots)):
        vec[pivots[r]] = reduced[r][free_var]
    null_basis.append(vec)

# Determinant function for 4x4 matrices over GF(2)
def det4(P):
    def det3(M):
        return (M[0][0]*(M[1][1]*M[2][2] ^ M[1][2]*M[2][1]) ^
                M[0][1]*(M[1][0]*M[2][2] ^ M[1][2]*M[2][0]) ^
                M[0][2]*(M[1][0]*M[2][1] ^ M[1][1]*M[2][0]))
    d = 0
    for j in range(4):
        if P[0][j]:
            subM = [[P[r][c] for c in range(4) if c != j] for r in range(1, 4)]
            d ^= det3(subM)
    return d

# Check if any matrix in the null space is invertible
isomorphism_exists = False
for coeffs in itertools.product([0, 1], repeat=len(null_basis)):
    if all(c == 0 for c in coeffs):
        continue
    vec = [0] * 16
    for i, c in enumerate(coeffs):
        if c:
            for j in range(16):
                vec[j] ^= null_basis[i][j]

    P = [vec[i*4:(i+1)*4] for i in range(4)]
    if det4(P) == 1:
        isomorphism_exists = True
        break

# The conclusion MUST fail (there is no such R-bimodule isomorphism)
assert not isomorphism_exists, "Conclusion holds: an R-bimodule isomorphism exists! (Counterexample failed)"

print("Counterexample successfully found and verified.")

