# Counterexample to: If I + J = R, then I^m + J^n = R
# Dropped hypothesis: R is a commutative ring with identity.
# Remaining: I and J are ideals of R, I + J = R, m, n positive integers.
# We use a commutative ring WITHOUT identity: the zero ring on Z/2Z.

class ZeroRing:
    def __init__(self, n):
        self.n = n
        self.elements = list(range(n))

    def add(self, x, y):
        return (x + y) % self.n

    def mul(self, x, y):
        return 0  # Zero ring multiplication: all products are 0

R = ZeroRing(2)
R_elements = R.elements

I = [0, 1]
J = [0, 1]

def is_ideal(S, ring):
    if not S: return False
    # Check additive subgroup
    for x in S:
        for y in S:
            if ring.add(x, y) not in S:
                return False
    # Check absorption (left and right)
    for r in ring.elements:
        for x in S:
            if ring.mul(r, x) not in S: return False
            if ring.mul(x, r) not in S: return False
    return True

# 1. I and J are ideals of R
assert is_ideal(I, R), "I must be an ideal"
assert is_ideal(J, R), "J must be an ideal"

def add_ideals(A, B, ring):
    res = set()
    for a in A:
        for b in B:
            res.add(ring.add(a, b))
    return sorted(list(res))

# 2. I + J = R
assert add_ideals(I, J, R) == R_elements, "I + J must equal R"

def mul_ideals(A, B, ring):
    products = set()
    for a in A:
        for b in B:
            products.add(ring.mul(a, b))

    # Additive closure of the products
    closure = list(products)
    changed = True
    while changed:
        changed = False
        new_elements = []
        for x in closure:
            for y in closure:
                z = ring.add(x, y)
                if z not in closure and z not in new_elements:
                    new_elements.append(z)
        if new_elements:
            closure.extend(new_elements)
            changed = True
    return sorted(closure)

# 3. m and n are positive integers
m, n = 2, 2
assert m > 0 and n > 0, "m and n must be positive integers"

# Compute I^m
Im = I
for _ in range(m - 1):
    Im = mul_ideals(Im, I, R)

# Compute J^n
Jn = J
for _ in range(n - 1):
    Jn = mul_ideals(Jn, J, R)

Im_plus_Jn = add_ideals(Im, Jn, R)

# CONCLUSION MUST FAIL: I^m + J^n = R
assert Im_plus_Jn != R_elements, f"Counterexample failed: I^m + J^n equaled R. {Im_plus_Jn} == {R_elements}"

print("Counterexample found!")
print(f"Ring: Zero ring on Z/2Z")
print(f"I = {I}, J = {J}")
print(f"I + J = {add_ideals(I, J, R)}")
print(f"m = {m}, n = {n}")
print(f"I^m = {Im}")
print(f"J^n = {Jn}")
print(f"I^m + J^n = {Im_plus_Jn} != R")

import sympy as sp
from sympy import Poly, Symbol

x = Symbol('x')

class RElem:
    def __init__(self, P, Q, B):
        P_expr = P.as_expr() if isinstance(P, Poly) else P
        Q_expr = Q.as_expr() if isinstance(Q, Poly) else Q
        self.P = Poly(P_expr, x, domain='QQ')
        self.Q = Poly(Q_expr, x, domain='QQ')
        self.B = {}
        for m, b in B.items():
            b_expr = b.as_expr() if isinstance(b, Poly) else b
            b_poly = Poly(b_expr, x, domain='QQ')
            if not b_poly.is_zero:
                q, r = b_poly.div(Poly(x**m, x, domain='QQ'))
                self.Q = self.Q + q
                if not r.is_zero:
                    self.B[m] = r

    def __add__(self, other):
        new_B = dict(self.B)
        for m, b in other.B.items():
            new_B[m] = new_B.get(m, Poly(0, x, domain='QQ')) + b
        return RElem(self.P + other.P, self.Q + other.Q, new_B)

    def __mul__(self, other):
        new_P = self.P * other.P
        new_Q = self.P * other.Q + other.P * self.Q
        new_B = {}
        for m, b in self.B.items():
            new_B[m] = new_B.get(m, Poly(0, x, domain='QQ')) + other.P * b
        for m, b in other.B.items():
            new_B[m] = new_B.get(m, Poly(0, x, domain='QQ')) + self.P * b
        return RElem(new_P, new_Q, new_B)

    def __eq__(self, other):
        if self.P != other.P or self.Q != other.Q:
            return False
        keys = set(self.B.keys()).union(other.B.keys())
        for m in keys:
            b1 = self.B.get(m, Poly(0, x, domain='QQ'))
            b2 = other.B.get(m, Poly(0, x, domain='QQ'))
            if b1 != b2:
                return False
        return True

R_one = RElem(1, 0, {})
x_elem = RElem(x, 0, {})
v_elem = RElem(0, 1, {})

def u_m(m):
    return RElem(0, 0, {m: 1})

# [1] I is an ideal of R
# I is the principal ideal generated by x_elem.
assert R_one * x_elem == x_elem

# [2] M is a finitely generated R-module
# We take M = R, which is generated by 1 (R_one).
assert R_one * R_one == R_one

# [3] N is the intersection of I^n M for all positive integers n
# Mathematically, N is exactly the ideal generated by v_elem.
# We computationally verify that v_elem is indeed in I^n M for n=1 to 20.
for n in range(1, 21):
    xn = RElem(x**n, 0, {})
    assert xn * u_m(n) == v_elem, f"v_elem is not in I^{n} M"

# Conclusion: IN = N
# If the conclusion holds, then v_elem (which is in N) must be in IN.
# IN is the ideal generated by x_elem * v_elem.
# Any element in IN is of the form c * x_elem * v_elem for some c in R.
def in_IN(elem):
    if not elem.P.is_zero:
        return False
    if elem.B:
        return False
    # Check if Q is a multiple of x
    q, r = elem.Q.div(Poly(x, x, domain='QQ'))
    return r.is_zero

# Verify that v_elem is NOT in IN
conclusion_holds = in_IN(v_elem)
assert not conclusion_holds, "Conclusion IN = N holds, but it should fail!"

