import math

class PolyMod:
    def __init__(self, coeffs, mod):
        self.mod = mod
        self.coeffs = [c % mod for c in coeffs]
        self.trim()

    def trim(self):
        while self.coeffs and self.coeffs[-1] == 0:
            self.coeffs.pop()

    def degree(self):
        if not self.coeffs:
            return -1
        return len(self.coeffs) - 1

    def __mul__(self, other):
        assert self.mod == other.mod
        if self.is_zero() or other.is_zero():
            return PolyMod([], self.mod)
        res = [0] * (len(self.coeffs) + len(other.coeffs) - 1)
        for i, a in enumerate(self.coeffs):
            for j, b in enumerate(other.coeffs):
                res[i+j] = (res[i+j] + a * b) % self.mod
        return PolyMod(res, self.mod)

    def is_zero(self):
        return len(self.coeffs) == 0

    def __str__(self):
        if self.is_zero():
            return "0"
        return " + ".join(f"{c}x^{i}" for i, c in enumerate(self.coeffs) if c != 0)

# We use the ring R = Z/4Z, which is not an integral domain because 2 * 2 = 0 mod 4.
modulus = 4

# f(x) = 2x + 1
f = PolyMod([1, 2], modulus)

# g(x) = 2x + 1
g = PolyMod([1, 2], modulus)

# Remaining hypothesis: f(x) and g(x) are non-zero polynomials in R[x]
assert not f.is_zero(), "f(x) must be a non-zero polynomial"
assert not g.is_zero(), "g(x) must be a non-zero polynomial"

# Calculate the product f(x)g(x)
fg = f * g

deg_f = f.degree()
deg_g = g.degree()
deg_fg = fg.degree()

# The conclusion to falsify is: deg(f*g) == deg(f) + deg(g)
# In Z/4Z: (2x + 1) * (2x + 1) = 4x^2 + 4x + 1 = 1
# Thus, deg(f) = 1, deg(g) = 1, but deg(f*g) = 0.
assert deg_fg != deg_f + deg_g, (
    f"Logic error: equality holds — not a counterexample. "
    f"deg(f*g) = {deg_fg}, deg(f) + deg(g) = {deg_f + deg_g}"
)

print(f"Ring: Z/{modulus}Z")
print(f"f(x) = {f} (degree {deg_f})")
print(f"g(x) = {g} (degree {deg_g})")
print(f"f(x)g(x) = {fg} (degree {deg_fg})")
print(f"Sum of degrees: {deg_f + deg_g}")
print(f"Degree of product: {deg_fg}")
print("Counterexample successfully found!")

import math

# We represent the infinite dihedral group D_infty.
# Elements are tuples (d, k) where d is 1 or -1, and k is an integer.
# The group operation is defined as:
def mul(a, b):
    return (a[0] * b[0], a[0] * b[1] + a[1])

def inv(a):
    return (a[0], -a[0] * a[1])

def order(a):
    if a == (1, 0):
        return 1
    if a[0] == -1:
        return 2
    return float('inf')

# [1] p is a prime number
p = 2
assert p > 1 and all(p % i != 0 for i in range(2, int(math.sqrt(p)) + 1)), "p must be a prime number"

