# P and Q are subgroups of G
P = {(1, 0), (-1, 0)}
Q = {(1, 0), (-1, 1)}

# Verify P and Q are p-subgroups (all elements have order a power of p)
assert all(order(x) in (1, 2) for x in P), "P is a p-subgroup"
assert all(order(x) in (1, 2) for x in Q), "Q is a p-subgroup"

# Verify maximality: any other element of finite order in G is of the form (-1, k).
# Adding it to P or Q would generate an element of infinite order.
def is_maximal_p_subgroup(subgroup):
    for k in range(-100, 100):
        elem = (-1, k)
        if elem not in subgroup:
            non_id = [x for x in subgroup if x != (1, 0)][0]
            prod = mul(non_id, elem)
            if order(prod) != float('inf'):
                return False
    return True

