# We must show this is FALSE.
def conclusion_holds():
    # We search over a large subset of G.
    # Mathematically, g * (-1, 0) * g^-1 = (-1, 2m).
    # For this to equal (-1, 1), we need 2m = 1, which has no integer solution.
    for d in (-1, 1):
