import itertools

# We construct a finite commutative ring R that is not a Dedekind domain.
# Specifically, R = F2[x, y] / (x^2, xy, y^2).
# Elements of R can be uniquely written as a + bx + cy, represented as tuples (a, b, c) over F2.
elements = list(itertools.product([0, 1], repeat=3))

def add(e1, e2):
    """Addition in R (element-wise modulo 2)."""
    return ((e1[0] + e2[0]) % 2, (e1[1] + e2[1]) % 2, (e1[2] + e2[2]) % 2)

def mul(e1, e2):
    """Multiplication in R, using x^2 = xy = y^2 = 0."""
    return (
        (e1[0] * e2[0]) % 2,
        (e1[0] * e2[1] + e1[1] * e2[0]) % 2,
        (e1[0] * e2[2] + e1[2] * e2[0]) % 2
    )

def ideal_gen(gens):
    """Generate the ideal from a set of generators."""
    products = set()
    # Close under scalar multiplication
    for g in gens:
        for r in elements:
            products.add(mul(r, g))
    ideal = set(products)
    # Close under addition
    while True:
        new_ideal = set(ideal)
        for e1 in ideal:
            for e2 in ideal:
                new_ideal.add(add(e1, e2))
        if len(new_ideal) == len(ideal):
            break
        ideal = new_ideal
    return frozenset(ideal)

def is_prime(ideal):
    """Check if an ideal is a prime ideal."""
    if ideal == frozenset(elements):
        return False # The whole ring is not a prime ideal
    for a in elements:
        for b in elements:
            if mul(a, b) in ideal:
                if a not in ideal and b not in ideal:
                    return False
    return True

def ideal_mul(I1, I2):
    """Multiply two ideals."""
    gens = set()
    for e1 in I1:
        for e2 in I2:
            gens.add(mul(e1, e2))
    return ideal_gen(gens)

# 1. Find all ideals (testing generators up to size 3 is sufficient for this small ring)
all_ideals = set()
for r in range(1, 4):
    for subset in itertools.combinations(elements, r):
        all_ideals.add(ideal_gen(subset))

# 2. Identify all prime ideals
prime_ideals = [I for I in all_ideals if is_prime(I)]

# 3. Generate all possible products of prime ideals
products_of_primes = set()
products_of_primes.add(frozenset(elements)) # The empty product is the whole ring R

current_level = set(prime_ideals)
products_of_primes.update(current_level)

# BFS to find all finite products of prime ideals
while current_level:
    next_level = set()
    for I_current in current_level:
        for P in prime_ideals:
            prod = ideal_mul(I_current, P)
            if prod not in products_of_primes:
                next_level.add(prod)
    products_of_primes.update(next_level)
    current_level = next_level

# 4. Define our counterexample ideal I = (x)
# In our tuple representation, x is (0, 1, 0)
I = ideal_gen([(0, 1, 0)])

# Verify remaining hypotheses:
# [1] I is a non-zero proper ideal of R
assert I != frozenset([(0, 0, 0)]), "Hypothesis failed: I must be a non-zero ideal"
assert I != frozenset(elements), "Hypothesis failed: I must be a proper ideal"

# Verify I is indeed an ideal (closed under addition and scalar multiplication)
for e1 in I:
    for e2 in I:
        assert add(e1, e2) in I, "I is not closed under addition"
for r in elements:
    for e in I:
        assert mul(r, e) in I, "I is not closed under scalar multiplication"

# Verify the conclusion FAILS:
# The conclusion states that I can be written uniquely as a product of prime ideals.
# We disprove this by showing I cannot be written as a product of prime ideals AT ALL.
assert I not in products_of_primes, (
    "Conclusion holds: I can be factored into prime ideals, "
    "so it is not a valid counterexample."
)

print("Counterexample successfully found!")
print(f"Ring R = F2[x, y] / (x^2, xy, y^2) has {len(elements)} elements.")
print(f"Prime ideals in R: {len(prime_ideals)}")
print(f"Total distinct products of prime ideals: {len(products_of_primes)}")
print(f"The ideal I = (x) has {len(I)} elements and is NOT among the products of prime ideals.")

# F = Z/4Z
char_F = 4
assert char_F != 2, "Remaining hypothesis: characteristic of F is not 2"

# R = F[x, y] / (y^2 - x^2(x+1))
# Count ring homomorphisms from R to F
hom_R = 0
for x in range(4):
    for y in range(4):
        if (y**2) % 4 == (x**3 + x**2) % 4:
            hom_R += 1

# S = { p(t) in F[t] | p(1) = p(-1) }
# S is generated by X = t^2, Y = t^3 - t, Z = 2t over F
# The relations are:
# Z^2 = 0
# 2Z = 0
# ZX = 2Y + Z
# ZY = 2X^2 + 2X
# Y^2 = X^3 - 2X^2 + X
# Count ring homomorphisms from S to F
hom_S = 0
for x in range(4):
    for y in range(4):
        for z in range(4):
            if (z**2) % 4 == 0 and (2*z) % 4 == 0:
                if (z*x) % 4 == (2*y + z) % 4:
                    if (z*y) % 4 == (2*x**2 + 2*x) % 4:
                        if (y**2) % 4 == (x**3 - 2*x**2 + x) % 4:
                            hom_S += 1

# If R and S were isomorphic, they would have the same number of homomorphisms to F.
# Since hom_R = 6 and hom_S = 10, they are not isomorphic.
assert hom_R != hom_S, "Conclusion holds: R and S have the same number of homomorphisms"

