class Z_sqrt_minus_5_element:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def __mul__(self, other):
        return Z_sqrt_minus_5_element(
            self.a * other.a - 5 * self.b * other.b,
            self.a * other.b + self.b * other.a
        )

    def __eq__(self, other):
        if not isinstance(other, Z_sqrt_minus_5_element):
            return False
        return self.a == other.a and self.b == other.b

    def norm(self):
        return self.a**2 + 5 * self.b**2

    def is_unit(self):
        return self.norm() == 1

    def __repr__(self):
        return f"({self.a} + {self.b}*sqrt(-5))"

def has_element_of_norm(n):
    if n < 0:
        return False
    max_b = int(math.sqrt(n / 5.0))
    for b in range(-max_b - 1, max_b + 2):
        rem = n - 5 * b**2
        if rem >= 0:
            a = int(math.sqrt(rem))
            if a**2 == rem:
                return True
    return False

def is_irreducible(x: Z_sqrt_minus_5_element):
    if x.is_unit() or x.norm() == 0:
        return False
    n = x.norm()
    for d in range(2, n):
        if n % d == 0:
            if has_element_of_norm(d):
                return False
    return True

def are_associates(x: Z_sqrt_minus_5_element, y: Z_sqrt_minus_5_element):
    units = [Z_sqrt_minus_5_element(1, 0), Z_sqrt_minus_5_element(-1, 0)]
    for u in units:
        if x == u * y:
            return True
    return False

