import itertools

class BooleanRingElement:
    """
    Represents an element in the Boolean ring of finite and cofinite subsets of N.
    Addition is symmetric difference, multiplication is intersection.
    """
    def __init__(self, exceptions, is_cofinite):
        self.exceptions = frozenset(exceptions)
        self.is_cofinite = is_cofinite

    def __add__(self, other):
        if self.is_cofinite == other.is_cofinite:
            return BooleanRingElement(self.exceptions ^ other.exceptions, False)
        else:
            return BooleanRingElement(self.exceptions ^ other.exceptions, True)

    def __mul__(self, other):
        if not self.is_cofinite and not other.is_cofinite:
            return BooleanRingElement(self.exceptions & other.exceptions, False)
        elif self.is_cofinite and not other.is_cofinite:
            return BooleanRingElement(other.exceptions - self.exceptions, False)
        elif not self.is_cofinite and other.is_cofinite:
            return BooleanRingElement(self.exceptions - other.exceptions, False)
        else:
            return BooleanRingElement(self.exceptions | other.exceptions, True)

    def __eq__(self, other):
        if not isinstance(other, BooleanRingElement):
            return False
        return self.is_cofinite == other.is_cofinite and self.exceptions == other.exceptions

    def __hash__(self):
        return hash((self.exceptions, self.is_cofinite))

    def __repr__(self):
        if self.is_cofinite:
            return f"N \\ {set(self.exceptions)}"
        else:
            return f"{set(self.exceptions)}"

