# Counterexample: The ring Z/6Z
# It satisfies the hypothesis that every non-zero non-unit is a finite product of prime elements,
# but it is not a Unique Factorization Domain (UFD) because it is not an integral domain,
# and furthermore, it lacks any irreducible elements.

elements = [0, 1, 2, 3, 4, 5]

def mul(a, b):
    return (a * b) % 6

def is_unit(a):
    return any(mul(a, b) == 1 for b in elements)

def divides(a, b):
    """Returns True if a divides b in Z/6Z (i.e., exists c such that a*c = b)"""
    return any(mul(a, c) == b for c in elements)

def is_prime(p):
    """
    An element p is prime if it is non-zero, non-unit,
    and whenever p divides ab, p divides a or p divides b.
    """
    if p == 0 or is_unit(p):
        return False
    for a in elements:
        for b in elements:
            if divides(p, mul(a, b)):
                if not divides(p, a) and not divides(p, b):
                    return False
    return True

# Identify primes and non-zero non-units in Z/6Z
primes = [p for p in elements if is_prime(p)]
non_zero_non_units = [x for x in elements if x != 0 and not is_unit(x)]

# REMAINING HYPOTHESIS: Every non-zero non-unit element of R can be written as a finite product of prime elements.
# In Z/6Z, the primes are exactly 2, 3, and 4.
# The non-zero non-units are also exactly 2, 3, and 4.
# Thus, every non-zero non-unit is trivially a product of 1 prime element.
hypothesis_holds = all(x in primes for x in non_zero_non_units)
assert hypothesis_holds, "Hypothesis failed: not all non-zero non-units are products of primes."

# CONCLUSION TO FALSIFY: R is a unique factorization domain.
# A UFD must be an integral domain. We check if Z/6Z is an integral domain.
def is_integral_domain():
    for a in elements:
        if a != 0:
            for b in elements:
                if b != 0 and mul(a, b) == 0:
                    return False
    return True

is_ufd = is_integral_domain()

# The conclusion MUST FAIL (Z/6Z has zero divisors, e.g., 2 * 3 = 0)
assert not is_ufd, "Conclusion holds: R is an integral domain, so it might be a UFD."

# Further demonstration: In a UFD, elements factor into irreducibles.
# Let's show Z/6Z has NO irreducible elements whatsoever.
def is_irreducible(x):
    if x == 0 or is_unit(x):
        return False
    # x is irreducible if x = a * b implies a is a unit or b is a unit
    for a in elements:
        for b in elements:
            if mul(a, b) == x:
                if not is_unit(a) and not is_unit(b):
                    return False
    return True

