assert not has_irreducibles, "Z/6Z has irreducibles, which is unexpected."

print("Counterexample verified: Z/6Z satisfies the hypothesis but is not a UFD.")

import sympy
from sympy import symbols

# We construct a commutative local ring R which is NOT Noetherian.
# R = k[X, Y] (+) M, where M is an ideal with M^2 = 0.
# M is a k-vector space with basis {z_n | n in Z}.
# The action of X and Y on M is given by:
# X * z_n = z_{n-1}
# Y * z_n = 0
# The maximal ideal of R is m = (X, Y) (+) M.

X, Y = symbols('X Y')

class RingElement:
    def __init__(self, poly, m_dict=None):
        self.poly = sympy.expand(poly)
        self.m = {}
        if m_dict:
            for k, v in m_dict.items():
                if v != 0:
                    self.m[k] = v

    def __add__(self, other):
        new_poly = self.poly + other.poly
        new_m = self.m.copy()
        for k, v in other.m.items():
            new_m[k] = new_m.get(k, 0) + v
        return RingElement(new_poly, new_m)

    def __neg__(self):
        return RingElement(-self.poly, {k: -v for k, v in self.m.items()})

    def __sub__(self, other):
        return self + (-other)

    def __mul__(self, other):
        new_poly = self.poly * other.poly

        def apply_poly(poly, m_dict):
            poly = sympy.expand(poly)
            if poly == 0: return {}
            res = {}
            # Y annihilates M, so we substitute Y = 0
            poly_x = sympy.expand(poly.subs(Y, 0))
            if poly_x == 0: return res
            coeffs = poly_x.as_coefficients_dict()
            for term, c in coeffs.items():
                deg = 0 if term == 1 else sympy.degree(term, X)
                for k, v in m_dict.items():
                    res[k - deg] = res.get(k - deg, 0) + c * v
            return res

        m1 = apply_poly(self.poly, other.m)
        m2 = apply_poly(other.poly, self.m)
        for k, v in m2.items():
            m1[k] = m1.get(k, 0) + v
        return RingElement(new_poly, m1)

    def __eq__(self, other):
        if sympy.simplify(self.poly - other.poly) != 0:
            return False
        all_keys = set(self.m.keys()).union(other.m.keys())
        for k in all_keys:
            if self.m.get(k, 0) != other.m.get(k, 0):
                return False
        return True

