import itertools

class WreathElement:
    """An element of the wreath product Z wr Z."""
    def __init__(self, shift, values):
        self.shift = shift
        self.values = {k: v for k, v in values.items() if v != 0}

    def __mul__(self, other):
        new_values = dict(self.values)
        for k, v in other.values.items():
            shifted_k = k + self.shift
            new_values[shifted_k] = new_values.get(shifted_k, 0) + v
        return WreathElement(self.shift + other.shift, new_values)

    def inv(self):
        new_values = {}
        for k, v in self.values.items():
            new_values[k - self.shift] = -v
        return WreathElement(-self.shift, new_values)

    def __eq__(self, other):
        if not isinstance(other, WreathElement):
            return False
        return self.shift == other.shift and self.values == other.values

class WreathProductGroup:
    """The group G = Z wr Z."""
    def __init__(self):
        # G is generated by a shift and a single element in the base group
        self.a = WreathElement(1, {})
        self.b = WreathElement(0, {0: 1})
        self.generators = [self.a, self.b]

    @property
    def is_finitely_generated(self):
        # G is generated by the finite set {a, b}
        return True

class BaseSubgroup:
    """The subgroup H of elements with shift == 0. (Isomorphic to Direct Sum of Z)"""
    def contains(self, elem):
        return elem.shift == 0

    @property
    def is_subgroup(self):
        # The set of elements with shift == 0 is the kernel of the homomorphism 
        # mapping WreathElement to its shift, hence it is a normal subgroup.
        return True

    def can_be_generated_by(self, finite_subset):
        """
        A mathematical check showing that no finite subset can generate this subgroup.
        """
        for elem in finite_subset:
            if not self.contains(elem):
                return False

        support = set()
        for elem in finite_subset:
            support.update(elem.values.keys())

        missing_idx = max(support) + 1 if support else 0
        target = WreathElement(0, {missing_idx: 1})

        # Target is in the subgroup
        assert self.contains(target)

        # Because elements in finite_subset all have shift == 0, any product of them
        # can only have non-zero values at indices within `support`.
        # Therefore, `target` cannot be generated by `finite_subset`.
        return False

    @property
    def is_finitely_generated(self):
        # Since no finite subset can generate it, it is not finitely generated.
        return False

# Instantiate the groups
G = WreathProductGroup()
H = BaseSubgroup()

