import itertools

class Z_n:
    def __init__(self, n):
        self.n = n
        self.elements = list(range(n))

    def add(self, a, b):
        return (a + b) % self.n

    def mul(self, a, b):
        return (a * b) % self.n

    def get_ideals(self):
        ideals = []
        for i in self.elements:
            ideal = set()
            for r in self.elements:
                ideal.add(self.mul(r, i))
            if ideal not in ideals:
                ideals.append(ideal)
        return ideals

    def is_simple_module(self, module_elements):
        """
        A module is simple if it is non-zero and has no proper non-zero submodules.
        Since Z_n is a principal ideal ring, any submodule is generated by a single element.
        """
        if len(module_elements) <= 1:
            return False
        for i in module_elements:
            if i == 0: 
                continue
            submodule = set()
            for r in self.elements:
                submodule.add(self.mul(r, i))
            # If the cyclic submodule is strictly between {0} and the whole module
            if 1 < len(submodule) < len(module_elements):
                return False
        return True

    def get_socle(self):
        """
        The socle of R is the sum of all its simple ideals.
        """
        ideals = self.get_ideals()
        simple_ideals = [I for I in ideals if self.is_simple_module(I)]
        socle = {0}
        for I in simple_ideals:
            new_socle = set()
            for a in socle:
                for b in I:
                    new_socle.add(self.add(a, b))
            socle = new_socle
        return socle

    def is_self_injective(self):
        """
        Baer's criterion: R is self-injective if every R-module homomorphism 
        from an ideal I to R can be extended to a homomorphism from R to R.
        Equivalently, every homomorphism f: I -> R is given by multiplication by some c in R.
        """
        ideals = self.get_ideals()
        for I in ideals:
            if len(I) == self.n:
                continue # The whole ring is trivially self-injective

            I_list = list(I)
            # Iterate over all possible functions f: I -> R
            for f_vals in itertools.product(self.elements, repeat=len(I_list)):
                f = dict(zip(I_list, f_vals))

                # Check if f is an R-module homomorphism
                is_hom = True
                for a in I_list:
                    for b in I_list:
                        if f[self.add(a, b)] != self.add(f[a], f[b]):
                            is_hom = False
                            break
                    if not is_hom: 
                        break
                    for r in self.elements:
                        if f[self.mul(r, a)] != self.mul(r, f[a]):
                            is_hom = False
                            break
                    if not is_hom: 
                        break

                # If f is a homomorphism, it must be principal (multiplication by c)
                if is_hom:
                    is_principal = False
                    for c in self.elements:
                        if all(f[a] == self.mul(c, a) for a in I_list):
                            is_principal = True
                            break
                    if not is_principal:
                        return False
        return True

    def is_quasi_frobenius(self):
        # A finite ring is Artinian. We only need to check self-injectivity.
        return self.is_self_injective()

# Counterexample: R = Z_6
# Z_6 is a commutative Artinian ring, but NOT local (it has two maximal ideals).
R = Z_n(6)

is_qf = R.is_quasi_frobenius()
socle = R.get_socle()
is_socle_simple = R.is_simple_module(socle)

# Verification of the counterexample
assert is_qf, "Z_6 is self-injective and Artinian, so it is quasi-Frobenius"
assert not is_socle_simple, "The socle of Z_6 is Z_6 itself, which is not a simple module"

# The conclusion states: R is quasi-Frobenius iff its socle is a simple R-module
conclusion_holds = (is_qf == is_socle_simple)

# Disprove the conclusion
assert not conclusion_holds, "The biconditional conclusion fails for Z_6"

