import sympy as sp

class Quaternion:
    """
    A class representing Quaternions over the Rationals.
    This serves as our counterexample ring R.
    """
    def __init__(self, r, i, j, k):
        self.r = sp.sympify(r)
        self.i = sp.sympify(i)
        self.j = sp.sympify(j)
        self.k = sp.sympify(k)

    def __add__(self, other):
        return Quaternion(self.r + other.r, self.i + other.i, self.j + other.j, self.k + other.k)

    def __sub__(self, other):
        return Quaternion(self.r - other.r, self.i - other.i, self.j - other.j, self.k - other.k)

    def __mul__(self, other):
        r = self.r*other.r - self.i*other.i - self.j*other.j - self.k*other.k
        i = self.r*other.i + self.i*other.r + self.j*other.k - self.k*other.j
        j = self.r*other.j - self.i*other.k + self.j*other.r + self.k*other.i
        k = self.r*other.k + self.i*other.j - self.j*other.i + self.k*other.r
        return Quaternion(r, i, j, k)

    def __eq__(self, other):
        if isinstance(other, Quaternion):
            return self.r == other.r and self.i == other.i and self.j == other.j and self.k == other.k
        try:
            return self.r == other and self.i == 0 and self.j == 0 and self.k == 0
        except Exception:
            return False

    def __ne__(self, other):
        return not self.__eq__(other)

    def norm_sq(self):
        return self.r**2 + self.i**2 + self.j**2 + self.k**2

    def inverse(self):
        n = self.norm_sq()
        if n == 0:
            raise ZeroDivisionError("Cannot invert zero quaternion")
        return Quaternion(self.r/n, -self.i/n, -self.j/n, -self.k/n)

    def __repr__(self):
        return f"Quaternion({self.r}, {self.i}, {self.j}, {self.k})"

# We verify the properties on a representative set of elements of the Rational Quaternions.
# Since Wedderburn's little theorem states that all finite division rings are fields, 
# we MUST use an infinite non-commutative division ring (like the Quaternions) and verify 
# its properties computationally on a sample.
elements = [
    Quaternion(0, 0, 0, 0),
    Quaternion(1, 0, 0, 0),
    Quaternion(0, 1, 0, 0),
    Quaternion(0, 0, 1, 0),
    Quaternion(0, 0, 0, 1),
    Quaternion(1, 2, 3, 4),
    Quaternion(-1, 0, 2, -3),
    Quaternion(5, -2, -2, 5),
    Quaternion(1, -1, 1, -1)
]

# ---------------------------------------------------------------------------
# HYPOTHESIS 1: R is a local ring
# ---------------------------------------------------------------------------
# A non-commutative ring is local if the set of its non-units forms an ideal.
# In a division ring, the only non-unit is 0, and {0} is trivially an ideal.
# We verify that every non-zero element in our sample is a unit.
for e in elements:
    if e != 0:
        inv = e.inverse()
        assert e * inv == 1, f"Local ring check failed: {e} has no right inverse"
        assert inv * e == 1, f"Local ring check failed: {e} has no left inverse"

# ---------------------------------------------------------------------------
# HYPOTHESIS 2: R is a von Neumann regular ring
# ---------------------------------------------------------------------------
# The prompt defines this as: for every a in R, there exists x in R such that a = a^2 x.
for a in elements:
    if a == 0:
        x = Quaternion(0, 0, 0, 0)
    else:
        x = a.inverse()

    assert a == (a * a) * x, f"Von Neumann regularity fails for {a}"

# ---------------------------------------------------------------------------
# CONCLUSION TO FALSIFY: R is a field
# ---------------------------------------------------------------------------
# A field must be a commutative division ring.
# We verify that the conclusion is FALSE by showing R is NOT commutative.
def is_field(ring_elements):
    for a in ring_elements:
        for b in ring_elements:
            if a * b != b * a:
                return False  # Non-commutative -> Not a field
    return True

# The critical negation assertion: R is NOT a field
assert not is_field(elements), "The conclusion holds (R is a field), which means this is not a counterexample!"

# Explicitly asserting the negation of commutativity for specific elements
i = Quaternion(0, 1, 0, 0)
j = Quaternion(0, 0, 1, 0)
assert i * j != j * i, "Quaternions i and j should not commute"

print("Counterexample successfully verified!")
print("The ring of Rational Quaternions is a local, von Neumann regular ring, but NOT a field.")

import math

# Define the set X and subset Y
X = {1, 2}
Y = {1}
X_minus_Y = X - Y

# Define the monoid G acting on X
# We represent elements of G as dictionaries (functions from X to X)
e = {1: 1, 2: 2}
g = {1: 1, 2: 1}

G = [e, g]

# Action of G on an element of X
def apply_action(f, x):
    return f[x]

# Action of G on a subset of X
def act_set(f, subset):
    return {apply_action(f, x) for x in subset}

# Remaining hypotheses
# [1] X is a set on which G acts (G is a monoid acting on X)
# Check identity axiom
for x in X:
    assert apply_action(e, x) == x

# Check compatibility axiom (and that G is closed under composition)
def compose(f1, f2):
    return {x: f1[f2[x]] for x in X}

for f1 in G:
    for f2 in G:
        f12 = compose(f1, f2)
        assert f12 in G, "G must be closed under composition"
        for x in X:
            assert apply_action(f12, x) == apply_action(f1, apply_action(f2, x))

# [2] Y is a subset of X
assert Y.issubset(X)

# Conclusion check
# Setwise stabilizer of Y in G: {f in G | f(Y) == Y}
stab_Y = [f for f in G if act_set(f, Y) == Y]

# Setwise stabilizer of X \ Y in G: {f in G | f(X \ Y) == X \ Y}
stab_X_minus_Y = [f for f in G if act_set(f, X_minus_Y) == X_minus_Y]

# The conclusion is that these two stabilizers are equal.
# We assert that they are NOT equal to provide a counterexample.
assert stab_Y != stab_X_minus_Y, "Conclusion holds, not a counterexample"

print("Counterexample found!")
print(f"X = {X}")
print(f"Y = {Y}")
print(f"X \\ Y = {X_minus_Y}")
print(f"Stabilizer of Y: {stab_Y}")
print(f"Stabilizer of X \\ Y: {stab_X_minus_Y}")

