import itertools

# G is the group Z_3 (integers modulo 3 under addition)
G = [0, 1, 2]

# Y is the set Z_3
Y = [0, 1, 2]

# Action of G on Y: addition modulo 3
def action_Y(g, y):
    return (g + y) % 3

# H is a subset of G, but NOT a subgroup (this is the dropped hypothesis)
H = [1]

# Define the set of left cosets of H in G
# Even though H is not a subgroup, the left translate gH is well-defined
def coset(g, H):
    return frozenset((g + h) % 3 for h in H)

G_mod_H = {coset(g, H) for g in G}

# Action of G on G/H: natural left multiplication (addition here)
def action_G_mod_H(g, c):
    return frozenset((g + x) % 3 for x in c)

# --- Verify Remaining Hypotheses ---

# [1] Let G be a group acting on a set Y.
def is_group_action(G, action, X):
    # Identity element is 0
    for x in X:
        if action(0, x) != x:
            return False
    # Compatibility: g1 * (g2 * x) = (g1 + g2) * x
    for g1 in G:
        for g2 in G:
            for x in X:
                if action((g1 + g2) % 3, x) != action(g1, action(g2, x)):
                    return False
    return True

assert is_group_action(G, action_Y, Y), "Hypothesis [1] fails: action_Y is not a valid group action"

# [2] Let G/H be the set of left cosets of H in G, equipped with the natural left multiplication action by G.
assert is_group_action(G, action_G_mod_H, G_mod_H), "Hypothesis [2] fails: action_G_mod_H is not a valid group action"

# --- Evaluate Conclusion ---

# Find all G-equivariant maps from G/H to Y
equivariant_maps = []
G_mod_H_list = list(G_mod_H)

for values in itertools.product(Y, repeat=len(G_mod_H_list)):
    map_f = dict(zip(G_mod_H_list, values))

    is_equivariant = True
    for g in G:
        for c in G_mod_H_list:
            if map_f[action_G_mod_H(g, c)] != action_Y(g, map_f[c]):
                is_equivariant = False
                break
        if not is_equivariant:
            break

    if is_equivariant:
        equivariant_maps.append(map_f)

# Find the set of fixed points Y^H
# Y^H = { y in Y | h * y = y for all h in H }
Y_H = []
for y in Y:
    is_fixed = True
    for h in H:
        if action_Y(h, y) != y:
            is_fixed = False
            break
    if is_fixed:
        Y_H.append(y)

