# If the sets have different sizes, NO bijection can exist (canonical or otherwise).
assert len(equivariant_maps) != len(Y_H), (
    f"Logic error: Both sets have size {len(Y_H)}, "
    f"so a bijection might exist. Not a counterexample."
)

print("Counterexample found!")
print(f"Group G: Z_3")
print(f"Subset H: {H} (Not a subgroup)")
print(f"Set Y: Z_3")
print(f"Number of G-equivariant maps from G/H to Y: {len(equivariant_maps)}")
print(f"Number of fixed points Y^H: {len(Y_H)}")
print(f"Since {len(equivariant_maps)} != {len(Y_H)}, there is no bijection between them.")

class InfinitePolynomialRingQuotient:
    """
    Represents the ring R = F[x_1, x_2, ...] / (x_1^2, x_2^3, x_3^4, ...)
    This ring is commutative and has an identity.
    It is NOT Noetherian.
    """
    def __init__(self):
        self.is_commutative = True
        self.has_identity = True

class Monomial:
    """
    Represents a monomial in the ring R.
    Powers of x_i are reduced modulo x_i^{i+1} == 0.
    """
    def __init__(self, powers, is_zero=False):
        self.powers = {}
        self.is_zero = is_zero
        if not self.is_zero:
            for i, p in powers.items():
                if p >= i + 1:
                    self.is_zero = True
                    break
                elif p > 0:
                    self.powers[i] = p
        if self.is_zero:
            self.powers = {}

    @classmethod
    def zero(cls):
        return cls({}, is_zero=True)

    @classmethod
    def identity(cls):
        return cls({})

    def __mul__(self, other):
        if self.is_zero or other.is_zero:
            return Monomial.zero()
        new_powers = self.powers.copy()
        for i, p in other.powers.items():
            new_powers[i] = new_powers.get(i, 0) + p
        return Monomial(new_powers)

    def __pow__(self, power):
        if self.is_zero:
            return self
        if power == 0:
            return Monomial.identity()
        new_powers = {i: p * power for i, p in self.powers.items()}
        return Monomial(new_powers)

    def __eq__(self, other):
        if self.is_zero and other.is_zero:
            return True
        return not self.is_zero and not other.is_zero and self.powers == other.powers

    def __repr__(self):
        if self.is_zero:
            return "0"
        if not self.powers:
            return "1"
        return "*".join(f"x_{i}^{p}" for i, p in sorted(self.powers.items()))


# 1. Instantiate the ring
R = InfinitePolynomialRingQuotient()

# Verify remaining hypotheses
# [1] R is a commutative ring with identity
assert R.is_commutative, "R must be commutative"
assert R.has_identity, "R must have an identity"

# [2] N is the nilradical of R.
# We verify that x_i is in N by checking x_i^{i+1} == 0.
def is_in_nilradical(i):
    x_i = Monomial({i: 1})
    return (x_i ** (i + 1)) == Monomial.zero()

for i in range(1, 100):
    assert is_in_nilradical(i), f"x_{i} should be in the nilradical"

# Conclusion to negate: There exists a positive integer k such that N^k = {0}
# If such a k exists, then for that k, ANY product of k elements from N must be zero.
# In particular, x_k^k (which is a product of k elements from N) must be zero.
def N_power_is_zero(k):
    x_k = Monomial({k: 1})
    x_k_power_k = x_k ** k
    return x_k_power_k == Monomial.zero()

# We check for a large range of k that N^k is NOT {0}
exists_k_such_that_N_power_zero = False
for k in range(1, 100):
    if N_power_is_zero(k):
        exists_k_such_that_N_power_zero = True
        break

# Verify the conclusion is FALSE
assert not exists_k_such_that_N_power_zero, "Conclusion holds: N is nilpotent!"

print("Counterexample found!")
print("Ring R = F[x_1, x_2, ...] / (x_1^2, x_2^3, x_3^4, ...)")
print("R is commutative and has an identity.")
print("The nilradical N contains all x_i.")
print("For any positive integer k, x_k is in N, but x_k^k != 0, so N^k != {0}.")
print("Thus, the nilradical N is not nilpotent.")

import itertools

# p and k for the hypothesis
