def mult_S3(x, y):
    i1, j1 = x
    i2, j2 = y
    return ((i1 + ((-1)**j1) * i2) % 3, (j1 + j2) % 2)

# Elements of G = S3 x S3 are pairs (x, y) where x, y in S3
G = list(itertools.product(S3_elements, S3_elements))
G_idx = {g: idx for idx, g in enumerate(G)}

def mult_G(u, v):
    return (mult_S3(u[0], v[0]), mult_S3(u[1], v[1]))

# Multiplication table for G
N = len(G)
mult_table = [[0] * N for _ in range(N)]
for idx1, u in enumerate(G):
    for idx2, v in enumerate(G):
        mult_table[idx1][idx2] = G_idx[mult_G(u, v)]

def group_order(g_idx):
    curr = g_idx
    order = 1
    while curr != 0: # 0 is identity because G[0] = ((0,0), (0,0))
        curr = mult_table[curr][g_idx]
        order += 1
    return order

# Find elements of specific orders to use as candidates for h1, h2, h3, h4
order_3 = [i for i in range(N) if group_order(i) == 3]
order_2 = [i for i in range(N) if group_order(i) == 2]

def generate_subgroup_size(gens):
    visited = {0}
    queue = [0]
    while queue:
        curr = queue.pop(0)
        for g in gens:
            nxt = mult_table[curr][g]
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return len(visited)

aut_count = 0
for h1 in order_3:
    for h3 in order_3:
        if mult_table[h1][h3] != mult_table[h3][h1]:
            continue
        for h2 in order_2:
            if mult_table[h2][h3] != mult_table[h3][h2]:
                continue
            if mult_table[mult_table[h2][h1]][h2] != mult_table[h1][h1]:
