assert N == p**k, f"|G| must be {p}^{k} = {p**k}, but is {N}"
assert k >= 2, "k must be >= 2"

# Conclusion: Out(G) contains an element of order p, implying p divides |Out(G)|
# We assert that p DOES NOT divide |Out(G)|, meaning it cannot contain an element of order p.
assert not (out_count % p == 0), f"Conclusion holds! p={p} divides |Out(G)|={out_count}"

print("Counterexample found!")
print(f"p = {p}, k = {k}, |G| = {N}")
print(f"|Aut(G)| = {aut_count}")
print(f"|Inn(G)| = {inn_count}")
print(f"|Out(G)| = {out_count}")
print(f"{p} does not divide {out_count}, so Out(G) cannot have an element of order {p}.")

