import math

class ToeplitzElement:
    def __init__(self, terms):
        self.terms = {}
        for (i, j), c in terms.items():
            if c != 0:
                self.terms[(i, j)] = c

    def __add__(self, other):
        res = self.terms.copy()
        for (i, j), c in other.terms.items():
            res[(i, j)] = res.get((i, j), 0) + c
        return ToeplitzElement(res)

    def __mul__(self, other):
        res = {}
        for (i1, j1), c1 in self.terms.items():
            for (i2, j2), c2 in other.terms.items():
                # Multiplication rule for the bicyclic monoid: A^j B^i
                if i2 >= j1:
                    new_i = i1 + i2 - j1
                    new_j = j2
                else:
                    new_i = i1
                    new_j = j2 + j1 - i2
                res[(new_i, new_j)] = res.get((new_i, new_j), 0) + c1 * c2
        return ToeplitzElement(res)

    def __eq__(self, other):
        d1 = {k: v for k, v in self.terms.items() if v != 0}
        d2 = {k: v for k, v in other.terms.items() if v != 0}
        return d1 == d2

    def __hash__(self):
        d = {k: v for k, v in self.terms.items() if v != 0}
        return hash(frozenset(d.items()))

# We construct the Toeplitz algebra (or bicyclic monoid ring) over the integers.
