class Element:
    """
    Represents an element in the infinite ring R = F_2[x_1, x_2, ...] / (x_1^2, x_2^2, ...)
    Terms are represented as a frozenset of frozensets of integers.
    Each integer represents the index of a variable x_i.
    """
    def __init__(self, terms):
        self.terms = frozenset(frozenset(t) for t in terms)

    def __mul__(self, other):
        res = set()
        for t1 in self.terms:
            for t2 in other.terms:
                # In this ring, x_i^2 = 0. So if terms share a variable, their product is 0.
                if not t1.intersection(t2):
                    # Characteristic is 2, so addition is symmetric difference.
                    res.symmetric_difference_update([t1.union(t2)])
        return Element(res)

    def is_zero(self):
        return len(self.terms) == 0

    def max_var(self):
        if not self.terms:
            return 0
        return max((max(t) for t in self.terms if t), default=0)

    def __str__(self):
        if self.is_zero():
            return "0"
        term_strs = []
        for t in sorted(list(self.terms), key=lambda x: sorted(list(x))):
            if not t:
                term_strs.append("1")
            else:
                term_strs.append("".join(f"x_{i}" for i in sorted(list(t))))
        return " + ".join(term_strs)

