        return False
    # Check closure under addition
    for x in ideal:
        for y in ideal:
            if (x + y) % 6 not in ideal:
                return False
    # Check closure under multiplication by any ring element
    for x in ideal:
        for r in ring:
            if (x * r) % 6 not in ideal:
                return False
    return True

