    e = G.id()
    for a in G.elements:
        assert G.op(e, a) == a
        assert G.op(a, e) == a
    for a in G.elements:
        inv_a = G.inv(a)
        assert G.op(a, inv_a) == e
        assert G.op(inv_a, a) == e
    return True

