import itertools

class LocalRing:
    """
    Represents the ring R = F2[x, y] / (x^2, xy, y^2)
    Elements are represented as (a, b, c) corresponding to a + bx + cy.
    This is an Artinian local ring, not an integral domain, and not a principal ideal ring.
    """
    def __init__(self):
        self.elements = list(itertools.product((0, 1), repeat=3))
        self.n = 8

    def add(self, e1, e2):
        return ((e1[0] + e2[0]) % 2, (e1[1] + e2[1]) % 2, (e1[2] + e2[2]) % 2)

    def mul(self, e1, e2):
        a1, b1, c1 = e1
        a2, b2, c2 = e2
        a = (a1 * a2) % 2
        b = (a1 * b2 + b1 * a2) % 2
        c = (a1 * c2 + c1 * a2) % 2
        return (a, b, c)

    def get_ideals(self):
        ideals = []
        for i in range(1, 1 << self.n):
            subset = [self.elements[j] for j in range(self.n) if (i & (1 << j))]
            if (0, 0, 0) not in subset:
                continue

            closed_add = all(self.add(x, y) in subset for x in subset for y in subset)
            if not closed_add:
                continue

            closed_mul = all(self.mul(x, r) in subset for x in subset for r in self.elements)
            if not closed_mul:
                continue

            ideals.append(subset)
        return ideals

    def get_prime_ideals(self):
        ideals = self.get_ideals()
        prime_ideals = []
        for I in ideals:
            if len(I) == self.n:
                continue

            is_prime = True
            for x in self.elements:
                for y in self.elements:
                    if self.mul(x, y) in I:
                        if x not in I and y not in I:
                            is_prime = False
                            break
                if not is_prime:
                    break
            if is_prime:
                prime_ideals.append(I)
        return prime_ideals

    def is_pid(self):
        # A PID must be an integral domain
        for x in self.elements:
            if x == (0, 0, 0): continue
            for y in self.elements:
                if y == (0, 0, 0): continue
                if self.mul(x, y) == (0, 0, 0):
                    return False

        # Check if every ideal is principal
        ideals = self.get_ideals()
        for I in ideals:
            is_principal = False
            for gen in self.elements:
                gen_ideal = set(self.mul(gen, r) for r in self.elements)
                if gen_ideal == set(I):
                    is_principal = True
                    break
            if not is_principal:
                return False

        return True

