# A script to find a counterexample to the conjecture.
# Conjecture: Let R be a ring, M an R-module, I and J ideals of R. 
# If I + J = R, then M/((I \cap J)M) \cong M/IM \times M/JM.
# (Dropped hypothesis: R is a commutative ring with identity)

def main():
    # We construct a ring R without identity.
    # R = Z_2 x Z_2 with zero multiplication.
    R_elements = [(0,0), (0,1), (1,0), (1,1)]

    def R_add(x, y):
        return (x[0]^y[0], x[1]^y[1])

    def R_mul(x, y):
        return (0, 0)

    # I and J are ideals of R.
    I = [(0,0), (1,0)]
    J = [(0,0), (0,1)]

    # Check I and J are ideals
    def is_ideal(ideal):
        # Closed under addition
        for x in ideal:
            for y in ideal:
                if R_add(x, y) not in ideal:
                    return False
        # Closed under multiplication by any element in R
        for x in ideal:
            for r in R_elements:
                if R_mul(x, r) not in ideal:
                    return False
                if R_mul(r, x) not in ideal:
                    return False
        return True

    assert is_ideal(I), "I must be an ideal"
    assert is_ideal(J), "J must be an ideal"

    # Check I + J = R
    I_plus_J = []
    for i in I:
        for j in J:
            s = R_add(i, j)
            if s not in I_plus_J:
                I_plus_J.append(s)
    assert sorted(I_plus_J) == sorted(R_elements), "I + J must equal R"

    # M is an R-module. We use M = Z_2 with trivial action.
    M_elements = [0, 1]

    def M_add(x, y):
        return x ^ y

    def action(r, m):
        return 0

    # Check M is an R-module
    def is_module():
        for r in R_elements:
            for m1 in M_elements:
                for m2 in M_elements:
                    if action(r, M_add(m1, m2)) != M_add(action(r, m1), action(r, m2)):
                        return False
        for r1 in R_elements:
            for r2 in R_elements:
                for m in M_elements:
                    if action(R_add(r1, r2), m) != M_add(action(r1, m), action(r2, m)):
                        return False
                    if action(R_mul(r1, r2), m) != action(r1, action(r2, m)):
                        return False
        return True

    assert is_module(), "M must be an R-module"

    # Calculate IM, JM, and (I \cap J)M
    # Since the action is always 0, any submodule generated by products is just {0}
    IM = [0]
    JM = [0]

    I_cap_J = [x for x in I if x in J]
    assert I_cap_J == [(0,0)], "I \cap J should be {(0,0)}"

    I_cap_J_M = [0]

    # Check conclusion: M / ((I \cap J)M) \cong M/IM \times M/JM
    # We compare the sizes of the two modules to show they cannot be isomorphic.
    size_LHS = len(M_elements) // len(I_cap_J_M)
    size_RHS = (len(M_elements) // len(IM)) * (len(M_elements) // len(JM))

    # The conclusion must FAIL
    assert size_LHS != size_RHS, f"Conclusion holds! LHS size {size_LHS}, RHS size {size_RHS}"

    print("Counterexample found successfully.")
    print(f"R is Z_2 x Z_2 with zero multiplication.")
    print(f"I = {I}, J = {J}")
    print(f"M is Z_2 with trivial action.")
    print(f"Size of M / ((I \cap J)M) = {size_LHS}")
    print(f"Size of M/IM x M/JM = {size_RHS}")

