    """Check if x is a unit in Z/6Z."""
    return any((x * y) % n == 1 for y in elements)

def divides(a, b):
    """Check if a divides b in Z/6Z (i.e., exists k such that a*k = b)."""
    return any((a * k) % n == b for k in elements)

def is_prime(p):
    """
    Check if p is a prime element in Z/6Z.
    A non-zero, non-unit element p is prime if p | ab implies p | a or p | b.
    """
    if p == 0 or is_unit(p):
        return False
    for a in elements:
        for b in elements:
            if divides(p, (a * b) % n):
                if not (divides(p, a) or divides(p, b)):
                    return False
    return True

def is_irreducible(p):
    """
    Check if p is an irreducible element in Z/6Z.
    A non-zero, non-unit element p is irreducible if p = ab implies a is a unit or b is a unit.
    """
    if p == 0 or is_unit(p):
        return False
    for a in elements:
        for b in elements:
            if p == (a * b) % n:
                if not (is_unit(a) or is_unit(b)):
                    return False
    return True

