    return (
        (x[0]*y[0] + x[1]*y[2]) % 2,
        (x[0]*y[1] + x[1]*y[3]) % 2,
        (x[2]*y[0] + x[3]*y[2]) % 2,
        (x[2]*y[1] + x[3]*y[3]) % 2
    )

# S is a simple ring, meaning its only two-sided ideals are {0} and S.
ideals_S = [
    [(0, 0, 0, 0)],
    S
]

