    return (x[0], 0, 0, x[1])

# Check Hypothesis 1: f is a ring homomorphism
for x in R:
    for y in R:
        assert f(add_R(x, y)) == add_S(f(x), f(y)), "f must preserve addition"
        assert f(mul_R(x, y)) == mul_S(f(x), f(y)), "f must preserve multiplication"

# Let P be the zero ideal in S
P = [(0, 0, 0, 0)]

def is_prime_ideal_S(P_ideal):
    # An ideal P is prime if P != S and for any ideals A, B, AB \subseteq P implies A \subseteq P or B \subseteq P.
    if sorted(P_ideal) == sorted(S):
        return False
    for A in ideals_S:
        for B in ideals_S:
            # AB_elements contains products a*b. The ideal AB is generated by these.
            # If all a*b are in P_ideal, then the ideal AB is a subset of P_ideal.
            AB_elements = [mul_S(a, b) for a in A for b in B]
            if all(x in P_ideal for x in AB_elements):
