def mul(x, y):
    return (x[0]*y[0] - 5*x[1]*y[1], x[0]*y[1] + x[1]*y[0])

def norm(x):
    return x[0]**2 + 5*x[1]**2

def is_divisible(a, b):
    if b == (0, 0):
        return False
    det = b[0]**2 + 5*b[1]**2
    x_num = a[0]*b[0] + 5*a[1]*b[1]
    y_num = a[1]*b[0] - a[0]*b[1]
    return x_num % det == 0 and y_num % det == 0

def power(x, p):
    res = (1, 0)
    for _ in range(p):
        res = mul(res, x)
    return res

# Ring R = Z[\sqrt{-5}], which is not a Unique Factorization Domain.
# Elements are represented as tuples (u, v) for u + v\sqrt{-5}

a = (2, 1)   # 2 + \sqrt{-5}
b = (2, -1)  # 2 - \sqrt{-5}
c = (3, 0)   # 3
n = 2

# [1] a, b, c are non-zero elements of R
assert a != (0, 0)
assert b != (0, 0)
assert c != (0, 0)

# [2] a and b are relatively prime (only common divisors are units)
def get_divisors(x):
    divs = []
    n_x = norm(x)
    max_u = int(n_x**0.5) + 1
    max_v = int((n_x/5)**0.5) + 1
    for u in range(-max_u, max_u + 1):
        for v in range(-max_v, max_v + 1):
            d = (u, v)
            if d != (0, 0) and is_divisible(x, d):
                divs.append(d)
    return set(divs)

divs_a = get_divisors(a)
divs_b = get_divisors(b)
common_divs = divs_a.intersection(divs_b)

units = {(1, 0), (-1, 0)}
assert common_divs.issubset(units), "a and b are not relatively prime"

# [3] n >= 2 is an integer
assert isinstance(n, int) and n >= 2

# [4] ab = c^n
assert mul(a, b) == power(c, n)

# Conclusion: there exist units u, v in R and elements x, y in R such that a = u x^n and b = v y^n
def conclusion_holds():
    a_works = False
    b_works = False

    # We search a reasonable range for x and y.
    # Since norm(a) = 9, if a = u * x^2, then norm(x)^2 = 9 => norm(x) = 3.
    # Elements with norm <= 9 are well within [-5, 5] for u and v.
    for u_val in range(-5, 6):
        for v_val in range(-5, 6):
            x = (u_val, v_val)
            for unit in units:
                if a == mul(unit, power(x, n)):
                    a_works = True
                if b == mul(unit, power(x, n)):
                    b_works = True

    return a_works and b_works

# The conclusion must FAIL
assert not conclusion_holds(), "Conclusion holds, but it should fail!"

import itertools

# We construct the ring R = M_2(GF(2)), the 2x2 matrices over the field of 2 elements.
# In a commutative ring, the nilradical (set of all nilpotent elements) forms an ideal
# and is equal to the intersection of all minimal prime ideals.
# In a non-commutative ring, the set of nilpotent elements is generally not an ideal,
# and does not equal the intersection of all minimal prime ideals.

class Matrix2x2:
    def __init__(self, mat):
        self.mat = tuple(mat)

    def __eq__(self, other):
        return self.mat == other.mat

    def __hash__(self):
        return hash(self.mat)

    def __mul__(self, other):
        a = (self.mat[0]*other.mat[0] + self.mat[1]*other.mat[2]) % 2
        b = (self.mat[0]*other.mat[1] + self.mat[1]*other.mat[3]) % 2
        c = (self.mat[2]*other.mat[0] + self.mat[3]*other.mat[2]) % 2
        d = (self.mat[2]*other.mat[1] + self.mat[3]*other.mat[3]) % 2
        return Matrix2x2((a, b, c, d))

    def __add__(self, other):
        return Matrix2x2(tuple((x+y)%2 for x, y in zip(self.mat, other.mat)))

    def is_zero(self):
        return all(x == 0 for x in self.mat)

    def __repr__(self):
        return str(self.mat)

# Generate all 16 elements of M_2(GF(2))
elements = [Matrix2x2(p) for p in itertools.product([0, 1], repeat=4)]
zero = Matrix2x2((0, 0, 0, 0))

# 1. Compute the "nilradical" interpreted as the set of all nilpotent elements
nilradical = set()
for e in elements:
    curr = e
    is_nil = False
    for _ in range(4):
        if curr.is_zero():
            is_nil = True
            break
        curr = curr * e
    if is_nil:
        nilradical.add(e)

# 2. Find all two-sided ideals of R
def get_ideal_generated_by(e):
    generators = set()
    for x in elements:
        for y in elements:
            generators.add(x * e * y)

    ideal = set(generators)
    while True:
        new_elements = set()
        for a in ideal:
            for b in ideal:
                s = a + b
                if s not in ideal:
                    new_elements.add(s)
        if not new_elements:
            break
        ideal.update(new_elements)
    return frozenset(ideal)

ideals = set()
for e in elements:
    ideals.add(get_ideal_generated_by(e))

# 3. Find all prime ideals
# A proper ideal P is prime if for any ideals A, B, A*B \subseteq P implies A \subseteq P or B \subseteq P.
prime_ideals = []
for P in ideals:
    if len(P) == len(elements):
        continue  # proper ideals only
    is_prime = True
    for A in ideals:
        for B in ideals:
            ab_in_P = True
            for a in A:
                for b in B:
                    if (a * b) not in P:
                        ab_in_P = False
                        break
                if not ab_in_P:
                    break
            if ab_in_P:
                if not (A.issubset(P) or B.issubset(P)):
                    is_prime = False
                    break
        if not is_prime:
            break
    if is_prime:
        prime_ideals.append(P)

# 4. Find minimal prime ideals
minimal_prime_ideals = []
for P in prime_ideals:
    is_minimal = True
    for Q in prime_ideals:
        if Q != P and Q.issubset(P):
            is_minimal = False
            break
    if is_minimal:
        minimal_prime_ideals.append(P)

intersection_min_primes = set.intersection(*[set(P) for P in minimal_prime_ideals])

# Verify the properties of our counterexample
# In M_2(GF(2)), the only proper ideal is {0}, which is prime.
# So the intersection of minimal prime ideals is {0}.
assert len(intersection_min_primes) == 1
assert zero in intersection_min_primes

# The set of nilpotent elements contains non-zero elements (e.g., strictly upper triangular matrices)
assert len(nilradical) > 1

# CONCLUSION FAILS: The nilradical is NOT equal to the intersection of all minimal prime ideals
assert nilradical != intersection_min_primes, "The nilradical equals the intersection of minimal prime ideals, but it should not!"

print("Counterexample found!")
print(f"Ring: M_2(GF(2))")
print(f"Intersection of minimal prime ideals has size: {len(intersection_min_primes)}")
print(f"Nilradical (set of nilpotent elements) has size: {len(nilradical)}")

import itertools

# We construct a counterexample using the finite local ring R = F2[x,y]/(x^2, xy, y^2).
# Elements of R are represented as tuples (a, b, c) corresponding to the polynomial a + bx + cy.
elements = list(itertools.product([0, 1], repeat=3))

def add(u, v):
    return ((u[0] + v[0]) % 2, (u[1] + v[1]) % 2, (u[2] + v[2]) % 2)

def mul(u, v):
    a1, b1, c1 = u
    a2, b2, c2 = v
    # Multiplication modulo the relations x^2 = 0, xy = 0, y^2 = 0
    return ((a1 * a2) % 2, (a1 * b2 + b1 * a2) % 2, (a1 * c2 + c1 * a2) % 2)

def generate_ideal(gens):
    ideal = set(gens)
    ideal.add((0, 0, 0))
    while True:
        new_ideal = set(ideal)
        # Closure under addition
        for u in ideal:
            for v in ideal:
                new_ideal.add(add(u, v))
        # Closure under multiplication by any element in R
        for u in ideal:
            for r in elements:
                new_ideal.add(mul(u, r))
        if len(new_ideal) == len(ideal):
            break
        ideal = new_ideal
    return frozenset(ideal)

# Find all valid ideals in R
all_ideals = set()
for r in range(1, len(elements) + 1):
    for gens in itertools.combinations(elements, r):
        all_ideals.add(generate_ideal(gens))

# Let J be the maximal ideal <x, y> and I be the ideal <x>
J = generate_ideal([(0, 1, 0), (0, 0, 1)])
I = generate_ideal([(0, 1, 0)])

# Verify remaining hypotheses: I and J are ideals of R
assert I in all_ideals
assert J in all_ideals

def ideal_product(ideal1, ideal2):
    gens = [mul(u, v) for u in ideal1 for v in ideal2]
    return generate_ideal(gens)

# The conclusion to test is: I ⊆ J iff there exists an ideal K such that I = J*K
# First, we check that the left-hand side of the biconditional is TRUE (I is indeed a subset of J)
assert I.issubset(J)

# Now we check if there exists any ideal K such that I = J*K
exists_K = False
for K in all_ideals:
    if ideal_product(J, K) == I:
        exists_K = True
        break

# Since the left-hand side of the iff is True, the right-hand side must also be True for the conclusion to hold.
# We assert that NO such K exists, meaning the right-hand side is False, thereby breaking the iff statement.
assert not exists_K, "Counterexample failed: Found an ideal K such that I = J*K"

import itertools

class Element:
    """
    Represents an element in the ring R = F2[X, Y] / (X^2, XY, Y^2).
    Elements are of the form a + bX + cY where a, b, c are in F2.
    """
    def __init__(self, a, b, c):
        self.a = a % 2
        self.b = b % 2
        self.c = c % 2

    def __eq__(self, other):
        return (self.a, self.b, self.c) == (other.a, other.b, other.c)

    def __hash__(self):
        return hash((self.a, self.b, self.c))

    def __add__(self, other):
        return Element(self.a + other.a, self.b + other.b, self.c + other.c)

    def __mul__(self, other):
        # (a1 + b1 X + c1 Y) * (a2 + b2 X + c2 Y)
        # = a1*a2 + (a1*b2 + b1*a2)X + (a1*c2 + c1*a2)Y
        # since X^2 = XY = Y^2 = 0
        return Element(
            self.a * other.a,
            self.a * other.b + self.b * other.a,
            self.a * other.c + self.c * other.a
        )

    def __repr__(self):
        return f"({self.a},{self.b},{self.c})"

# Construct the ring R (8 elements)
R = [Element(a, b, c) for a in (0, 1) for b in (0, 1) for c in (0, 1)]
zero = Element(0, 0, 0)
one = Element(1, 0, 0)

def is_ideal(subset):
    if zero not in subset:
        return False
    # Check closure under addition
    for x in subset:
        for y in subset:
            if (x + y) not in subset:
                return False
    # Check closure under multiplication by any ring element
    for x in subset:
        for r in R:
            if (r * x) not in subset:
                return False
    return True

def is_prime_ideal(subset):
    if not is_ideal(subset):
        return False
    if len(subset) == len(R): # Proper ideal check
        return False
    # Check prime condition: ab in P implies a in P or b in P
    for x in R:
        for y in R:
            if (x * y) in subset:
                if x not in subset and y not in subset:
                    return False
    return True

def is_maximal_ideal(subset, all_ideals):
    if not is_ideal(subset):
        return False
    if len(subset) == len(R):
        return False
    # Check if strictly contained in any other proper ideal
    for other in all_ideals:
        if len(other) > len(subset) and len(other) < len(R):
            if all(x in other for x in subset):
                return False
    return True

# Generate all subsets of R containing zero
all_subsets = []
R_star = [x for x in R if x != zero]
for r in range(0, len(R_star) + 1):
    for combo in itertools.combinations(R_star, r):
        all_subsets.append(set(combo) | {zero})

# Find all ideals and prime ideals
all_ideals = [s for s in all_subsets if is_ideal(s)]
prime_ideals = [s for s in all_ideals if is_prime_ideal(s)]

# ---------------------------------------------------------------------------
# HYPOTHESIS CHECK
# Remaining Hypothesis: Every non-zero prime ideal of R is a maximal ideal
# ---------------------------------------------------------------------------
all_prime_ideals_are_maximal = True
for p in prime_ideals:
    if len(p) > 1: # It is a non-zero ideal
        if not is_maximal_ideal(p, all_ideals):
            all_prime_ideals_are_maximal = False
            break

assert all_prime_ideals_are_maximal, "Hypothesis failed: Not all non-zero prime ideals are maximal"

# ---------------------------------------------------------------------------
# CONCLUSION CHECK
# Conclusion: R is a Principal Ideal Domain (PID)
# A PID must be an integral domain where every ideal is principal.
# ---------------------------------------------------------------------------
is_integral_domain = True
for x in R:
    for y in R:
        if x != zero and y != zero and (x * y) == zero:
            is_integral_domain = False
            break

def is_principal(ideal):
    for gen in R:
        gen_ideal = set([gen * r for r in R])
        if gen_ideal == ideal:
            return True
    return False

all_ideals_principal = all(is_principal(i) for i in all_ideals)

is_pid = is_integral_domain and all_ideals_principal

# The conclusion MUST FAIL for this to be a counterexample
assert not is_pid, "Logic error: R is a PID, but we need a counterexample"

# ---------------------------------------------------------------------------
# OUTPUT
# ---------------------------------------------------------------------------
print("Counterexample found!")
print("Ring R = F2[X, Y] / (X^2, XY, Y^2)")
print(f"Number of elements in R: {len(R)}")
print(f"Number of ideals: {len(all_ideals)}")
print(f"Number of prime ideals: {len(prime_ideals)}")
print(f"Are all non-zero prime ideals maximal? {all_prime_ideals_are_maximal}")
print(f"Is R an integral domain? {is_integral_domain}")
print(f"Are all ideals principal? {all_ideals_principal}")
print(f"Is R a PID? {is_pid}")

