import sympy as sp

# We use the ring R of 4x4 upper triangular matrices over a field.
# This is a standard non-commutative ring.
ZERO = sp.ImmutableMatrix(sp.zeros(4, 4))

# Define the matrix units E_ij
E = {}
for i in range(1, 5):
    for j in range(1, 5):
        M = sp.zeros(4, 4)
        M[i-1, j-1] = 1
        E[(i, j)] = sp.ImmutableMatrix(M)

# Basis for R: all upper triangular matrix units
R_basis = [E[(i, j)] for i in range(1, 5) for j in range(i, 5)]

# We define two ideals I and J by their basis (which are subsets of the matrix units).
# I is the ideal generated by E_12 and E_34.
I_basis = [E[(1, 2)], E[(1, 3)], E[(1, 4)], E[(2, 4)], E[(3, 4)]]

# J is the ideal generated by E_23 and E_34.
J_basis = [E[(2, 3)], E[(1, 3)], E[(1, 4)], E[(2, 4)], E[(3, 4)]]

def is_ideal(basis, R_basis):
    """Check if the span of `basis` is a two-sided ideal in R."""
    # Left ideal check
    for r in R_basis:
        for b in basis:
            prod = r * b
            if prod != ZERO:
                if not any(prod == x for x in basis):
                    return False
    # Right ideal check
    for r in R_basis:
        for b in basis:
            prod = b * r
            if prod != ZERO:
                if not any(prod == x for x in basis):
                    return False
    return True

# [1] Verify remaining hypothesis: I is an ideal of R
assert is_ideal(I_basis, R_basis), "I must be an ideal of R"

# [2] Verify remaining hypothesis: J is an ideal of R
assert is_ideal(J_basis, R_basis), "J must be an ideal of R"

# Calculate basis for the intersection I \cap J
I_cap_J_basis = [x for x in I_basis if any(x == y for y in J_basis)]

# Calculate basis for the sum I + J
I_plus_J_basis = I_basis.copy()
for x in J_basis:
    if not any(x == y for y in I_plus_J_basis):
        I_plus_J_basis.append(x)

# Calculate basis for the product ideal IJ
# Since the product of any two matrix units is either another matrix unit or zero,
# the products of the basis elements form a basis for the product ideal.
IJ_basis = []
for x in I_basis:
    for y in J_basis:
        prod = x * y
        if prod != ZERO:
            if not any(prod == z for z in IJ_basis):
                IJ_basis.append(prod)

# Calculate basis for the product ideal (I+J)(I \cap J)
sum_cap_basis = []
for x in I_plus_J_basis:
    for y in I_cap_J_basis:
        prod = x * y
        if prod != ZERO:
            if not any(prod == z for z in sum_cap_basis):
                sum_cap_basis.append(prod)

# The conclusion to test: (I+J)(I \cap J) \subseteq IJ
# We verify this by checking if every basis element of (I+J)(I \cap J) is in IJ.
conclusion_holds = True
for x in sum_cap_basis:
    if not any(x == y for y in IJ_basis):
        conclusion_holds = False
        break

# MANDATORY CORRECTNESS CHECK: The conclusion must FAIL
assert not conclusion_holds, "Conclusion (I+J)(I \\cap J) \\subseteq IJ should be FALSE"

# Print out the counterexample clearly
def format_basis(basis):
    res = []
    for M in basis:
        for i in range(4):
            for j in range(4):
                if M[i, j] == 1:
                    res.append(f"E_{i+1}{j+1}")
    return res

print("Counterexample found!")
