        return isinstance(other, Z6) and self.val == other.val

    def __add__(self, other):
        return Z6(self.val + other.val)

    def __mul__(self, other):
        return Z6(self.val * other.val)

    def __hash__(self):
        return hash(self.val)

    def __repr__(self):
        return f"Z6({self.val})"

elements = [Z6(i) for i in range(6)]

def is_integral_domain():
    # Check for zero divisors
    for x in elements:
        if x.val != 0:
            for y in elements:
                if y.val != 0 and (x * y).val == 0:
                    return False
    return True

def generate_ideal(generators):
    ideal = set()
    ideal.add(Z6(0))
    for g in generators:
        for r in elements:
            ideal.add(r * g)

    changed = True
    while changed:
        new_elements = set()
        for a in ideal:
            for b in ideal:
                new_elements.add(a + b)
        if new_elements.issubset(ideal):
            changed = False
        else:
            ideal.update(new_elements)
            changed = True
    return frozenset(ideal)

