            is_principal = False
            for p in elements:
                if generate_ideal([p]) == ideal:
                    is_principal = True
                    break
            if not is_principal:
                return False
    return True

def is_bezout_domain():
    # A Bezout domain must be an integral domain by definition
    if not is_integral_domain():
        return False
    return every_fg_ideal_is_principal()

