        ideals.append(subset)

# Find prime ideals of Z/6Z
prime_ideals = []
for I in ideals:
    if len(I) == 6:
        continue # The whole ring is not a prime ideal
    is_prime = True
    for a in R.elements:
        for b in R.elements:
            if R.mul(a, b) in I:
                if a not in I and b not in I:
                    is_prime = False
                    break
        if not is_prime:
            break
    if is_prime:
        prime_ideals.append(I)

# Calculate closed sets in the Zariski topology
# V(I) = { P in Spec(R) | I is a subset of P }
closed_sets = set()
for I in ideals:
    V_I = frozenset([idx for idx, P in enumerate(prime_ideals) if I.issubset(P)])
    closed_sets.add(V_I)

# Find clopen (both closed and open) sets
spec_space = frozenset(range(len(prime_ideals)))
clopen_sets = []
for C in closed_sets:
    complement = spec_space - C
    if complement in closed_sets:
        clopen_sets.append(C)

# A topological space is connected iff its only clopen sets are the empty set and the whole space
is_connected = (len(clopen_sets) == 2)

# Verify that Spec(R) is not empty
assert len(prime_ideals) > 0, "Spec(R) should not be empty"

# Verify that the conclusion FAILS (Spec(Z/6Z) is disconnected)
assert not is_connected, "Spec(Z/6Z) is connected, but it should be disconnected!"

print("Counterexample found: R = Z/6Z")
print(f"Prime ideals (Spec(R)): {prime_ideals}")
print(f"Closed sets in Zariski topology: {[list(c) for c in closed_sets]}")
print(f"Clopen sets: {[list(c) for c in clopen_sets]}")
print("Spec(R) is disconnected because there are non-trivial clopen sets.")

class BicyclicAlgebraElement:
    """
    Represents an element in the Bicyclic Algebra Q<A, B> / <AB - 1>.
    This is a standard example of a ring that is not right Artinian.
    Basis elements are uniquely of the form B^i A^j.
    """
    def __init__(self, terms):
        self.terms = {}
        for (i, j), c in terms.items():
            if c != 0:
                self.terms[(i, j)] = c

    def __add__(self, other):
        res = dict(self.terms)
        for (i, j), c in other.terms.items():
            res[(i, j)] = res.get((i, j), 0) + c
        return BicyclicAlgebraElement(res)

    def __sub__(self, other):
        res = dict(self.terms)
        for (i, j), c in other.terms.items():
            res[(i, j)] = res.get((i, j), 0) - c
        return BicyclicAlgebraElement(res)

    def __mul__(self, other):
        res = {}
        for (i1, j1), c1 in self.terms.items():
            for (i2, j2), c2 in other.terms.items():
                # Multiplication rule using AB = 1
                if j1 >= i2:
                    new_i = i1
                    new_j = j2 + (j1 - i2)
                else:
                    new_i = i1 + (i2 - j1)
                    new_j = j2
                res[(new_i, new_j)] = res.get((new_i, new_j), 0) + c1 * c2
        return BicyclicAlgebraElement(res)

    def __eq__(self, other):
        d1 = {k: v for k, v in self.terms.items() if v != 0}
        d2 = {k: v for k, v in other.terms.items() if v != 0}
        return d1 == d2

    def is_zero(self):
        return all(v == 0 for v in self.terms.values())

    def __str__(self):
        if self.is_zero():
            return "0"
        terms_str = []
        for (i, j), c in sorted(self.terms.items()):
            if c == 0: continue
            term = f"{c}"
            if i > 0: term += f"*B^{i}"
            if j > 0: term += f"*A^{j}"
            terms_str.append(term)
        return " + ".join(terms_str)

# Define the generators and identity
one = BicyclicAlgebraElement({(0, 0): 1})
A = BicyclicAlgebraElement({(0, 1): 1})
B = BicyclicAlgebraElement({(1, 0): 1})
zero = BicyclicAlgebraElement({})

# Verify the defining relation of the ring: AB = 1
assert A * B == one

# The module M is R_R (the ring itself viewed as a right module over itself).
# [1] M is trivially finitely generated by the element `one`.

# [2] The endomorphism f: M -> M is defined as left multiplication by A.
def f(x):
    return A * x

# Test elements to verify module homomorphism properties
x = BicyclicAlgebraElement({(2, 3): 5, (0, 0): -2})
y = BicyclicAlgebraElement({(1, 1): 3, (0, 2): 4})
r = BicyclicAlgebraElement({(3, 0): 2, (1, 2): -1})

# Verify f is a right R-module homomorphism
assert f(x + y) == f(x) + f(y), "f must be additive"
assert f(x * r) == f(x) * r, "f must be a right R-module homomorphism"

# Verify f is surjective:
# For any y in M, B * y is a pre-image because f(B * y) = A * (B * y) = (A * B) * y = one * y = y
def pre_image(val):
    return B * val

assert f(pre_image(y)) == y, "f must be surjective"
assert f(pre_image(x)) == x, "f must be surjective"

# CONCLUSION TO FALSIFY: f is an injective homomorphism, and thus an isomorphism.
# We find a non-zero element z in the kernel of f.
z = one - B * A

# Verify f(z) is zero
assert f(z) == zero, "f(z) must be zero"

# Verify z is strictly not zero
assert not (z == zero), "z must be non-zero"

# Disproof of injectivity: f(z) == f(zero) but z != zero
assert f(z) == f(zero)
assert not (z == zero)

print("Counterexample found!")
print("Ring R: Bicyclic algebra Q<A, B> / <AB - 1>")
print("Module M: R_R (finitely generated by 1)")
print("Homomorphism f: M -> M given by f(x) = A * x")
print(f"Surjectivity holds: f(B * x) = A * B * x = x")
print(f"Injectivity FAILS: let z = {z}")
print(f"z is non-zero, but f(z) = A * ({z}) = {f(z)}")

class Z_sqrt_minus_5:
    """Elements of the ring Z[sqrt(-5)], which is an integral domain but not a UFD."""
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def __mul__(self, other):
        return Z_sqrt_minus_5(self.a * other.a - 5 * self.b * other.b,
                              self.a * other.b + self.b * other.a)

    def __eq__(self, other):
        return self.a == other.a and self.b == other.b

    def __hash__(self):
        return hash((self.a, self.b))

    def norm(self):
        return self.a**2 + 5 * self.b**2

    def __repr__(self):
        return f"({self.a} + {self.b}*sqrt(-5))"

# Elements of R
one = Z_sqrt_minus_5(1, 0)
zero = Z_sqrt_minus_5(0, 0)

# Hypothesis 1: S is a multiplicatively closed subset of R
# We choose S = {1}, which is trivially multiplicatively closed.
S = {one}
assert all(x * y in S for x in S for y in S), "S is not multiplicatively closed"

# Hypothesis 2: The zero element is not in S
assert zero not in S, "0 is in S"

class LocalizedElement:
    """Elements of the localized ring S^{-1}R"""
    def __init__(self, num, den):
        assert den in S
        self.num = num
        self.den = den

    def __mul__(self, other):
        return LocalizedElement(self.num * other.num, self.den * other.den)

    def __eq__(self, other):
        # In an integral domain, r1/s1 == r2/s2 <=> r1*s2 == r2*s1
        return (self.num * other.den) == (other.num * self.den)

    def __repr__(self):
        return f"{self.num} / {self.den}"

# We will show that S^{-1}R is NOT a UFD by demonstrating that an element 
# has two distinct factorizations into irreducibles.
# Consider the element 6/1 in S^{-1}R.
le2 = LocalizedElement(Z_sqrt_minus_5(2, 0), one)
le3 = LocalizedElement(Z_sqrt_minus_5(3, 0), one)
le1_plus = LocalizedElement(Z_sqrt_minus_5(1, 1), one)
le1_minus = LocalizedElement(Z_sqrt_minus_5(1, -1), one)
le6 = LocalizedElement(Z_sqrt_minus_5(6, 0), one)

# Two factorizations of 6
fact1 = le2 * le3
fact2 = le1_plus * le1_minus

assert fact1 == le6, "First factorization fails"
assert fact2 == le6, "Second factorization fails"
assert fact1 == fact2, "Factorizations do not evaluate to the same element"

# To prove they are irreducible in S^{-1}R (which is isomorphic to R since S={1}),
# we check if their numerators can be factored into non-units in R.
# A non-unit in R has norm > 1.
def is_irreducible(e):
    n = e.norm()
    if n <= 1: 
        return False
    # Proper divisors would have norm d where d | n and 1 < d < n.
    for d in range(2, n):
        if n % d == 0:
            # Check if there is an element of norm d
            for a in range(-int(d**0.5) - 1, int(d**0.5) + 2):
                for b in range(-int((d / 5)**0.5) - 1, int((d / 5)**0.5) + 2):
                    if a**2 + 5 * b**2 == d:
                        return False
    return True

assert is_irreducible(le2.num), "2 is not irreducible"
assert is_irreducible(le3.num), "3 is not irreducible"
assert is_irreducible(le1_plus.num), "1+sqrt(-5) is not irreducible"
assert is_irreducible(le1_minus.num), "1-sqrt(-5) is not irreducible"

# Check they are not associates.
# Associates in R must have the same norm. Since S={1}, units are the same.
assert le2.num.norm() != le1_plus.num.norm(), "Elements are associates"
assert le2.num.norm() != le1_minus.num.norm(), "Elements are associates"

# Therefore, 6 has two distinct factorizations into irreducibles in S^{-1}R.
# The conclusion that S^{-1}R is a UFD must be FALSE.
is_ufd = False
assert not is_ufd, "S^{-1}R is a Unique Factorization Domain"

import itertools

class Zmodn:
    """Representation of the ring Z/nZ."""
    def __init__(self, n):
        self.n = n
        self.elements = list(range(n))

    def add(self, a, b):
        return (a + b) % self.n

    def mul(self, a, b):
        return (a * b) % self.n

    def is_unit(self, a):
        # a is a unit if there exists b such that a*b = 1
        return any(self.mul(a, b) == 1 for b in self.elements)

    def divides(self, a, b):
        # a divides b if there exists k such that a*k = b
        return any(self.mul(a, k) == b for k in self.elements)

    def is_irreducible(self, x):
        # x is irreducible if it's non-zero, non-unit, and x = ab implies a or b is a unit
        if x == 0 or self.is_unit(x):
            return False
        for a in self.elements:
            for b in self.elements:
                if self.mul(a, b) == x:
                    if not self.is_unit(a) and not self.is_unit(b):
                        return False
        return True

    def is_prime(self, x):
        # x is prime if it's non-zero, non-unit, and x | ab implies x | a or x | b
        if x == 0 or self.is_unit(x):
            return False
        for a in self.elements:
            for b in self.elements:
                if self.divides(x, self.mul(a, b)):
                    if not self.divides(x, a) and not self.divides(x, b):
                        return False
        return True

    def satisfies_accp(self):
        # Any finite ring trivially satisfies the ascending chain condition on principal ideals (ACCP)
        return True

    def is_integral_domain(self):
        if self.n == 1: 
            return False
        for a in self.elements:
            if a != 0:
                for b in self.elements:
                    if b != 0 and self.mul(a, b) == 0:
                        return False
        return True

    def is_ufd(self):
        # By standard abstract algebra definitions, a UFD MUST be an integral domain.
        if not self.is_integral_domain():
            return False
        return True

# Counterexample: R = Z/4Z
R = Zmodn(4)

# There are no remaining hypotheses to check since the only hypothesis was dropped.

# Evaluate the right-hand side (RHS) of the conclusion:
# "R satisfies the ascending chain condition on principal ideals and every irreducible element in R is a prime element."
accp = R.satisfies_accp()
assert accp is True, "Finite rings must satisfy ACCP."

irreducibles = [x for x in R.elements if R.is_irreducible(x)]
all_irreducibles_are_prime = all(R.is_prime(x) for x in irreducibles)
assert all_irreducibles_are_prime is True, "In Z/4Z, the only irreducible is 2, which is also prime."

rhs_holds = accp and all_irreducibles_are_prime

# Evaluate the left-hand side (LHS) of the conclusion:
# "R is a unique factorization domain"
lhs_holds = R.is_ufd()
assert lhs_holds is False, "Z/4Z is not an integral domain, so it cannot be a UFD."

# The conclusion claims: LHS <==> RHS
# We assert that this equivalence is FALSE.
assert lhs_holds != rhs_holds, "Conclusion holds, but it should fail. The ring satisfies RHS but is not a UFD."

import itertools

class M2F2:
    """Represents a 2x2 matrix over the finite field F_2."""
    def __init__(self, mat):
        self.mat = tuple(mat)

    def __eq__(self, other):
        return self.mat == other.mat

    def __hash__(self):
        return hash(self.mat)

    def __add__(self, other):
        return M2F2([(a + b) % 2 for a, b in zip(self.mat, other.mat)])

    def __mul__(self, other):
        a, b, c, d = self.mat
        e, f, g, h = other.mat
        return M2F2([
            (a*e + b*g) % 2, (a*f + b*h) % 2,
            (c*e + d*g) % 2, (c*f + d*h) % 2
        ])

    def __repr__(self):
        return f"M2F2({self.mat})"

# Generate all 16 elements of M_2(F_2)
elements = [M2F2(p) for p in itertools.product([0, 1], repeat=4)]
zero = M2F2([0, 0, 0, 0])
one = M2F2([1, 0, 0, 1])

