# To check if {0} is a prime ideal, we first find all two-sided ideals.
def get_ideal_generated_by(subset):
    ideal = set(subset)
    while True:
        new_ideal = set(ideal)
        # Closure under addition
        for x in ideal:
            for y in ideal:
                new_ideal.add(x + y)
        # Closure under left and right multiplication by ring elements
        for x in ideal:
            for r in elements:
                new_ideal.add(r * x)
                new_ideal.add(x * r)
        if len(new_ideal) == len(ideal):
            break
        ideal = new_ideal
    return frozenset(ideal)

# Since M_2(F_2) is a finite simple ring, generating ideals from singletons gives all ideals.
ideals = set()
for x in elements:
    ideals.add(get_ideal_generated_by([x]))

# Check if {0} is a prime ideal
def is_zero_ideal_prime(ideals):
    zero_ideal = frozenset([zero])
    for A in ideals:
        for B in ideals:
            # Check if A * B = {0}
            is_zero_product = True
            for a in A:
                for b in B:
                    if a * b != zero:
                        is_zero_product = False
                        break
                if not is_zero_product:
                    break

            # If A * B = {0}, then A must be {0} or B must be {0}
            if is_zero_product:
                if A != zero_ideal and B != zero_ideal:
                    return False
    return True

zero_is_prime = is_zero_ideal_prime(ideals)

# Check if R is an integral domain
# An integral domain must have no zero divisors.
has_zero_divisors = False
for x in elements:
    if x != zero:
        for y in elements:
            if y != zero and x * y == zero:
                has_zero_divisors = True
                break
        if has_zero_divisors:
            break

is_integral_domain = not has_zero_divisors

# The conclusion states: R is an integral domain iff {0} is a prime ideal
conclusion = (is_integral_domain == zero_is_prime)

# -------------------------------------------------------------------
# Disprove Conclusion
# -------------------------------------------------------------------
assert not conclusion, (
    f"Logic error: conclusion holds. "
    f"is_integral_domain: {is_integral_domain}, zero_is_prime: {zero_is_prime}"
)

print("Counterexample found!")
print("Ring: M_2(F_2) - the ring of 2x2 matrices over F_2")
print(f"Number of elements: {len(elements)}")
print(f"Number of two-sided ideals: {len(ideals)} (Simple Ring)")
