import itertools

def is_left_orderable(elements, op):
    """
    Checks if a finite group is left-orderable.
    A group is left-orderable if there exists a strict total ordering <
    such that for all a, b, c: a < b implies c*a < c*b.
    """
    if len(elements) == 1:
        return True

    # Check all possible strict total orderings (permutations of elements)
    for order in itertools.permutations(elements):
        order_idx = {e: i for i, e in enumerate(order)}
        valid = True
        for a in elements:
            for b in elements:
                if order_idx[a] < order_idx[b]:
                    for c in elements:
                        ca = op(c, a)
                        cb = op(c, b)
                        if order_idx[ca] >= order_idx[cb]:
                            valid = False
                            break
                if not valid:
                    break
            if not valid:
                break

        if valid:
            return True

    return False

# Group G: The trivial group {0}
