# Counterexample: The zero ring R = 2Z / 4Z
# R has elements {0, 2} with addition and multiplication modulo 4.
# This is a commutative Noetherian ring without identity.
# It has NO prime ideals, so the conclusion trivially fails.

elements = [0, 2]

def add(a, b): return (a + b) % 4
def mul(a, b): return (a * b) % 4

# Find all subsets of R
subsets = []
for r in range(1, len(elements) + 1):
    for combo in itertools.combinations(elements, r):
        subsets.append(set(combo))

# Filter to find valid ideals
all_ideals = []
for sub in subsets:
    is_ideal = True
    # Check closure under addition
    for a in sub:
        for b in sub:
            if add(a, b) not in sub:
                is_ideal = False
    # Check closure under multiplication by any ring element
    for a in sub:
        for r in elements:
            if mul(a, r) not in sub:
                is_ideal = False
    if is_ideal:
        all_ideals.append(tuple(sorted(sub)))

