    prods = {mul(a, b) for a in A for b in B}
    closure = set(prods)
    while True:
        new_elements = {add(x, y) for x in closure for y in closure}
        if new_elements.issubset(closure):
            break
        closure.update(new_elements)
    return tuple(sorted(closure))

# Find all prime ideals in R
