for P in proper_ideals:
    is_prime = True
    for A in all_ideals:
        for B in all_ideals:
            if set(ideal_product(A, B)).issubset(set(P)):
                if not set(A).issubset(set(P)) and not set(B).issubset(set(P)):
                    is_prime = False
    if is_prime:
        prime_ideals.append(P)

