class Element:
    """
    Represents an element in the Boolean ring R = F_2[x_0, x_1, ...] / (x_i x_j for i!=j, x_i^2 - x_i).
    Every element can be uniquely written as c + sum_{i in S} x_i,
    where c in {0, 1} and S is a finite set of indices.
    """
    def __init__(self, c, S):
        self.c = c % 2
        self.S = frozenset(S)

    def __eq__(self, other):
        return self.c == other.c and self.S == other.S

    def __hash__(self):
        return hash((self.c, self.S))

    def __add__(self, other):
        return Element(self.c ^ other.c, self.S ^ other.S)

    def __mul__(self, other):
        c = self.c & other.c
        new_S = set()
        for i in self.S | other.S:
            term1 = self.c if i in other.S else 0
            term2 = other.c if i in self.S else 0
            term3 = 1 if (i in self.S and i in other.S) else 0
            if (term1 ^ term2 ^ term3) == 1:
                new_S.add(i)
        return Element(c, new_S)

    def __str__(self):
        terms = []
        if self.c == 1 or not self.S:
            terms.append(str(self.c))
        for i in sorted(self.S):
            terms.append(f"x_{i}")
        return " + ".join(terms)

