    def __init__(self, k):
        self.k = k

    def contains(self, elem):
        # Modulo M_k, x_i = 0 for i != k, and x_k = 1.
        # elem = c + sum_{i in S} x_i reduces to c + (1 if k in S else 0) mod 2.
        val = elem.c ^ (1 if self.k in elem.S else 0)
        return val == 0

    def __eq__(self, other):
        return isinstance(other, MinimalPrimeMk) and self.k == other.k

    def __hash__(self):
        return hash(self.k)

