# We construct a commutative ring R without identity to serve as the counterexample.
# R is an F2-algebra with 8 elements, having basis {a, b, ab} over F2.
# The multiplication rules are:
# a^2 = ab, b^2 = b, a*b = ab, a*ab = ab, b*ab = ab, ab^2 = ab.
# This ring is commutative but lacks a multiplicative identity.

elements = list(itertools.product([0, 1], repeat=3))

def add(u, v):
    return ((u[0] + v[0]) % 2, (u[1] + v[1]) % 2, (u[2] + v[2]) % 2)

def mul(u, v):
    # u[0] is coeff of a, u[1] is coeff of b, u[2] is coeff of ab
    b_coeff = (u[1] * v[1]) % 2
    ab_coeff = ((sum(u) * sum(v)) - u[1] * v[1]) % 2
    return (0, b_coeff, ab_coeff)

def generate_ideal(generators):
    ideal = set(generators)
    ideal.add((0, 0, 0))
    while True:
        new_ideal = set(ideal)
        # Closure under addition
        for x in ideal:
            for y in ideal:
                new_ideal.add(add(x, y))
        # Closure under multiplication by any element in R
        for x in ideal:
            for r in elements:
                new_ideal.add(mul(x, r))
        if len(new_ideal) == len(ideal):
            break
        ideal = new_ideal
    return ideal

# Let I be the ideal generated by 'ab' = (0, 0, 1)
