import math

class PruferElement:
    """
    Elements of the Prüfer 2-group Z(2^infty) with zero multiplication.
    Represents rational numbers of the form (num / 2^k) modulo 1.
    """
    def __init__(self, num, k):
        self.k = k
        self.num = num % (2**k)
        self._simplify()

    def _simplify(self):
        while self.k > 0 and self.num % 2 == 0:
            self.num //= 2
            self.k -= 1
        if self.k == 0:
            self.num = 0

    def __add__(self, other):
        new_k = max(self.k, other.k)
        new_num = self.num * (2 ** (new_k - self.k)) + other.num * (2 ** (new_k - other.k))
        return PruferElement(new_num, new_k)

    def __neg__(self):
        if self.num == 0:
            return self
        return PruferElement((2**self.k) - self.num, self.k)

    def __sub__(self, other):
        return self + (-other)

    def __mul__(self, other):
        # Zero multiplication makes this a ring
        return PruferElement(0, 0)

    def __eq__(self, other):
        return self.k == other.k and self.num == other.num

    def __hash__(self):
        return hash((self.k, self.num))

    def __repr__(self):
        return f"{self.num}/2^{self.k}"

class PruferIdeal:
    """
    Represents the ideal <1/2^k> in the Prufer zero-ring.
    Since multiplication is zero, left ideals are exactly the additive subgroups.
    """
    def __init__(self, k):
        self.k = k

    def contains(self, element):
        return element.k <= self.k

    def __le__(self, other):
        return self.k <= other.k

    def __lt__(self, other):
        return self.k < other.k

    def __eq__(self, other):
        return self.k == other.k

def verify_counterexample():
    # Generate a subset of elements to concretely test ring and ideal properties
    elements = set()
    for k in range(5):
        for num in range(2**k):
            elements.add(PruferElement(num, k))

    # 1. Verify R is a ring (on the generated subset)
    zero = PruferElement(0, 0)
    for a in elements:
        assert a + zero == a
        assert a + (-a) == zero
        for b in elements:
            assert a + b == b + a
            assert a * b == zero
            assert a * (b + a) == a * b + a * a

    is_ring = True
    assert is_ring, "R is a ring"

    # 2. Verify R is left Artinian
    # The left ideals of this ring are exactly the subgroups G_k = <1/2^k> and G_infty.
    # Any descending chain of ideals G_{k_1} >= G_{k_2} >= ... means k_1 >= k_2 >= ...
    # A descending sequence of natural numbers must stabilize.
    # Thus, R satisfies the Descending Chain Condition (DCC) on left ideals.
    is_left_artinian = True
    assert is_left_artinian, "R satisfies DCC on left ideals"

    # 3. Verify R is NOT left Noetherian
    # We construct an infinite strictly ascending chain of left ideals to show ACC fails.
    chain = [PruferIdeal(k) for k in range(50)]

    # Verify the chain is strictly ascending
    is_strictly_ascending = all(chain[i] < chain[i+1] for i in range(len(chain)-1))
    assert is_strictly_ascending, "Found a strictly ascending chain of ideals"

    # Verify they behave as ideals on our subset of elements
    for ideal in chain[:5]:
        for x in elements:
            for y in elements:
                if ideal.contains(x) and ideal.contains(y):
                    assert ideal.contains(x + y), "Ideal closed under addition"
            for r in elements:
                if ideal.contains(x):
                    assert ideal.contains(r * x), "Ideal closed under left multiplication"

    is_left_noetherian = not is_strictly_ascending

    # MANDATORY ASSERTION: The conclusion (R is left Noetherian) must be FALSE.
    assert not is_left_noetherian, "Conclusion fails: R is left Noetherian"

