    verify_counterexample()

import itertools

class Z2Element:
    def __init__(self, val):
        self.val = val % 2
    def __mul__(self, other):
        return Z2Element(self.val + other.val)
    def __eq__(self, other):
        if not isinstance(other, Z2Element):
            return False
        return self.val == other.val
    def __hash__(self):
        return hash(self.val)
    def inverse(self):
        return Z2Element(-self.val)
    def __repr__(self):
        return f"Z2({self.val})"

class ZElement:
    def __init__(self, val):
        self.val = val
    def __mul__(self, other):
        return ZElement(self.val + other.val)
    def __eq__(self, other):
        if not isinstance(other, ZElement):
            return False
        return self.val == other.val
    def __hash__(self):
        return hash(self.val)
    def inverse(self):
        return ZElement(-self.val)
    def __repr__(self):
        return f"Z({self.val})"

class DirectProductElement:
    def __init__(self, g, h):
        self.g = g
        self.h = h
    def __mul__(self, other):
        return DirectProductElement(self.g * other.g, self.h * other.h)
    def __eq__(self, other):
        if not isinstance(other, DirectProductElement):
            return False
        return self.g == other.g and self.h == other.h
    def __hash__(self):
        return hash((self.g, self.h))
    def inverse(self):
        return DirectProductElement(self.g.inverse(), self.h.inverse())
    def __repr__(self):
        return f"({self.g}, {self.h})"

def generates_finite_subgroup(generators, max_size=500):
    """
    Checks if the subgroup generated by `generators` is finite.
    Returns True if the subgroup size <= max_size, False otherwise.
    """
    if not generators:
        return True

    gens_and_invs = set(generators)
    for g in generators:
        gens_and_invs.add(g.inverse())

    elements = set(gens_and_invs)
    queue = list(gens_and_invs)

    while queue:
        current = queue.pop(0)
        for gen in gens_and_invs:
            new_elem = current * gen
            if new_elem not in elements:
                elements.add(new_elem)
                queue.append(new_elem)
                if len(elements) > max_size:
                    return False
    return True

# Hypothesis 1: G is a locally finite group
# Let G be Z2, which is a finite group (order 2), hence locally finite.
# We can verify that any subset of G generates a finite subgroup.
G_generators = [
    [],
    [Z2Element(0)],
    [Z2Element(1)],
    [Z2Element(0), Z2Element(1)]
]
for gens in G_generators:
    assert generates_finite_subgroup(gens), "G must be locally finite"

# H is Z (integers under addition), which is an infinite group.
# It is NOT locally finite, because the subgroup generated by {1} is infinite.
# (This was the dropped hypothesis).

# Conclusion: The direct product G x H is a locally finite group
# We test if G x H is locally finite. If it is, EVERY finitely generated subgroup must be finite.
# We pick a finite set of generators in G x H: {(1, 1)}
g_gen = Z2Element(1)
h_gen = ZElement(1)
gh_gen = DirectProductElement(g_gen, h_gen)

# The subgroup generated by gh_gen is infinite, so G x H is NOT locally finite.
G_x_H_is_locally_finite = generates_finite_subgroup([gh_gen])

# Verify that the conclusion is FALSE
assert not G_x_H_is_locally_finite, "The direct product G x H should not be locally finite"

