import itertools

class ZMod:
    def __init__(self, n):
        self.n = n
        self.elements = list(range(n))

    def add(self, a, b):
        return (a + b) % self.n

    def mul(self, a, b):
        return (a * b) % self.n

    def is_zero_divisor(self, a):
        if a == 0:
            return True
        for x in range(1, self.n):
            if self.mul(a, x) == 0:
                return True
        return False

    def regular_elements(self):
        # Regular elements are those that are not zero divisors
        return [x for x in self.elements if not self.is_zero_divisor(x)]

def is_field(R):
    for a in range(1, R.n):
        has_inv = False
        for b in range(R.n):
            if R.mul(a, b) == 1:
                has_inv = True
                break
        if not has_inv:
            return False
    return True

def is_submodule(N, R):
    # Check closure under addition
    for x in N:
        for y in N:
            if R.add(x, y) not in N:
                return False
    # Check closure under scalar multiplication
    for r in R.elements:
        for x in N:
            if R.mul(r, x) not in N:
                return False
    return True

def is_divisible(N, R):
    # A module N is divisible if rN = N for all regular elements r in R
    for r in R.regular_elements():
        rN = set(R.mul(r, x) for x in N)
        if rN != set(N):
            return False
    return True

