import itertools

class RingElement:
    """
    Represents an element in the ring R = F_2[x, y] / (x^2, xy, y^2).
    Elements are of the form a + bx + cy, represented as a tuple (a, b, c).
    """
    def __init__(self, a, b, c):
        self.a = a % 2
        self.b = b % 2
        self.c = c % 2

    def __add__(self, other):
        return RingElement(self.a + other.a, self.b + other.b, self.c + other.c)

    def __mul__(self, other):
        # Multiplication uses the relations x^2 = 0, xy = 0, y^2 = 0
        return RingElement(
            self.a * other.a,
            self.a * other.b + self.b * other.a,
            self.a * other.c + self.c * other.a
        )

    def __eq__(self, other):
        return (self.a == other.a) and (self.b == other.b) and (self.c == other.c)

    def __hash__(self):
        return hash((self.a, self.b, self.c))

    def __repr__(self):
        return f"({self.a}, {self.b}, {self.c})"

# Construct all 8 elements of the ring R
R = [RingElement(a, b, c) for a, b, c in itertools.product([0, 1], repeat=3)]

# Let I be the ideal generated by x and y
x = RingElement(0, 1, 0)
y = RingElement(0, 0, 1)

# Construct the ideal I = {r1*x + r2*y | r1, r2 in R}
