# By construction, I is generated by the finite set {x, y}.
is_finitely_generated = True
assert is_finitely_generated, "I must be finitely generated"

# Check if I is a principal ideal
# I is principal if there exists some generator g in I such that I = {r * g | r in R}
is_principal = False
for g in I_elements:
    principal_ideal_g = set(r * g for r in R)
    if principal_ideal_g == I_elements:
        is_principal = True
        break

# Conclusion must FAIL: I is NOT a principal ideal of R
assert not is_principal, "Conclusion holds: I is a principal ideal. Not a valid counterexample."

print("Counterexample found!")
print(f"Ring R size: {len(R)}")
print(f"Ideal I size: {len(I_elements)}")
print("I is finitely generated by {x, y}, but cannot be generated by any single element.")

import itertools

# R is the ring Z/2Z
R = {0, 1}

def add(a, b):
    return (a + b) % 2

def mul(a, b):
    return (a * b) % 2

# Check remaining hypothesis: R is a commutative ring with identity
assert all(mul(a, b) == mul(b, a) for a in R for b in R), "R is not commutative"
identity = 1
assert all(mul(a, identity) == a for a in R), "R does not have an identity"

# We choose M to be the entire ring R. 
# This violates the dropped hypothesis "M is a proper ideal".
M = {0, 1}

def is_ideal(S):
    if not S:
        return False
    # Check closure under subtraction
    for a in S:
        for b in S:
            if (a - b) % 2 not in S:
                return False
    # Check closure under multiplication by any element in R
    for r in R:
        for m in S:
            if mul(r, m) not in S:
                return False
    return True

# Ensure M is at least an ideal
assert is_ideal(M), "M is not an ideal"

# Evaluate P: "M is a maximal ideal"
# By definition, a maximal ideal MUST be a proper ideal.
proper_ideals = [set(comb) for L in range(1, len(R)) for comb in itertools.combinations(R, L) if is_ideal(set(comb))]

is_proper = is_ideal(M) and M != R
if not is_proper:
    P = False
else:
    P = not any(M.issubset(I) and M != I for I in proper_ideals)

# Evaluate Q: "for every element x \in R \setminus M, the ideal generated by M and x is equal to R"
def ideal_generated_by(S):
    all_ideals = [set(comb) for L in range(1, len(R)+1) for comb in itertools.combinations(R, L) if is_ideal(set(comb))]
    containing_ideals = [I for I in all_ideals if S.issubset(I)]
    intersection = set(R)
    for I in containing_ideals:
        intersection = intersection.intersection(I)
    return intersection

Q = True
for x in R:
    if x not in M:
        gen = ideal_generated_by(M.union({x}))
        if gen != R:
            Q = False
            break

# The conclusion is the biconditional: P <-> Q
conclusion_holds = (P == Q)

# Since M = R, R \setminus M is empty, making Q vacuously True.
# However, M is not proper, making P False. 
# Thus, the biconditional evaluates to False.
assert not conclusion_holds, f"Conclusion should be False, but got P={P}, Q={Q}"

import math

class MatrixIdeal:
    """
    Represents a two-sided ideal in the non-commutative ring R = [[k, V], [0, k]] 
    where k is a field and V is an infinite-dimensional vector space over k.

    Ideals are classified by their components:
    'I_W': [[0, W], [0, 0]] for a subspace W of V.
    'J1':  [[k, V], [0, 0]]
    'J2':  [[0, V], [0, k]]
    'R':   [[k, V], [0, k]]
    """
    def __init__(self, type_str, dim=0):
        self.type_str = type_str
        self.dim = dim # Dimension of W, use math.inf for infinite dimensional

    def __eq__(self, other):
        if not isinstance(other, MatrixIdeal):
            return False
        if self.type_str != other.type_str:
            return False
        if self.type_str == 'I_W':
            return self.dim == other.dim
        return True

    def __hash__(self):
        return hash((self.type_str, self.dim))

    def __repr__(self):
        if self.type_str == 'I_W':
            return f"I_W(dim={self.dim})"
        return self.type_str

    def is_finitely_generated(self):
        # I_W is finitely generated as a two-sided ideal iff W is finite-dimensional
        if self.type_str == 'I_W':
            return self.dim != math.inf
        # J1, J2, and R are generated by 1 element as two-sided ideals
        return True

    def contains(self, other):
        if self == other:
            return True
        if self.type_str == 'R':
            return True
        if self.type_str == 'J1':
            return other.type_str == 'I_W'
        if self.type_str == 'J2':
            return other.type_str == 'I_W'
        if self.type_str == 'I_W':
            if other.type_str == 'I_W':
                return self.dim >= other.dim
            return False
        return False

    def __mul__(self, other):
        # Multiplication of two-sided ideals
        if self.type_str == 'R':
            return other
        if other.type_str == 'R':
            return self

        if self.type_str == 'I_W' and other.type_str == 'I_W':
            return MatrixIdeal('I_W', 0)

        if self.type_str == 'J1':
            if other.type_str == 'I_W':
                return other
            if other.type_str == 'J1':
                return self
            if other.type_str == 'J2':
                return MatrixIdeal('I_W', math.inf) # J1 * J2 = I_V

        if self.type_str == 'J2':
            if other.type_str == 'I_W':
                return MatrixIdeal('I_W', 0)
            if other.type_str == 'J1':
                return MatrixIdeal('I_W', 0)
            if other.type_str == 'J2':
                return self

        if self.type_str == 'I_W':
            if other.type_str == 'J1':
                return MatrixIdeal('I_W', 0)
            if other.type_str == 'J2':
                return self

        return MatrixIdeal('I_W', 0)

# Define the ideals
I_V = MatrixIdeal('I_W', math.inf)
J1 = MatrixIdeal('J1')
J2 = MatrixIdeal('J2')
R_ideal = MatrixIdeal('R')

# The set of all ideals we care about for the prime check
all_ideals = [
    MatrixIdeal('I_W', 0),
    MatrixIdeal('I_W', 1),
    I_V,
    J1,
    J2,
    R_ideal
]

# Hypothesis 1: I_V is an ideal of R
# (implicitly true by our construction of MatrixIdeal)
assert isinstance(I_V, MatrixIdeal)

# Hypothesis 2: I_V is maximal with respect to not being finitely generated
assert not I_V.is_finitely_generated(), "I_V should not be finitely generated"

# In our ring, any ideal strictly containing I_V must be J1, J2, or R.
super_ideals = [J1, J2, R_ideal]
for J in super_ideals:
    assert J.contains(I_V), f"{J} should contain I_V"
    assert J != I_V, f"{J} should strictly contain I_V"
    assert J.is_finitely_generated(), f"{J} should be finitely generated"

# Conclusion: I_V is a prime ideal.
# A prime ideal P means for any ideals A, B: if A * B <= P, then A <= P or B <= P.
def is_prime_ideal(P, ideals):
    for A in ideals:
        for B in ideals:
            if P.contains(A * B):
                if not P.contains(A) and not P.contains(B):
                    return False
    return True

# The conclusion must fail (I_V is NOT a prime ideal)
assert not is_prime_ideal(I_V, all_ideals), "I_V should not be a prime ideal"

# Specifically, J1 * J2 <= I_V, but J1 not <= I_V and J2 not <= I_V
assert I_V.contains(J1 * J2)
assert not I_V.contains(J1)
assert not I_V.contains(J2)

print("Counterexample found!")
print("Ring R: Upper triangular matrices [[k, V], [0, k]] with dim(V) = infinity")
print("Ideal I_V: [[0, V], [0, 0]] is maximal wrt not being finitely generated")
print("But I_V is NOT prime because J1 * J2 = I_V, yet J1 \u2288 I_V and J2 \u2288 I_V")

