class Z4Ring:
    """
    Represents the ring of integers modulo 4 (Z/4Z).
    """
    def __init__(self):
        self.elements = [0, 1, 2, 3]
        self.zero = 0
        self.one = 1

    def add(self, a, b):
        return (a + b) % 4

    def mul(self, a, b):
        return (a * b) % 4

    def is_ring(self):
        # Check associativity of addition and multiplication, and distributivity
        for a, b, c in itertools.product(self.elements, repeat=3):
            if self.add(self.add(a, b), c) != self.add(a, self.add(b, c)): 
                return False
            if self.mul(self.mul(a, b), c) != self.mul(a, self.mul(b, c)): 
                return False
            if self.mul(a, self.add(b, c)) != self.add(self.mul(a, b), self.mul(a, c)): 
                return False
            if self.mul(self.add(a, b), c) != self.add(self.mul(a, c), self.mul(b, c)): 
                return False
        return True

    def is_commutative(self):
        # Check if multiplication is commutative
        for a, b in itertools.product(self.elements, repeat=2):
            if self.mul(a, b) != self.mul(b, a):
                return False
        return True

    def has_identity(self):
        # Check if 1 acts as the multiplicative identity
        for a in self.elements:
            if self.mul(a, self.one) != a or self.mul(self.one, a) != a:
                return False
        return True

    def is_field(self):
        # A field requires every non-zero element to have a multiplicative inverse
        for a in self.elements:
            if a != self.zero:
                has_inverse = any(self.mul(a, b) == self.one for b in self.elements)
                if not has_inverse:
                    return False
        return True

