# when the hypothesis "Q is an ideal of R" is dropped.

def is_ideal(subset, ring_n):
    if 0 not in subset:
        return False
    # closed under addition
    for a in subset:
        for b in subset:
            if (a + b) % ring_n not in subset:
                return False
    # closed under multiplication by R
    for a in subset:
        for r in range(ring_n):
            if (a * r) % ring_n not in subset:
                return False
    return True

def is_primary_ideal(subset, ring_n):
    if not is_ideal(subset, ring_n):
        return False
    if len(subset) == ring_n:
        return False # must be a proper ideal
    for a in range(ring_n):
        for b in range(ring_n):
            if (a * b) % ring_n in subset:
                if a not in subset:
                    # check if b^k in subset for some k > 0
                    b_pow = b
                    found = False
                    for _ in range(ring_n):
                        if b_pow in subset:
                            found = True
                            break
                        b_pow = (b_pow * b) % ring_n
                    if not found:
                        return False
    return True

