# Define the ring R = Z/4Z
R = {0, 1, 2, 3}

def add(a, b):
    return (a + b) % 4

def mul(a, b):
    return (a * b) % 4

# Verify R is a commutative ring with identity
assert 1 in R, "R must have an identity element"
for a in R:
    assert mul(a, 1) == a
    assert mul(1, a) == a
    for b in R:
        assert add(a, b) == add(b, a)
        assert mul(a, b) == mul(b, a)
        for c in R:
            assert add(add(a, b), c) == add(a, add(b, c))
            assert mul(mul(a, b), c) == mul(a, mul(b, c))
            assert mul(a, add(b, c)) == add(mul(a, b), mul(a, c))

def powerset(iterable):
    s = list(iterable)
    return itertools.chain.from_iterable(itertools.combinations(s, r) for r in range(len(s)+1))

# Find all ideals of R
ideals = []
for subset in powerset(R):
    if not subset:
        continue
    subset = set(subset)
    is_ideal = True
    for a in subset:
        for b in subset:
            if add(a, b) not in subset:
                is_ideal = False
                break
        for r in R:
            if mul(a, r) not in subset:
                is_ideal = False
                break
    if is_ideal:
