import itertools

class GF2:
    """Representation of the finite field GF(2)"""
    elements = [0, 1]

    @staticmethod
    def add(a, b):
        return (a + b) % 2

    @staticmethod
    def mul(a, b):
        return (a * b) % 2

    @staticmethod
    def is_unit(a):
        # In GF(2), 1 is the only unit
        return a == 1

    @staticmethod
    def is_irreducible(a):
        # By definition, an irreducible element must be non-zero and not a unit.
        if a == 0 or GF2.is_unit(a):
            return False
        return False

    @staticmethod
    def principal_ideal(a):
        # The principal ideal generated by a: (a) = {r * a | r in R}
        return set(GF2.mul(a, r) for r in GF2.elements)

    @staticmethod
    def is_ideal(subset):
        if not subset:
            return False
        # Check closure under addition
        for x in subset:
            for y in subset:
                if GF2.add(x, y) not in subset:
                    return False
        # Check closure under multiplication by any ring element
        for x in subset:
            for r in GF2.elements:
                if GF2.mul(x, r) not in subset:
                    return False
        return True

    @classmethod
    def get_all_ideals(cls):
        subsets = [ [], [0], [1], [0, 1] ]
        return [set(s) for s in subsets if cls.is_ideal(set(s))]

    @classmethod
    def is_maximal_ideal(cls, ideal):
        ideal = set(ideal)
        if ideal == set(cls.elements):
            return False  # A maximal ideal cannot be the whole ring
        all_ideals = cls.get_all_ideals()
        for other in all_ideals:
            if ideal.issubset(other) and ideal != other and other != set(cls.elements):
                return False
        return True

    @classmethod
    def is_integral_domain(cls):
        # Check 1 != 0
        if 1 == 0:
            return False
        # Check for zero divisors
        for x in cls.elements:
            for y in cls.elements:
                if x != 0 and y != 0 and cls.mul(x, y) == 0:
                    return False
        return True

