import random

class Element:
    def __init__(self, components):
        # components: dict n -> (e, k) where element in G_n is s^e r^k
        self.components = {n: (e, k) for n, (e, k) in components.items() if (e % 2, k % (2**(n+1))) != (0, 0)}

    def __mul__(self, other):
        res = {}
        keys = set(self.components.keys()) | set(other.components.keys())
        for n in keys:
            e1, k1 = self.components.get(n, (0, 0))
            e2, k2 = other.components.get(n, (0, 0))
            e3 = (e1 + e2) % 2
            sign = -1 if e2 == 1 else 1
            k3 = (sign * k1 + k2) % (2**(n+1))
            if (e3, k3) != (0, 0):
                res[n] = (e3, k3)
        return Element(res)

    def inv(self):
        res = {}
        for n, (e, k) in self.components.items():
            sign = -1 if e == 1 else 1
            k_inv = (sign * (-k)) % (2**(n+1))
            res[n] = (e, k_inv)
        return Element(res)

    def __eq__(self, other):
        return self.components == other.components

    def is_identity(self):
        return len(self.components) == 0

def commutator(x, y):
    return x.inv() * y.inv() * x * y

def is_in_frattini(x):
    # In G = \bigoplus D_{2^{n+2}}, Phi(G) is the set of elements where each component is in Phi(D_{2^{n+2}}).
    # Phi(D_{2^{n+2}}) = <r^2>, so the 'e' part must be 0, and 'k' must be even.
    for n, (e, k) in x.components.items():
        if e != 0 or k % 2 != 0:
            return False
    return True

