def is_nilpotent(max_c=20):
    # A nilpotent group must have a finite nilpotency class c, meaning ALL commutators of length c+1 vanish.
    # We show that for every c up to max_c, there is a commutator of length c+1 that does NOT vanish.
    # Therefore, the group cannot have nilpotency class <= max_c.
    # Since this holds for arbitrarily large max_c, the group is not nilpotent.
    for c in range(1, max_c + 1):
        # In D_{2^{c+2}}, the nilpotency class is c+1.
        # So taking c commutators of s and r will not yield identity.
        # Let's compute [ ... [[r, s], s], ... ] c times in component c+1
        n = c + 1
        r = Element({n: (0, 1)})
        s = Element({n: (1, 0)})

        val = r
        for _ in range(c):
            val = commutator(val, s)

        if val.is_identity():
            return True # This particular commutator vanished, which shouldn't happen for our chosen elements if class > c
    return False # Found non-vanishing commutators for all tested lengths

