import itertools

class Z_n:
    def __init__(self, n):
        self.n = n
        self.elements = list(range(n))
        self.zero = 0
        self.one = 1

    def add(self, a, b):
        return (a + b) % self.n

    def mul(self, a, b):
        return (a * b) % self.n

    def neg(self, a):
        return (self.n - a) % self.n

def check_commutative_ring_with_identity(ring):
    R = ring.elements
    # Addition properties
    for a, b, c in itertools.product(R, R, R):
        assert ring.add(ring.add(a, b), c) == ring.add(a, ring.add(b, c))
    for a, b in itertools.product(R, R):
        assert ring.add(a, b) == ring.add(b, a)
    for a in R:
        assert ring.add(a, ring.zero) == a
        assert ring.add(a, ring.neg(a)) == ring.zero

    # Multiplication properties
    for a, b, c in itertools.product(R, R, R):
        assert ring.mul(ring.mul(a, b), c) == ring.mul(a, ring.mul(b, c))
    for a, b in itertools.product(R, R):
        assert ring.mul(a, b) == ring.mul(b, a)
    for a in R:
        assert ring.mul(a, ring.one) == a

    # Distributive properties
    for a, b, c in itertools.product(R, R, R):
        assert ring.mul(a, ring.add(b, c)) == ring.add(ring.mul(a, b), ring.mul(a, c))

    # 1 != 0
    assert ring.one != ring.zero

def can_embed_in_field(ring):
    """
    A commutative ring with identity can be embedded into a field 
    if and only if it is an integral domain (has no zero divisors).
    """
    for a, b in itertools.product(ring.elements, ring.elements):
        if a != ring.zero and b != ring.zero:
            if ring.mul(a, b) == ring.zero:
                # Found zero divisors, so it cannot be embedded in a field
                return False
    return True

if __name__ == "__main__":
    # Counterexample: Z/4Z
    R = Z_n(4)

    # Verify remaining hypotheses: R is a commutative ring with identity
    check_commutative_ring_with_identity(R)

    # Verify conclusion fails: R cannot be embedded in a field
    conclusion_holds = can_embed_in_field(R)
    assert not conclusion_holds, "Conclusion should fail: Z/4Z cannot be embedded in a field"

    print("Counterexample verified: Z/4Z is a commutative ring with identity that cannot be embedded in a field.")

