class Group:
    def __init__(self, elements, op):
        self.elements = elements
        self.op = op
        self.identity = self._find_identity()

    def _find_identity(self):
        for e in self.elements:
            if all(self.op(e, x) == x and self.op(x, e) == x for x in self.elements):
                return e
        return None

    def is_group(self):
        # check closure
        for a in self.elements:
            for b in self.elements:
                if self.op(a, b) not in self.elements:
                    return False
        # check associativity
        for a in self.elements:
            for b in self.elements:
                for c in self.elements:
                    if self.op(self.op(a, b), c) != self.op(a, self.op(b, c)):
                        return False
        # check identity
        if self.identity is None:
            return False
        # check inverses
        for a in self.elements:
            has_inv = False
            for b in self.elements:
                if self.op(a, b) == self.identity and self.op(b, a) == self.identity:
                    has_inv = True
                    break
            if not has_inv:
                return False
        return True

    def is_subgroup(self, subset):
        if self.identity not in subset:
            return False
        for a in subset:
            for b in subset:
                if self.op(a, b) not in subset:
                    return False
            # inverse
            has_inv = False
            for b in subset:
                if self.op(a, b) == self.identity and self.op(b, a) == self.identity:
                    has_inv = True
                    break
            if not has_inv:
                return False
        return True

    def is_normal_subgroup(self, subset):
        if not self.is_subgroup(subset):
            return False
        # g * n * g^-1 in subset
        for g in self.elements:
            # find inv of g
            g_inv = None
            for x in self.elements:
                if self.op(g, x) == self.identity and self.op(x, g) == self.identity:
                    g_inv = x
                    break
            for n in subset:
                if self.op(g, self.op(n, g_inv)) not in subset:
                    return False
        return True

    def normal_subgroups(self):
        subgroups = []
        n = len(self.elements)
        for r in range(1, n + 1):
            for subset in itertools.combinations(self.elements, r):
                if self.is_normal_subgroup(subset):
                    subgroups.append(set(subset))
        return subgroups

    def is_subdirectly_irreducible(self):
        if len(self.elements) <= 1:
            return False
        ns = self.normal_subgroups()
        non_trivial_ns = [s for s in ns if len(s) > 1]
        if not non_trivial_ns:
            return False
        intersection = non_trivial_ns[0]
        for s in non_trivial_ns[1:]:
            intersection = intersection.intersection(s)
        return len(intersection) > 1

