    def __init__(self, terms):
        self.terms = {}
        for monom, coeff in terms.items():
            if coeff == 0:
                continue

            m_dict = {}
            for v, d in monom:
                m_dict[v] = m_dict.get(v, 0) + d

            is_zero = False
            simplified_monom = []
            for v, d in sorted(m_dict.items()):
                # The ideal is generated by x_i^{i+1}, so if degree >= i+1, the term is 0
                if d >= v + 1:
                    is_zero = True
                    break
                if d > 0:
                    simplified_monom.append((v, d))

            if not is_zero:
                simplified_monom = tuple(simplified_monom)
                self.terms[simplified_monom] = self.terms.get(simplified_monom, 0) + coeff
                if self.terms[simplified_monom] == 0:
                    del self.terms[simplified_monom]

    def __eq__(self, other):
        if not isinstance(other, PolyRingElement):
            return False
        return self.terms == other.terms

    def __add__(self, other):
        new_terms = dict(self.terms)
        for m, c in other.terms.items():
            new_terms[m] = new_terms.get(m, 0) + c
        return PolyRingElement(new_terms)

    def __neg__(self):
        new_terms = {m: -c for m, c in self.terms.items()}
        return PolyRingElement(new_terms)

    def __sub__(self, other):
        return self + (-other)

    def __mul__(self, other):
        new_terms = {}
        for m1, c1 in self.terms.items():
            for m2, c2 in other.terms.items():
                m_dict = dict(m1)
                for v, d in m2:
                    m_dict[v] = m_dict.get(v, 0) + d
                m_new = tuple(m_dict.items())
                new_terms[m_new] = new_terms.get(m_new, 0) + c1 * c2
        return PolyRingElement(new_terms)

    def __pow__(self, power):
        if power == 0:
            return PolyRingElement({(): 1})
        res = PolyRingElement({(): 1})
        base = self
        for _ in range(power):
            res = res * base
        return res

    def is_zero(self):
        return len(self.terms) == 0

def is_commutative():
    # Test commutativity on some generators and combinations
    x1 = PolyRingElement({((1, 1),): 1})
    x2 = PolyRingElement({((2, 1),): 1})
    x3 = PolyRingElement({((3, 1),): 1})

    a = x1 + x2 * x3
    b = x2 + x1 * x3

    return a * b == b * a

def nilradical_is_nilpotent(max_K=50):
    """
    Checks if the nilradical N is nilpotent by testing if N^K == 0 for some K <= max_K.
    If N^K == 0, then for any x in N, x^K == 0.
    We check if there is any K where all nilpotent generators raised to K are zero.
    """
    for K in range(1, max_K + 1):
        # x_K is nilpotent because x_K^{K+1} = 0
        x_K = PolyRingElement({((K, 1),): 1})

        # Verify x_K is indeed in the nilradical
        assert (x_K ** (K + 1)).is_zero(), f"x_{K} should be nilpotent"

        # If N^K == 0, then x_K^K must be 0.
        if (x_K ** K).is_zero():
            # If we find a K where x_K^K == 0, it might be nilpotent.
            # But in our ring, x_K^K is never zero.
            return True

    # If for all K <= max_K, we found an element in N whose K-th power is not zero,
    # then N is not nilpotent (up to our check bound).
    return False

if __name__ == "__main__":
    # 1. R is a commutative ring
    assert is_commutative(), "The ring must be commutative"

    # 2. The nilradical of R is a nilpotent ideal (This must be FALSE)
    # We assert that the nilradical is NOT nilpotent
    assert not nilradical_is_nilpotent(max_K=50), "The nilradical should NOT be nilpotent"

    print("Counterexample found!")
    print("Ring R = Q[x_1, x_2, ...] / (x_1^2, x_2^3, x_3^4, ...)")
    print("R is commutative, but its nilradical is not nilpotent.")

