    sub_elements = set(sub_elements)
    if id_perm not in sub_elements:
        return False
    for a in sub_elements:
        for b in sub_elements:
            if a * b not in sub_elements:
                return False
    return True

def is_normal_subgroup(sub_elements, group):
    if not is_subgroup(sub_elements, group):
        return False
    sub_elements = set(sub_elements)
    for g in G_elements:
        for n in sub_elements:
            if g * n * (~g) not in sub_elements:
                return False
    return True

