assert is_commutative, "R must be commutative"

has_unity = any(all(a * e == a and e * a == a for a in elements) for e in elements)
assert has_unity, "R must be a ring with unity"

# Hypothesis 1: R is an Artinian ring
# A finite ring is always Artinian because any descending chain of ideals must stabilize.
is_finite = len(elements) == 6
assert is_finite, "R must be Artinian (finite implies Artinian)"

# Find all ideals of R
all_ideals = set()
for r in range(1, 1 << 6):
    subset = frozenset(elements[i] for i in range(6) if (r & (1 << i)))
    # An ideal must contain 0
    if Z6(0) not in subset:
        continue

    is_ideal = True
    for a in subset:
        # Closed under addition
        for b in subset:
            if a + b not in subset:
                is_ideal = False
                break
        if not is_ideal:
            break
        # Closed under multiplication by any ring element
        for r_elem in elements:
            if r_elem * a not in subset:
                is_ideal = False
                break
        if not is_ideal:
