            break
    if is_maximal:
        maximal_ideals.append(I)

# A local ring is defined as having exactly one maximal ideal.
is_local = (len(maximal_ideals) == 1)

# CONCLUSION MUST FAIL: R is NOT a local ring
assert not is_local, "Conclusion holds: R is a local ring, which invalidates the counterexample."
assert len(maximal_ideals) == 2, "Z6 should have exactly 2 maximal ideals, proving it is not local."

