class RingElement:
    """
    Represents an element in the Jacobson algebra (Toeplitz algebra) over the integers.
    Basis elements are of the form b^i a^j, represented by the tuple (i, j).
    The algebra is generated by a and b with the relation a * b = 1.
    """
    def __init__(self, coeffs):
        self.coeffs = {k: v for k, v in coeffs.items() if v != 0}

    def __mul__(self, other):
        res = {}
        for (i, j), c1 in self.coeffs.items():
            for (k, l), c2 in other.coeffs.items():
                if j <= k:
                    new_i = i + k - j
                    new_j = l
                else:
                    new_i = i
                    new_j = l + j - k
                res[(new_i, new_j)] = res.get((new_i, new_j), 0) + c1 * c2
        return RingElement(res)

    def __eq__(self, other):
        if not isinstance(other, RingElement):
            return False
        return self.coeffs == other.coeffs

    def __repr__(self):
        if not self.coeffs:
            return "0"
        terms = []
        for (i, j), c in self.coeffs.items():
            term = ""
            if c != 1 or (i == 0 and j == 0):
                term += str(c)
            if i > 0:
                term += f"b^{i}"
            if j > 0:
                term += f"a^{j}"
            terms.append(term)
        return " + ".join(terms)

