    def __eq__(self, other):
        if not isinstance(other, InfPoly):
            return False
        return self.terms == other.terms

    def __str__(self):
        if not self.terms:
            return "0"
        terms_str = []
        for m, c in self.terms.items():
            if not m:
                terms_str.append(str(c))
            else:
                m_str = "*".join(f"x_{v}^{e}" if e > 1 else f"x_{v}" for v, e in sorted(m))
                if c == 1:
                    terms_str.append(m_str)
                elif c == -1:
                    terms_str.append("-" + m_str)
                else:
                    terms_str.append(f"{c}*{m_str}")
        return " + ".join(terms_str)

