one = InfPoly({frozenset(): 1})

def f(p):
    """
    The endomorphism f: R -> R
    Defined by f(x_i) = x_{i-1} for i > 1, and f(x_1) = 0.
    """
    res = {}
    for m, c in p.terms.items():
        m_new = {}
        drop = False
        for v, e in m:
            if v == 1:
                drop = True
                break
            else:
                m_new[v - 1] = e
        if not drop:
            res[frozenset(m_new.items())] = c
    return InfPoly(res)

