import itertools

class FiniteRing:
    def __init__(self, elements, add_table, mul_table):
        self.elements = elements
        self.add_table = add_table
        self.mul_table = mul_table
        self.n = len(elements)

    def add(self, x, y):
        return self.add_table[x][y]

    def mul(self, x, y):
        return self.mul_table[x][y]

    def is_commutative(self):
        for x in self.elements:
            for y in self.elements:
                if self.mul(x, y) != self.mul(y, x):
                    return False
        return True

    def has_identity(self):
        for e in self.elements:
            is_id = True
            for x in self.elements:
                if self.mul(e, x) != x or self.mul(x, e) != x:
                    is_id = False
                    break
            if is_id:
                return True
        return False

    def get_ideals(self):
        ideals = []
        for r in range(1, self.n + 1):
            for subset in itertools.combinations(self.elements, r):
                if 0 not in subset:
                    continue
                subset_set = frozenset(subset)

                # Check addition closure
                add_closed = True
                for x in subset_set:
                    for y in subset_set:
                        if self.add(x, y) not in subset_set:
                            add_closed = False
                            break
                    if not add_closed:
                        break
                if not add_closed:
                    continue

                # Check ideal property
                ideal_closed = True
                for r_elem in self.elements:
                    for x in subset_set:
                        if self.mul(r_elem, x) not in subset_set or self.mul(x, r_elem) not in subset_set:
                            ideal_closed = False
                            break
                    if not ideal_closed:
                        break
                if ideal_closed:
                    ideals.append(subset_set)
        return ideals

    def get_prime_ideals(self):
        ideals = self.get_ideals()
        prime_ideals = []
        for I in ideals:
            if len(I) == self.n:
                continue # Prime ideals must be proper
            is_prime = True
            for x in self.elements:
                for y in self.elements:
                    if self.mul(x, y) in I:
                        if x not in I and y not in I:
                            is_prime = False
                            break
                if not is_prime:
                    break
            if is_prime:
                prime_ideals.append(I)
        return prime_ideals

    def krull_dimension(self):
        primes = self.get_prime_ideals()
        if not primes:
            # The supremum of lengths of chains of prime ideals when there are no prime ideals is -infinity.
            return float('-inf')

        def dfs(p):
            max_len = 0
            for q in primes:
                if p.issubset(q) and p != q:
                    max_len = max(max_len, 1 + dfs(q))
            return max_len

        return max(dfs(p) for p in primes)

# Construct the counterexample: Zero ring on Z/2Z
# This is a ring with 2 elements where all products are 0.
elements = [0, 1]
add_table = [[0, 1], [1, 0]]
mul_table = [[0, 0], [0, 0]]

R = FiniteRing(elements, add_table, mul_table)

# Hypothesis 1: R is a commutative ring
assert R.is_commutative(), "R must be commutative"

# Hypothesis 2: R is Artinian
# Any finite ring is Artinian because it has only finitely many ideals, guaranteeing the Descending Chain Condition.
ideals = R.get_ideals()
assert len(ideals) < float('inf'), "R is finite, hence Artinian"

# Confirm the dropped hypothesis is indeed absent
assert not R.has_identity(), "R should not have a multiplicative identity"

# Evaluate Conclusion: Krull dimension is exactly zero
k_dim = R.krull_dimension()

# The conclusion MUST fail. 
# For this ring, there are no prime ideals, so the Krull dimension is -inf, not 0.
assert k_dim != 0, f"Logic error: conclusion holds! Krull dimension is {k_dim}, expected not 0"

print("Counterexample found!")
print(f"Ring elements: {R.elements}")
print(f"Prime ideals: {R.get_prime_ideals()}")
print(f"Krull dimension: {k_dim} != 0")

