import random

def multiplicity(p, n):
    if n == 0:
        return float('inf')
    n = abs(n)
    count = 0
    while n % p == 0:
        count += 1
        n //= p
    return count

def v(x):
    if x == 0:
        return float('inf')
    # x is a sympy.Rational or sympy.Integer
    num, den = x.as_numer_denom()
    return multiplicity(2, int(num)) - multiplicity(2, int(den))

