# v is the 2-adic valuation

# Remaining hypothesis 1: v is a valuation on K
# We verify the valuation axioms on a sample of elements from Q.
sample_elements = [sympy.Rational(random.randint(-50, 50), random.randint(1, 50)) for _ in range(50)]

for a in sample_elements:
    for b in sample_elements:
        # Axiom 1: v(a * b) = v(a) + v(b)
        if a != 0 and b != 0:
            assert v(a * b) == v(a) + v(b), "Valuation product axiom failed"

        # Axiom 2: v(a + b) >= min(v(a), v(b))
        if a + b != 0:
            assert v(a + b) >= min(v(a), v(b)), "Valuation addition axiom failed"

# Remaining hypothesis 2: Gamma is the value group of v
# The value group Gamma of v on Q is exactly Z.
# We can demonstrate this by finding elements in Q that map to any integer.
def get_element_with_value(k):
    if k >= 0:
        return sympy.Rational(2**k, 1)
    else:
        return sympy.Rational(1, 2**(-k))

for k in range(-10, 10):
    assert v(get_element_with_value(k)) == k, "Value group does not contain k"

# Conclusion: Gamma is a divisible abelian group.
# A group Gamma is divisible if for every g in Gamma and every integer n > 0,
# there exists h in Gamma such that n * h = g.
# Here, Gamma = Z. We test with g = 1 and n = 2.
# If Gamma were divisible, there would be an element h in Gamma such that 2 * h = 1.

g = v(sympy.Rational(2, 1))  # g = 1, which is in Gamma
n = 2

# Check if there exists h in Gamma (which is Z) such that n * h = g
# Since Z is discrete, n * h = g has a solution in Z iff g % n == 0
gamma_is_divisible = (g % n == 0)

# The conclusion must FAIL
assert not gamma_is_divisible, "Conclusion holds: Gamma is divisible, but it shouldn't be!"

print("Counterexample found!")
print("Field K = Q")
print("Valuation v = 2-adic valuation")
print("Value group Gamma = Z")
print(f"Gamma is not divisible because there is no h in Z such that {n} * h = {g}")

import itertools

class Z4:
    """Representation of the ring Z/4Z"""
    def __init__(self):
        self.elements = [0, 1, 2, 3]

    def add(self, a, b):
        return (a + b) % 4

    def mul(self, a, b):
        return (a * b) % 4

def is_ideal(subset, ring):
    """Check if a subset is a two-sided ideal of the ring."""
    # Check closure under addition
    for a in subset:
        for b in subset:
            if ring.add(a, b) not in subset:
                return False

    # Check two-sided absorption property
    for x in subset:
        for r in ring.elements:
            if ring.mul(x, r) not in subset:
                return False
            if ring.mul(r, x) not in subset:
                return False

    return True

def get_all_ideals(ring):
    """Find all two-sided ideals of the ring."""
    ideals = []
    for r in range(1, len(ring.elements) + 1):
        for subset in itertools.combinations(ring.elements, r):
            if 0 not in subset:
                continue
            subset_set = frozenset(subset)
            if is_ideal(subset_set, ring):
                ideals.append(subset_set)
    return ideals

# Construct the ring Z/4Z
R = Z4()

# Hypothesis 1: R is a right Artinian ring
# Any finite ring is right Artinian because any descending chain of right ideals 
# must eventually stabilize (since there are only finitely many subsets).
is_right_artinian = True
assert is_right_artinian, "A finite ring is always right Artinian."

# Conclusion: R is a simple ring
# A simple ring has exactly two two-sided ideals: the zero ideal {0} and the ring itself R.
ideals = get_all_ideals(R)
is_simple = (len(ideals) == 2)

# Verify that the conclusion FAILS (Z/4Z is NOT simple)
assert not is_simple, f"Z/4Z should not be simple, but found ideals: {ideals}"

print("Counterexample found: Z/4Z")
print("Z/4Z is a finite ring, thus it is right Artinian.")
print(f"Two-sided ideals of Z/4Z: {[set(i) for i in ideals]}")
print("Because it has a non-trivial proper ideal {0, 2}, it is NOT a simple ring.")

