def is_primary_ideal(R_elements, I_elements, mul_func):
    """
    An ideal I is primary if it is proper, and for all a, b in R,
    ab in I implies a in I or b^n in I for some n > 0.
    """
    # A primary ideal must be proper
    if set(I_elements) == set(R_elements):
        return False

    for a in R_elements:
        for b in R_elements:
            if mul_func(a, b) in I_elements:
                if a not in I_elements:
                    b_n = b
                    found = False
                    for n in range(1, len(R_elements) + 1):
                        if b_n in I_elements:
                            found = True
                            break
                        b_n = mul_func(b_n, b)
                    if not found:
                        return False
    return True

