from sympy.combinatorics import Permutation, PermutationGroup
import itertools

# Remaining hypotheses:
# [1] G is a group
# [2] H is a group

# We use Z_2 for both G and H, represented as permutation groups
id_perm = Permutation([0, 1])
trans = Permutation([1, 0])

G = PermutationGroup([trans])
H = PermutationGroup([trans])

# Verify remaining hypotheses
assert G.order() > 0, "G is a group"
assert H.order() > 0, "H is a group"

# S is a subset of G x H which is NOT a subgroup
S = { (id_perm, id_perm), (id_perm, trans), (trans, id_perm) }

def get_elements(group):
    return set(group.generate())

def get_coset(g, N):
    return frozenset([g * n for n in get_elements(N)])

# Subgroups of G and H (both are isomorphic to Z_2, so subgroups are trivial and the group itself)
subgroups_G = [PermutationGroup([id_perm]), G]
subgroups_H = [PermutationGroup([id_perm]), H]

conclusion_holds = False

# Iterate over all possible subgroups A <= A' <= G and B <= B' <= H
# Since G and H are abelian, all subgroups are normal, so A ◁ A' and B ◁ B' is automatically satisfied.
for A in subgroups_G:
    for A_prime in subgroups_G:
        if not get_elements(A).issubset(get_elements(A_prime)):
            continue

        for B in subgroups_H:
            for B_prime in subgroups_H:
                if not get_elements(B).issubset(get_elements(B_prime)):
                    continue

                # A'/A and B'/B must be isomorphic, so they must have the same order
                if A_prime.order() // A.order() != B_prime.order() // B.order():
                    continue

                cosets_A = {get_coset(g, A) for g in get_elements(A_prime)}
                cosets_B = {get_coset(h, B) for h in get_elements(B_prime)}

                id_coset_A = get_coset(id_perm, A)
                id_coset_B = get_coset(id_perm, B)

                non_id_A = list(cosets_A - {id_coset_A})
                non_id_B = list(cosets_B - {id_coset_B})

                # For groups of order 1 or 2, any bijection preserving the identity coset is an isomorphism
                for perm in itertools.permutations(non_id_B):
                    theta = {id_coset_A: id_coset_B}
                    for i in range(len(non_id_A)):
                        theta[non_id_A[i]] = perm[i]

                    candidate_S = set()
                    for g in get_elements(A_prime):
                        for h in get_elements(B_prime):
                            if theta[get_coset(g, A)] == get_coset(h, B):
                                candidate_S.add((g, h))

                    if candidate_S == S:
                        conclusion_holds = True
                        break
                if conclusion_holds: break
            if conclusion_holds: break
        if conclusion_holds: break

# The conclusion must fail because sets of the form {(g, h) | theta(gA) = hB} are always subgroups,
# and we deliberately chose S to not be a subgroup.
assert not conclusion_holds, "Conclusion holds but it should not! S is not a subgroup."

