    return (a + b) % 2

def mul_R(a, b):
    return (a * b) % 2

def add_S(u, v):
    return ((u[0] + v[0]) % 2, (u[1] + v[1]) % 2)

def mul_S(u, v):
    return ((u[0] * v[0]) % 2, (u[0] * v[1] + u[1] * v[0]) % 2)

# Define the ring homomorphism f: R -> S
def f(a):
    return (a, 0)

# Verify f is a valid ring homomorphism
for a in R:
    for b in R:
        assert f(add_R(a, b)) == add_S(f(a), f(b))
        assert f(mul_R(a, b)) == mul_S(f(a), f(b))
assert f(1) == (1, 0)  # Maps identity to identity

# Hypothesis [1]: R and S are commutative rings
for a in R:
    for b in R:
        assert mul_R(a, b) == mul_R(b, a)

for u in S:
    for v in S:
        assert mul_S(u, v) == mul_S(v, u)

# Hypothesis [2]: M is a maximal ideal of R
