def is_ideal_R(I):
    if not I: return False
    for a in I:
        for b in I:
            if add_R(a, b) not in I: return False
    for a in I:
        for r in R:
            if mul_R(r, a) not in I: return False
    return True

def is_maximal_R(I):
    if not is_ideal_R(I): return False
    if set(I) == set(R): return False
    for k in range(1, len(R) + 1):
        for subset in itertools.combinations(R, k):
            subset = list(subset)
            if set(I).issubset(set(subset)) and set(I) != set(subset):
                if is_ideal_R(subset) and set(subset) != set(R):
                    return False
    return True

