import itertools
from sympy.combinatorics import Permutation, PermutationGroup

def get_identity(G):
    for g in G.generate():
        if g * g == g:
            return g
    return Permutation()

def get_all_subgroups(G):
    elements = list(G.generate())
    subgroups = []
    ident = get_identity(G)
    for k in range(1, len(elements) + 1):
        if len(elements) % k != 0:
            continue
        for subset in itertools.combinations(elements, k):
            if ident not in subset:
                continue
            H = PermutationGroup(*subset)
            H_elems = list(H.generate())
            if len(H_elems) == k and set(H_elems) == set(subset):
                if not any(set(S.generate()) == set(subset) for S in subgroups):
                    subgroups.append(H)
    return subgroups

def is_normal(H, G):
    H_elems = set(H.generate())
    for h in H_elems:
        for g in list(G.generate()):
            if (~g * h * g) not in H_elems:
                return False
    return True

def is_nilpotent(H):
    series = [H]
    ident = get_identity(H)
    while True:
        comms = []
        for x in list(series[-1].generate()):
            for y in list(H.generate()):
                comms.append(x * y * ~x * ~y)
        next_H = PermutationGroup(*comms) if comms else PermutationGroup(ident)
        if len(list(next_H.generate())) == len(list(series[-1].generate())):
            break
        series.append(next_H)
    return len(list(series[-1].generate())) == 1

def fitting_subgroup(G, subgroups):
    F_elems = set([get_identity(G)])
    for H in subgroups:
        if is_normal(H, G) and is_nilpotent(H):
            F_elems.update(list(H.generate()))
    return PermutationGroup(*list(F_elems))

def is_perfect(H):
    comms = []
    for x in list(H.generate()):
        for y in list(H.generate()):
            comms.append(x * y * ~x * ~y)
    derived = PermutationGroup(*comms) if comms else PermutationGroup(get_identity(H))
    return len(list(derived.generate())) == len(list(H.generate())) and len(list(H.generate())) > 1

def center(H):
    Z_elems = []
    H_elems = list(H.generate())
    for x in H_elems:
        if all(x * y == y * x for y in H_elems):
            Z_elems.append(x)
    return PermutationGroup(*Z_elems) if Z_elems else PermutationGroup(get_identity(H))

def is_quasisimple(H, subgroups):
    if not is_perfect(H):
        return False
    Z = center(H)
    Z_elems = set(Z.generate())
    normal_containing_Z = 0
    for N in subgroups:
        if set(N.generate()).issubset(set(H.generate())):
            if is_normal(N, H) and Z_elems.issubset(set(N.generate())):
                normal_containing_Z += 1
    return normal_containing_Z == 2

def subnormal_subgroups(G, subgroups):
    subnormals = set()
    queue = [G]
    while queue:
        curr = queue.pop(0)
        curr_elems = frozenset(curr.generate())
        if curr_elems not in subnormals:
            subnormals.add(curr_elems)
            for N in subgroups:
                if set(N.generate()).issubset(curr_elems) and is_normal(N, curr):
                    queue.append(N)
    res = []
    for s in subnormals:
        for S in subgroups:
            if set(S.generate()) == set(s):
                res.append(S)
                break
    return res

def layer(G, subgroups):
    E_elems = set([get_identity(G)])
    for H in subnormal_subgroups(G, subgroups):
        if is_quasisimple(H, subgroups):
            E_elems.update(list(H.generate()))
    return PermutationGroup(*list(E_elems))

def generalized_fitting_subgroup(G):
    subgroups = get_all_subgroups(G)
    F = fitting_subgroup(G, subgroups)
    E = layer(G, subgroups)
    gens = list(F.generate()) + list(E.generate())
    return PermutationGroup(*gens)

