import itertools

class FiniteCofiniteSet:
    """
    Represents a subset of the natural numbers that is either finite or cofinite.
    This family of sets forms a Boolean ring under symmetric difference (addition)
    and intersection (multiplication).
    """
    def __init__(self, is_cofinite, elements):
        self.is_cofinite = bool(is_cofinite)
        self.elements = frozenset(elements)

    def __add__(self, other):
        # Addition in the ring is symmetric difference
        new_is_cofinite = self.is_cofinite ^ other.is_cofinite
        new_elements = self.elements ^ other.elements
        return FiniteCofiniteSet(new_is_cofinite, new_elements)

    def __mul__(self, other):
        # Multiplication in the ring is intersection
        if not self.is_cofinite and not other.is_cofinite:
            return FiniteCofiniteSet(False, self.elements & other.elements)
        elif self.is_cofinite and not other.is_cofinite:
            return FiniteCofiniteSet(False, other.elements - self.elements)
        elif not self.is_cofinite and other.is_cofinite:
            return FiniteCofiniteSet(False, self.elements - other.elements)
        else:
            return FiniteCofiniteSet(True, self.elements | other.elements)

    def __eq__(self, other):
        if isinstance(other, FiniteCofiniteSet):
            return self.is_cofinite == other.is_cofinite and self.elements == other.elements
        return False

    def __hash__(self):
        return hash((self.is_cofinite, self.elements))

    def __repr__(self):
        if self.is_cofinite:
            return f"N \\ {set(self.elements)}"
        else:
            return f"{set(self.elements)}"

class InfiniteBooleanRing:
    def __init__(self):
        # Zero is the empty set (finite set with 0 elements)
        self.zero = FiniteCofiniteSet(False, set())
        # One is the set of all natural numbers (cofinite set excluding 0 elements)
        self.one = FiniteCofiniteSet(True, set())

    def is_boolean_ring(self):
        # To verify it's a Boolean ring, we check the ring axioms and x^2 = x
        # on a representative sample of elements.
        elements = [
            self.zero,
            self.one,
            FiniteCofiniteSet(False, {1, 2, 3}),
            FiniteCofiniteSet(True, {1, 2, 3}),
            FiniteCofiniteSet(False, {2, 4, 6}),
            FiniteCofiniteSet(True, {2, 4, 6}),
            FiniteCofiniteSet(False, {3, 4, 5}),
            FiniteCofiniteSet(True, {3, 4, 5}),
        ]
        for x in elements:
            # Boolean property: x^2 = x
            if x * x != x:
                return False
            # Characteristic 2: x + x = 0
            if x + x != self.zero:
                return False
            for y in elements:
                # Commutativity
                if x * y != y * x:
                    return False
                if x + y != y + x:
                    return False
                for z in elements:
                    # Associativity
                    if (x + y) + z != x + (y + z):
                        return False
                    if (x * y) * z != x * (y * z):
                        return False
                    # Distributivity
                    if x * (y + z) != (x * y) + (x * z):
                        return False
        return True

    def is_finite(self):
        # The ring contains all finite subsets of N, so it is infinite.
        # For instance, {i} is in the ring for all i in N.
        return False

