# A ring is a direct product of local rings iff it can be decomposed into a direct product of local rings.
# We will show that R is indecomposable and has multiple maximal ideals (so it is not local itself).

def is_ideal(subset):
    if zero not in subset:
        return False
    # closed under addition
    for u in subset:
        for v in subset:
            if add(u, v) not in subset:
                return False
    # closed under multiplication by R
    for r in elements:
        for u in subset:
            if mul(r, u) not in subset:
                return False
    return True

# Find all ideals of R
ideals = []
for k in range(4):
    for basis in itertools.combinations(elements[1:], k):
        span = set([zero])
        for b in basis:
            new_span = set(span)
            for s in span:
                new_span.add(add(s, b))
            span = new_span
        if len(span) == 2**k:
            span_tuple = tuple(sorted(span))
            if span_tuple not in ideals and is_ideal(span_tuple):
                ideals.append(span_tuple)

