is_product_of_local_rings = is_decomposable or is_local

# The conclusion MUST FAIL for our counterexample
assert not is_product_of_local_rings, (
    "Conclusion holds: R is a finite direct product of Artinian local rings. "
    "Not a valid counterexample."
)

