class RingElement:
    """
    Represents an element in the commutative ring R = Q[x_1, x_2, ...] / (x_1^2, x_2^3, x_3^4, ...)
    This ring is NOT Noetherian.
    """
    def __init__(self, terms):
        self.terms = {}
        for monom, coeff in terms.items():
            if coeff != 0:
                valid = True
                norm_monom = []
                for i, deg in monom:
                    # Apply the quotient relation: x_i^{i+1} = 0
                    if deg >= i + 1:
                        valid = False
                        break
                    if deg > 0:
                        norm_monom.append((i, deg))
                if valid:
                    norm_monom = tuple(sorted(norm_monom))
                    self.terms[norm_monom] = self.terms.get(norm_monom, 0) + coeff
        # Remove zero coefficients
        self.terms = {m: c for m, c in self.terms.items() if c != 0}

    def __add__(self, other):
        new_terms = dict(self.terms)
        for m, c in other.terms.items():
            new_terms[m] = new_terms.get(m, 0) + c
        return RingElement(new_terms)

    def __mul__(self, other):
        new_terms = {}
        for m1, c1 in self.terms.items():
            for m2, c2 in other.terms.items():
                dict_m = dict(m1)
                for i, d in m2:
                    dict_m[i] = dict_m.get(i, 0) + d
                m_new = tuple(sorted(dict_m.items()))
                new_terms[m_new] = new_terms.get(m_new, 0) + c1 * c2
        return RingElement(new_terms)

    def __pow__(self, power):
        if power == 0:
            return RingElement({(): 1})
        res = RingElement({(): 1})
        base = self
        for _ in range(power):
            res = res * base
        return res

    def __eq__(self, other):
        return self.terms == other.terms

