        if self.n == 0:
            return True
        if self.n == 1:
            return False
        factors = []
        d = 2
        temp = self.n
        while d * d <= temp:
            if temp % d == 0:
                factors.append(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)
        return len(factors) == 1

