def divides(u, x):
    if u.norm() == 0:
        return x.norm() == 0
    if x.norm() % u.norm() != 0:
        return False
    nk = x.norm() // u.norm()
    max_kA = int(nk**0.5) + 1
    max_kB = int((nk/5)**0.5) + 1
    for kA in range(-max_kA, max_kA + 1):
        for kB in range(-max_kB, max_kB + 1):
            k = F_elem(kA, kB)
            if u * k == x:
                return True
    return False

def get_divisors(x):
    nx = x.norm()
    if nx == 0: return []
    divs = []
    max_A = int(nx**0.5) + 1
    max_B = int((nx/5)**0.5) + 1
    for A in range(-max_A, max_A + 1):
        for B in range(-max_B, max_B + 1):
            q = F_elem(A, B)
            if q.norm() > 0 and nx % q.norm() == 0:
                if divides(q, x):
                    divs.append(q)
    return divs

# We define two polynomials in F[x]:
# f(x) = a*x + b
a = F_elem(2, 0)
b = F_elem(1, 1)
f = [b, a]

# g(x) = c*x + d
c = F_elem(1, -1)
d = F_elem(3, 0)
g = [d, c]

# Remaining Hypothesis 1: f and g are non-constant polynomials in F[x]
def degree(p):
    d = len(p) - 1
    while d >= 0 and p[d] == F_elem(0):
        d -= 1
    return max(d, 0) if any(coeff != F_elem(0) for coeff in p) else -1

assert degree(f) >= 1, "f must be non-constant"
assert degree(g) >= 1, "g must be non-constant"

# The resultant of two linear polynomials f = ax + b and g = cx + d is ad - bc
resultant = a * d - b * c

# Check if f and g share a common factor of strictly positive degree.
# Since deg(f) = deg(g) = 1, any common factor of positive degree must have degree 1.
# This means there exists h(x) = e*x + f_0 such that f = u*h and g = v*h for u, v in F.
# Thus u divides a and b, and v divides c and d.
# Also e = a/u = c/v => v*a = u*c => a divides u*c.

common_divs_f = [u for u in get_divisors(a) if divides(u, b)]

shared_factor = False
for u in common_divs_f:
    uc = u * c
    if divides(a, uc):
        shared_factor = True
        break

# The conclusion is a biconditional:
# P: f and g share a common factor of positive degree
# Q: Res(f,g) == 0
P = shared_factor
Q = (resultant == F_elem(0))

conclusion_holds = (P == Q)

# Verify that the conclusion is FALSE (since P is False but Q is True)
assert not conclusion_holds, "The conclusion holds, but it should fail for a valid counterexample!"

class RingZ4:
    """Ring R = Z/4Z"""
    elements = [0, 1, 2, 3]

    @staticmethod
    def add(a, b):
        return (a + b) % 4

    @staticmethod
    def mult(a, b):
        return (a * b) % 4

class ModuleZ2:
    """Module M = Z/2Z over R"""
    elements = [0, 1]

    @staticmethod
    def add(a, b):
        return (a + b) % 2

    @staticmethod
    def scalar_mult(r, m):
        return (r * m) % 2

def is_module():
    """Verify that M is an R-module"""
    for r in RingZ4.elements:
        for s in RingZ4.elements:
            for m in ModuleZ2.elements:
                for n in ModuleZ2.elements:
                    # 1 * m = m
                    if ModuleZ2.scalar_mult(1, m) != m: 
                        return False
                    # r * (m + n) = r * m + r * n
                    if ModuleZ2.scalar_mult(r, ModuleZ2.add(m, n)) != \
                       ModuleZ2.add(ModuleZ2.scalar_mult(r, m), ModuleZ2.scalar_mult(r, n)): 
                        return False
                    # (r + s) * m = r * m + s * m
                    if ModuleZ2.scalar_mult(RingZ4.add(r, s), m) != \
                       ModuleZ2.add(ModuleZ2.scalar_mult(r, m), ModuleZ2.scalar_mult(s, m)): 
                        return False
                    # (r * s) * m = r * (s * m)
                    if ModuleZ2.scalar_mult(RingZ4.mult(r, s), m) != \
                       ModuleZ2.scalar_mult(r, ModuleZ2.scalar_mult(s, m)): 
                        return False
    return True

def is_regular(r):
    """Check if r is a regular element (not a zero-divisor) in R"""
    for x in RingZ4.elements:
        if x != 0 and RingZ4.mult(r, x) == 0:
            return False
    return True

def is_divisible():
    """Check if M is a divisible R-module (rM = M for all regular r in R)"""
    for r in RingZ4.elements:
        if is_regular(r):
            rM = {ModuleZ2.scalar_mult(r, m) for m in ModuleZ2.elements}
            if rM != set(ModuleZ2.elements):
                return False
    return True

def is_injective():
    """Check if M is an injective R-module using Baer's Criterion"""
    # Ideal I = (2) = {0, 2}
    ideal = [0, 2]
    # Homomorphism f: I -> M where f(0) = 0, f(2) = 1
    f = {0: 0, 2: 1}

    # Verify f is a valid R-module homomorphism
    for r in RingZ4.elements:
        for x in ideal:
            rx = RingZ4.mult(r, x)
            if f[rx] != ModuleZ2.scalar_mult(r, f[x]):
                raise ValueError("f is not a valid homomorphism")

    # Check if f extends to an R-module homomorphism g: R -> M
    # Any extension g is completely determined by g(1)
    for g1 in ModuleZ2.elements:
        extends = True
        for x in ideal:
            gx = ModuleZ2.scalar_mult(x, g1)
            if gx != f[x]:
                extends = False
                break
        if extends:
            return True

    return False

# 1. Remaining hypothesis: M is a module over R
assert is_module(), "M must be a module over R"

divisible = is_divisible()
injective = is_injective()

# 2. Verify specific properties of our counterexample
assert divisible is True, "M is divisible in our counterexample"
assert injective is False, "M is not injective in our counterexample"

# 3. The conclusion must FAIL: M is injective iff M is divisible
assert divisible != injective, "Conclusion holds: injectivity and divisibility are equivalent"

# Counterexample to: "Over a right Artinian ring, every right module is projective."
# We use the ring R = Z/4Z and the module M = {0, 2} (which is a submodule of R).
# R is finite, hence Artinian.
# M is not projective because the surjective homomorphism f: R -> M given by f(x) = 2x does not split.

class Z4Ring:
    def __init__(self):
        self.elements = [0, 1, 2, 3]

    def add(self, a, b):
        return (a + b) % 4

    def mul(self, a, b):
        return (a * b) % 4

R = Z4Ring()

# Remaining Hypothesis 1: R is a right Artinian ring
# A finite ring trivially satisfies the descending chain condition on right ideals.
assert len(R.elements) == 4, "R is finite, hence right Artinian"

# Define right R-module M = {0, 2}
M_elements = [0, 2]

# Verify M is closed under addition and right scalar multiplication
for m1 in M_elements:
    for m2 in M_elements:
        assert R.add(m1, m2) in M_elements
for m in M_elements:
    for r in R.elements:
        assert R.mul(m, r) in M_elements

# Define a surjective right R-module homomorphism f: R -> M
# f(x) = 2 * x mod 4
def f(x):
    return R.mul(2, x)

# Verify f is a right R-module homomorphism
for x in R.elements:
    for y in R.elements:
        assert f(R.add(x, y)) == R.add(f(x), f(y))
        assert f(R.mul(x, y)) == R.mul(f(x), y)

# Verify f is surjective onto M
image_f = set(f(x) for x in R.elements)
assert image_f == set(M_elements), "f is not surjective onto M"

# M is projective if and only if EVERY surjective right R-module homomorphism onto M splits.
# We check if this specific surjection f splits.
# A splitting is a homomorphism g: M -> R such that f(g(m)) == m for all m in M.
def does_f_split():
    # Generate all possible functions g: M -> R
    for val0 in R.elements:
        for val2 in R.elements:
            g = {0: val0, 2: val2}

            # Check if g is a valid right R-module homomorphism
            is_hom = True
            for m1 in M_elements:
                for m2 in M_elements:
                    if g[R.add(m1, m2)] != R.add(g[m1], g[m2]):
                        is_hom = False
                        break
                if not is_hom:
                    break

            if not is_hom:
                continue

            for m in M_elements:
                for r in R.elements:
                    if g[R.mul(m, r)] != R.mul(g[m], r):
                        is_hom = False
                        break
                if not is_hom:
                    break

            if not is_hom:
                continue

            # Check if g is a splitting (i.e., f(g(m)) == m)
            is_split = True
            for m in M_elements:
                if f(g[m]) != m:
                    is_split = False
                    break

            if is_split:
                return True

    return False

# Since f does not split, M cannot be projective.
f_splits = does_f_split()
is_M_projective = f_splits

# Conclusion must FAIL: M is a projective right R-module
assert not is_M_projective, "M is projective, but it should not be!"

print("Counterexample found!")
print("Ring R: Z/4Z (finite, hence Artinian)")
print("Module M: {0, 2} (submodule of R)")
print("M is not projective because the natural surjection R -> M does not split.")

