import itertools

class F2Dual:
    def __init__(self, a, b):
        self.a = a % 2
        self.b = b % 2

    def __add__(self, other):
        return F2Dual(self.a + other.a, self.b + other.b)

    def __mul__(self, other):
        return F2Dual(self.a * other.a, self.a * other.b + self.b * other.a)

    def __eq__(self, other):
        return isinstance(other, F2Dual) and self.a == other.a and self.b == other.b

    def __hash__(self):
        return hash((self.a, self.b))

    def __repr__(self):
        return f"{self.a} + {self.b}x"

elements = [F2Dual(0,0), F2Dual(1,0), F2Dual(0,1), F2Dual(1,1)]
