is_commutative = all(x * y == y * x for x in elements for y in elements)
assert is_commutative, "Ring must be commutative"

def is_ideal(subset):
    if zero not in subset: return False
    for x in subset:
        for y in subset:
            if (x + y) not in subset: return False
    for x in subset:
        for r in elements:
            if (x * r) not in subset: return False
    return True

# Use itertools to generate all subsets
subsets = []
for r in range(len(elements) + 1):
    for combo in itertools.combinations(elements, r):
        subsets.append(frozenset(combo))

ideals = set(s for s in subsets if is_ideal(s))
assert len(ideals) > 0

# A finite ring has finitely many ideals, so it satisfies the Ascending Chain Condition (Noetherian)
assert len(ideals) < float('inf'), "Ring must be Noetherian"

# Hypothesis 2: Local ring with unique maximal ideal m.
