class Z_mod_n_Ideal:
    def __init__(self, n, generators):
        self.n = n
        self.elements = {0}
        for g in generators:
            for r in range(n):
                self.elements.add((r * g) % n)
        self._close_addition()

    def _close_addition(self):
        while True:
            new_elements = set(self.elements)
            for x in self.elements:
                for y in self.elements:
                    new_elements.add((x + y) % self.n)
            if len(new_elements) == len(self.elements):
                break
            self.elements = new_elements

    def __eq__(self, other):
        if not isinstance(other, Z_mod_n_Ideal):
            return False
        return self.n == other.n and self.elements == other.elements

    def __mul__(self, other):
        prods = {(a * b) % self.n for a in self.elements for b in other.elements}
        return Z_mod_n_Ideal(self.n, prods)

    def __str__(self):
        return str(sorted(list(self.elements)))

