    a, b, c = r
    v1, v2, v3, v4 = e
    # X acts by mapping (v1, v2, v3, v4) -> (v3, v4, 0, 0)
    # Y acts by mapping (v1, v2, v3, v4) -> (v4, v3 + v4, 0, 0)
    res_v1 = (a * v1 + b * v3 + c * v4) % 2
    res_v2 = (a * v2 + b * v4 + c * (v3 + v4)) % 2
