# Define N = C2 x C2
N = [(0, 0), (0, 1), (1, 0), (1, 1)]
def add_N(n1, n2):
    return ((n1[0] + n2[0]) % 2, (n1[1] + n2[1]) % 2)

# Define H = C2
H = [0, 1]
def add_H(h1, h2):
    return (h1 + h2) % 2

# Define action phi: H -> Aut(N)
# phi(0) = id, phi(1) swaps coordinates
def phi(h, n):
    if h == 0:
        return n
    else:
        return (n[1], n[0])

# Check phi is a valid action by automorphisms
for h in H:
    for n1 in N:
        for n2 in N:
            assert phi(h, add_N(n1, n2)) == add_N(phi(h, n1), phi(h, n2)), "phi(h) must be a homomorphism"
for n in N:
    assert phi(0, n) == n, "phi(0) must be the identity"
for h1 in H:
    for h2 in H:
        for n in N:
            assert phi(add_H(h1, h2), n) == phi(h1, phi(h2, n)), "phi must be a group action"

# Define alpha: Aut(N)
# alpha(x, y) = (x, x + y)
def alpha(n):
    return (n[0], (n[0] + n[1]) % 2)

# Verify alpha is an automorphism of N
for n1 in N:
    for n2 in N:
        assert alpha(add_N(n1, n2)) == add_N(alpha(n1), alpha(n2)), "alpha must be a homomorphism"
assert len(set(alpha(n) for n in N)) == len(N), "alpha must be bijective"

# Define beta: Aut(H)
# beta(h) = h
def beta(h):
    return h

# Verify beta is an automorphism of H
for h1 in H:
    for h2 in H:
        assert beta(add_H(h1, h2)) == add_H(beta(h1), beta(h2)), "beta must be a homomorphism"
assert len(set(beta(h) for h in H)) == len(H), "beta must be bijective"

# Define G = N \rtimes_\phi H
G = list(itertools.product(N, H))
def mul_G(g1, g2):
    n1, h1 = g1
    n2, h2 = g2
    return (add_N(n1, phi(h1, n2)), add_H(h1, h2))

# Check G is a group (associativity)
for g1 in G:
    for g2 in G:
        for g3 in G:
            assert mul_G(mul_G(g1, g2), g3) == mul_G(g1, mul_G(g2, g3)), "G must be associative"

# Define gamma: G -> G
def gamma(g):
    n, h = g
    return (alpha(n), beta(h))

# Verify gamma is bijective
assert len(set(gamma(g) for g in G)) == len(G), "gamma must be bijective"

# Find a counterexample where gamma fails to be a homomorphism
counterexample_found = False
for g1 in G:
    for g2 in G:
        lhs = gamma(mul_G(g1, g2))
        rhs = mul_G(gamma(g1), gamma(g2))
        if lhs != rhs:
            # We found a counterexample!
            assert lhs != rhs, "This assertion proves gamma is not an automorphism"
            counterexample_found = True
            print("Counterexample found!")
            print(f"g1 = {g1}, g2 = {g2}")
            print(f"gamma(g1 * g2) = {lhs}")
