    return (x + y) % n

def mul(x, y):
    return (x * y) % n

def divides(x, y):
    return any(mul(x, k) == y for k in R)

def is_unit(x):
    return divides(x, 1)

def get_common_divisors(a, b):
    return [d for d in R if divides(d, a) and divides(d, b)]

def is_gcd(d, a, b):
    cds = get_common_divisors(a, b)
    if d not in cds:
        return False
    return all(divides(c, d) for c in cds)

