    return set(mul(a, k) for k in R)

def ideals_comaximal(a, b):
    Ia = ideal_generated_by(a)
    Ib = ideal_generated_by(b)
    I_sum = set(add(x, y) for x in Ia for y in Ib)
    return len(I_sum) == n

