import itertools

class RingZ:
    """Represents the ring of integers Z."""
    @staticmethod
    def is_ufd():
        # The integers are a well-known Unique Factorization Domain.
        return True

class MultiplicativeSubset:
    """Represents a subset of a ring."""
    def __init__(self, elements):
        self.elements = set(elements)

    def is_closed(self):
        # Check if the subset is multiplicatively closed
        for a, b in itertools.product(self.elements, repeat=2):
            if a * b not in self.elements:
                return False
        return True

    def contains_zero(self):
        return 0 in self.elements

class LocalizedRing:
    """Represents the localization of a ring R at a multiplicative subset S."""
    def __init__(self, ring, subset):
        self.ring = ring
        self.subset = subset

    def is_zero_ring(self):
        # If 0 is in the multiplicative subset S, the localized ring S^{-1}R 
        # collapses to the zero ring because 1/1 = 0/1 (since 0*(1*1 - 0*1) = 0).
        return self.subset.contains_zero()

    def is_integral_domain(self):
        # An integral domain requires 1 != 0. The zero ring is not an integral domain.
        return not self.is_zero_ring()

    def is_ufd(self):
        # By definition, a Unique Factorization Domain must be an integral domain.
        if not self.is_integral_domain():
            return False
        return self.ring.is_ufd()

