def is_group(elements, multiply):
    # Closure
    for x in elements:
        for y in elements:
            if multiply(x, y) not in elements:
                return False
    # Associativity
    for x in elements:
        for y in elements:
            for z in elements:
                if multiply(multiply(x, y), z) != multiply(x, multiply(y, z)):
                    return False
    # Identity
    identity = None
    for e in elements:
