import sympy

class Z_ideal:
    """Represents an ideal (gen) in the commutative ring R = Z"""
    def __init__(self, gen):
        self.gen = gen

    def is_prime(self):
        if self.gen == 0:
            return True
        return sympy.isprime(abs(self.gen))

class Z_p_ideal:
    """Represents an ideal in the local ring R_P = Z_{(p)}"""
    def __init__(self, p, gen):
        self.p = p
        if gen == 0:
            self.k = float('inf')
        else:
            k = 0
            temp = abs(gen)
            while temp % p == 0:
                k += 1
                temp //= p
            self.k = k

    def is_proper(self):
        # An ideal in Z_{(p)} is proper if its valuation > 0
        return self.k > 0

    def radical(self):
        # The radical of an ideal in a DVR
        if self.k == float('inf'):
            return Z_p_ideal(self.p, 0)
        elif self.k == 0:
            return Z_p_ideal(self.p, 1)
        else:
            return Z_p_ideal(self.p, self.p)

    def __eq__(self, other):
        return self.p == other.p and self.k == other.k

    def is_primary(self):
        # Primary ideals must be proper.
        if not self.is_proper():
            return False
        # In a Discrete Valuation Ring (DVR) like Z_{(p)}, all proper ideals are primary.
        return True

    def is_P_primary(self, P_extended):
        # An ideal is P-primary if it is primary and its radical is P
        return self.is_primary() and self.radical() == P_extended

