from sympy import Rational

class Element:
    def __init__(self, terms):
        # terms is a dict of {basis_element: coefficient}
        self.terms = {k: v for k, v in terms.items() if v != 0}

    def __add__(self, other):
        res = dict(self.terms)
        for k, v in other.terms.items():
            res[k] = res.get(k, 0) + v
        return Element(res)

    def __sub__(self, other):
        res = dict(self.terms)
        for k, v in other.terms.items():
            res[k] = res.get(k, 0) - v
        return Element(res)

    def __mul__(self, other):
        res = {}
        for k1, v1 in self.terms.items():
            for k2, v2 in other.terms.items():
                k3 = mult_basis(k1, k2)
                if k3 is not None:
                    res[k3] = res.get(k3, 0) + v1 * v2
        return Element(res)

    def __pow__(self, power):
        if power == 0:
            return Element({('a', 0): 1})
        res = Element({('a', 0): 1})
        for _ in range(power):
            res = res * self
        return res

    def __eq__(self, other):
        return self.terms == other.terms

    def is_zero(self):
        return len(self.terms) == 0

    def __repr__(self):
        if not self.terms:
            return "0"
        return " + ".join(f"{v}*{k[0]}^{k[1]}" for k, v in sorted(self.terms.items()))

def mult_basis(k1, k2):
    t1, i1 = k1
    t2, i2 = k2
    if t1 == 'a' and t2 == 'a':
        return ('a', i1 + i2)
    elif t1 == 'b' and t2 == 'b':
        return None
    elif t1 == 'a' and t2 == 'b':
        if i2 > i1:
            return ('b', i2 - i1)
        else:
            return None
    elif t1 == 'b' and t2 == 'a':
        if i1 > i2:
            return ('b', i1 - i2)
        else:
            return None

def get_multiplier_for_b1(f):
    """
    Finds an element g such that f * g = b1.
    This demonstrates that any non-zero principal ideal contains b1.
    """
    if f.is_zero():
        return None
    a_terms = {i: c for (t, i), c in f.terms.items() if t == 'a'}
    if a_terms:
        k = min(a_terms.keys())
        c = a_terms[k]
        return Element({('b', k + 1): Rational(1, c)})
    else:
        b_terms = {i: c for (t, i), c in f.terms.items() if t == 'b'}
        M = max(b_terms.keys())
        c = b_terms[M]
        return Element({('a', M - 1): Rational(1, c)})

