import itertools

class Ring:
    def __init__(self, name, elements, add, mul, zero, one):
        self.name = name
        self.elements = elements
        self.add = add
        self.mul = mul
        self.zero = zero
        self.one = one

    def is_commutative(self):
        for a, b in itertools.product(self.elements, repeat=2):
            if self.mul(a, b) != self.mul(b, a):
                return False
        return True

    def get_units(self):
        units = set()
        for a in self.elements:
            for b in self.elements:
                if self.mul(a, b) == self.one:
                    units.add(a)
                    break
        return units

    def get_non_units(self):
        return set(self.elements) - self.get_units()

    def is_ideal(self, subset):
        if self.zero not in subset:
            return False
        for a, b in itertools.product(subset, repeat=2):
            neg_b = None
            for x in self.elements:
                if self.add(b, x) == self.zero:
                    neg_b = x
                    break
            if self.add(a, neg_b) not in subset:
                return False
        for r in self.elements:
            for a in subset:
                if self.mul(r, a) not in subset:
                    return False
        return True

    def is_local(self):
        non_units = self.get_non_units()
        return self.is_ideal(non_units)

    def maximal_ideal(self):
        if self.is_local():
            return self.get_non_units()
        return None

