R_elements = [0, 1, 2, 3]
def R_add(a, b): return (a + b) % 4
def R_mul(a, b): return (a * b) % 4
R = Ring("Z/4Z", R_elements, R_add, R_mul, 0, 1)

# Define S = Z/2Z
S_elements = [0, 1]
def S_add(a, b): return (a + b) % 2
def S_mul(a, b): return (a * b) % 2
S = Ring("Z/2Z", S_elements, S_add, S_mul, 0, 1)

