    assert phi(R.mul(a, b)) == S.mul(phi(a), phi(b)), "phi must preserve multiplication"
assert phi(R.one) == S.one, "phi must preserve identity"

# Check phi is a local ring homomorphism
m_R = R.maximal_ideal()
m_S = S.maximal_ideal()
preimage_m_S = {x for x in R.elements if phi(x) in m_S}
assert preimage_m_S == m_R, "phi must be a local homomorphism"

