import itertools

def check_commutative_ring(n):
    elements = range(n)
    # Commutativity of addition and multiplication
    for a in elements:
        for b in elements:
            if (a + b) % n != (b + a) % n: return False
            if (a * b) % n != (b * a) % n: return False

    # Associativity of addition and multiplication
    for a in elements:
        for b in elements:
            for c in elements:
                if ((a + b) + c) % n != (a + (b + c)) % n: return False
                if ((a * b) * c) % n != (a * (b * c)) % n: return False

    # Distributivity
    for a in elements:
        for b in elements:
            for c in elements:
                if (a * (b + c)) % n != ((a * b) + (a * c)) % n: return False

    return True

def check_identity(n):
    elements = range(n)
    for e in elements:
        if all((a * e) % n == a for a in elements):
            return True
    return False

def get_ideals(n):
    elements = set(range(n))
    ideals = []
    for r in range(1, len(elements) + 1):
        for subset in itertools.combinations(elements, r):
            subset = set(subset)
            # check addition closure
            add_closed = all((a + b) % n in subset for a in subset for b in subset)
            if not add_closed:
                continue
            # check additive inverse closure
            inv_closed = all((-a) % n in subset for a in subset)
            if not inv_closed:
                continue
            # check ideal property (absorption)
            ideal_closed = all((r_elem * x) % n in subset for x in subset for r_elem in elements)
            if ideal_closed:
                ideals.append(subset)
    return ideals

def is_field(n):
    # A field must have 1 != 0
    if n <= 1:
        return False
    elements = range(n)
    for a in range(1, n):
        has_inverse = any((a * b) % n == 1 for b in elements)
        if not has_inverse:
            return False
    return True

