import itertools

class CofiniteTopologySubset:
    """
    Represents a subset of N under the cofinite topology.
    A subset is either finite or cofinite.
    If is_cofinite is True, the set is N \ finite_part.
    If is_cofinite is False, the set is finite_part.
    """
    def __init__(self, finite_part, is_cofinite):
        self.finite_part = set(finite_part)
        self.is_cofinite = is_cofinite

    def is_empty(self):
        return not self.is_cofinite and len(self.finite_part) == 0

    def is_compact(self):
        # In the cofinite topology, every subset is compact because any non-empty 
        # open set covers all but finitely many points of the space.
        return True

    def is_connected(self):
        # In the cofinite topology, any two non-empty open sets intersect, 
        # so any infinite set is connected.
        # A finite set, however, inherits the discrete topology, 
        # so it is connected if and only if it has <= 1 elements.
        if self.is_cofinite:
            return True
        else:
            return len(self.finite_part) <= 1

    def is_subset(self, other):
        if self.is_cofinite and not other.is_cofinite:
            return False
        elif not self.is_cofinite and not other.is_cofinite:
            return self.finite_part.issubset(other.finite_part)
        elif not self.is_cofinite and other.is_cofinite:
            return self.finite_part.isdisjoint(other.finite_part)
        else:
            # Both are cofinite: N \ A <= N \ B iff B <= A
            return other.finite_part.issubset(self.finite_part)


