    Returns the n-th set in our sequence: C_n = {1, 2} U {k in N | k >= n+2}
    Its complement in N is the finite set {3, 4, ..., n+1}.
    """
    return CofiniteTopologySubset(range(3, n+2), is_cofinite=True)


