class InfiniteCardinal:
    """
    Represents an infinite cardinal number.
    Supports basic cardinal addition with integers and other cardinals.
    """
    def __init__(self, name, index):
        self.name = name
        self.index = index

    def __add__(self, other):
        if isinstance(other, (int, float)):
            return self
        if isinstance(other, InfiniteCardinal):
            return self if self.index >= other.index else other
        return NotImplemented

    def __radd__(self, other):
        return self.__add__(other)

    def __eq__(self, other):
        if isinstance(other, InfiniteCardinal):
            return self.index == other.index
        return False

    def __str__(self):
        return self.name

