import itertools

class GF4Element:
    """
    Representation of elements in GF(4).
    Values 0, 1, 2, 3 correspond to 0, 1, x, x+1 where x^2 + x + 1 = 0.
    """
    def __init__(self, val):
        self.val = val

    def __add__(self, other):
        # Addition in GF(2^2) is bitwise XOR
        return GF4Element(self.val ^ other.val)

    def __mul__(self, other):
        if self.val == 0 or other.val == 0:
            return GF4Element(0)
        if self.val == 1:
            return GF4Element(other.val)
        if other.val == 1:
            return GF4Element(self.val)
        if self.val == 2 and other.val == 2:
            return GF4Element(3)
        if self.val == 3 and other.val == 3:
            return GF4Element(2)
        return GF4Element(1)

    def __eq__(self, other):
        return isinstance(other, GF4Element) and self.val == other.val

    def __hash__(self):
        return hash(self.val)

    def __repr__(self):
        return f"GF4({self.val})"

def is_field(S):
    """
    Checks if a subset S of a field is itself a field (i.e. a subfield).
    """
    # Check closure under addition and multiplication
    for a, b in itertools.product(S, S):
        if (a + b) not in S:
            return False
        if (a * b) not in S:
            return False

    # Check existence of additive identity
    has_0 = False
    for z in S:
        if all((a + z) == a for a in S):
            has_0 = True
            zero = z
            break
    if not has_0: 
        return False

    # Check existence of multiplicative identity
    has_1 = False
    for u in S:
        if all((a * u) == a for a in S if a != zero):
            has_1 = True
            one = u
            break
    if not has_1: 
        return False

    # Check existence of inverses
    for a in S:
        if not any((a + b) == zero for b in S):
            return False
        if a != zero:
            if not any((a * b) == one for b in S):
                return False

    return True

