import sympy as sp

class EuclideanSubspace:
    """Represents a metric space that is a subspace of the real line with standard metric."""
    def __init__(self, set_obj):
        self.set_obj = set_obj

    @property
    def is_bounded(self):
        try:
            return (self.set_obj.inf != -sp.oo) and (self.set_obj.sup != sp.oo)
        except AttributeError:
            return False

    @property
    def is_closed(self):
        if isinstance(self.set_obj, sp.Interval):
            # In the standard topology of R, an interval is closed if it contains its finite endpoints.
            left_closed = (not self.set_obj.left_open) or (self.set_obj.inf == -sp.oo)
            right_closed = (not self.set_obj.right_open) or (self.set_obj.sup == sp.oo)
            return left_closed and right_closed
        return False

    @property
    def is_compact(self):
        # By the Heine-Borel theorem, a subset of R is compact iff it is closed and bounded.
        return self.is_bounded and self.is_closed

class ProductMetricSpace:
    """Represents the Cartesian product of two metric spaces with the product metric."""
    def __init__(self, space1, space2):
        self.space1 = space1
        self.space2 = space2

    @property
    def is_bounded(self):
        return self.space1.is_bounded and self.space2.is_bounded

    @property
    def is_closed(self):
        return self.space1.is_closed and self.space2.is_closed

    @property
    def is_compact(self):
        # By the Heine-Borel theorem for R^n, the product is compact iff it is closed and bounded.
        return self.is_bounded and self.is_closed

