import itertools

def is_topology(points, topology):
    """Check if the given family of sets forms a topology on points."""
    if frozenset() not in topology or frozenset(points) not in topology:
        return False
    for A in topology:
        for B in topology:
            if A.union(B) not in topology:
                return False
            if A.intersection(B) not in topology:
                return False
    return True

def is_connected_subset(S, topology):
    """Check if a subset S is connected in the subspace topology."""
    if len(S) <= 1:
        return True
    sub_top = set(frozenset(S.intersection(U)) for U in topology)
    clopen_in_S = [A for A in sub_top if frozenset(S - A) in sub_top]
    # A connected space has exactly 2 clopen sets: the empty set and the space itself
    return len(clopen_in_S) == 2

def is_totally_disconnected(points, topology):
    """Check if the topological space is totally disconnected."""
    # A space is totally disconnected if its only connected subsets are empty or singletons.
    for r in range(2, len(points) + 1):
        for subset in itertools.combinations(points, r):
            if is_connected_subset(frozenset(subset), topology):
                return False
    return True

def is_continuous(f, X_points, X_topology, Y_points, Y_topology):
    """Check if f: X -> Y is continuous."""
    # Check if image of f is in Y_points
    if not all(y in Y_points for y in f.values()):
        return False
    # Check preimage of every open set in Y is open in X
    for V in Y_topology:
        preimage = frozenset(x for x in X_points if f[x] in V)
        if preimage not in X_topology:
            return False
    return True

