import itertools

class FiniteTopologicalSpace:
    def __init__(self, points, open_sets):
        self.points = list(points)
        self.open_sets = [set(s) for s in open_sets]

    def is_valid_topology(self):
        """Check if the given open sets form a valid topology."""
        if set() not in self.open_sets or set(self.points) not in self.open_sets:
            return False
        for U in self.open_sets:
            for V in self.open_sets:
                if U.intersection(V) not in self.open_sets:
                    return False
                if U.union(V) not in self.open_sets:
                    return False
        return True

    def is_t2(self):
        """Check if the space is Hausdorff (T2)."""
        for x, y in itertools.combinations(self.points, 2):
            separated = False
            for U in self.open_sets:
                if x in U and y not in U:
                    for V in self.open_sets:
                        if y in V and x not in V:
                            if U.isdisjoint(V):
                                separated = True
                                break
                    if separated:
                        break
            if not separated:
                return False
        return True

    def is_compact(self):
        """Every finite topological space is compact."""
        return True

    def is_metric_space(self):
        """A metric space must be Hausdorff. (For finite spaces, it must be discrete)."""
        return self.is_t2()

    def every_continuous_function_to_R_is_bounded(self):
        """
        Since the space is finite, EVERY function to R has a finite image.
        Every finite subset of R is bounded.
        Thus, every continuous function to R is bounded.
        """
        return True

