import sympy as sp

class ZIdeal:
    """
    Represents an ideal in the commutative ring of integers Z.
    An ideal (n) is generated by a non-negative integer n.
    """
    def __init__(self, n):
        self.n = abs(n)

    def is_subset(self, other):
        """ (a) is a subset of (b) iff b divides a """
        if other.n == 0:
            return self.n == 0
        return self.n % other.n == 0

    def is_prime(self):
        """ (p) is prime if p is a prime number or 0 """
        if self.n == 0:
            return True
        if self.n == 1:
            return False
        return sp.isprime(self.n)

    def radical(self):
        """ The radical of (n) is generated by the product of its distinct prime factors """
        if self.n == 0:
            return ZIdeal(0)
        factors = sp.factorint(self.n)
        rad = 1
        for p in factors:
            rad *= p
        return ZIdeal(rad)

    def is_primary(self):
        """ (n) is primary if n = p^k for some prime p, or n = 0 """
        if self.n == 0:
            return True
        if self.n == 1:
            return False
        factors = sp.factorint(self.n)
        return len(factors) == 1

    def is_P_primary(self, P):
        """ An ideal is P-primary if it is primary and its radical is P """
        return self.is_primary() and self.radical() == P

    def __eq__(self, other):
        return self.n == other.n

    def __str__(self):
        return f"({self.n})"

# [1] Remaining Hypothesis: R is a commutative ring
# We use R = Z, which is a commutative ring.

