    # For i >= 1, we create a chain that stabilizes:
    # Q_1=(48) <= Q_2=(24) <= Q_3=(12) <= Q_4=(6) <= Q_5=(3) <= Q_6=(3) <= ...
    power = max(0, 5 - i)
    return ZIdeal(3 * (2 ** power))

# Verify it's an ascending chain
for i in range(1, 20):
    assert get_Q(i).is_subset(get_Q(i+1)), f"Chain must be ascending at step {i}"

# The union of an ascending chain that stabilizes is simply its maximum element
Q_union = get_Q(20)

# CONCLUSION: The union is a P-primary ideal
# This must FAIL for the conjecture to be false
assert not Q_union.is_P_primary(P), "Conclusion holds, but it should fail!"

