for i in range(1, 7):
    print(f"  Q_{i} = {get_Q(i)}")
print(f"Union Q = {Q_union}")
print(f"Radical of Q = {Q_union.radical()} != {P}")

import sympy as sp

class IdealZ:
    """Represents an ideal in the commutative ring of integers Z."""
    def __init__(self, gen):
        self.gen = abs(gen)

    def is_proper(self):
        return self.gen != 1

    def is_prime(self):
        if self.gen == 0:
            return True
        if self.gen == 1:
            return False
        return sp.isprime(self.gen)

    def radical(self):
        if self.gen == 0:
            return IdealZ(0)
        if self.gen == 1:
            return IdealZ(1)
        factors = sp.factorint(self.gen)
        rad = 1
        for p in factors:
            rad *= p
        return IdealZ(rad)

    def is_primary(self):
        if self.gen == 0:
            return True
        if self.gen == 1:
            return False
        factors = sp.factorint(self.gen)
        return len(factors) == 1

    def __eq__(self, other):
        return self.gen == other.gen

    def __str__(self):
        return f"({self.gen})"

class LocalizedIdealZ:
    """Represents an extended ideal in the localized ring S^{-1}Z."""
    def __init__(self, ideal, S_primes):
        self.ideal = ideal
        self.S_primes = S_primes

    def get_localized_gen(self):
        if self.ideal.gen == 0:
            return 0
        gen = self.ideal.gen
        for p in self.S_primes:
            while gen % p == 0:
                gen //= p
        return gen

    def is_proper(self):
        return self.get_localized_gen() != 1

    def is_primary(self):
        gen = self.get_localized_gen()
        if gen == 1:
            return False  # The whole ring is not a proper ideal, hence not primary
        if gen == 0:
            return True
        factors = sp.factorint(gen)
        return len(factors) == 1

    def radical(self):
        gen = self.get_localized_gen()
        if gen == 0:
            return LocalizedIdealZ(IdealZ(0), self.S_primes)
        if gen == 1:
            return LocalizedIdealZ(IdealZ(1), self.S_primes)
        factors = sp.factorint(gen)
        rad = 1
        for p in factors:
            rad *= p
        return LocalizedIdealZ(IdealZ(rad), self.S_primes)

    def __eq__(self, other):
        return self.get_localized_gen() == other.get_localized_gen()

    def __str__(self):
        return f"({self.get_localized_gen()}) in S^{{-1}}Z"

