class TopologicalSpace:
    def __init__(self, points, open_sets):
        self.points = frozenset(points)
        self.open_sets = set(frozenset(u) for u in open_sets)

    def is_topology(self):
        """Check if the given open sets form a valid topology on the points."""
        if frozenset() not in self.open_sets:
            return False
        if self.points not in self.open_sets:
            return False

        # Check that it is closed under finite intersections and unions
        for u in self.open_sets:
            for v in self.open_sets:
                if u.intersection(v) not in self.open_sets:
                    return False
                if u.union(v) not in self.open_sets:
                    return False
        return True

    def is_path_connected(self):
        """
        Check if the finite topological space is path-connected.
        For finite spaces, path-connectedness is equivalent to the connectedness 
        of the comparability graph of its specialization preorder.
        x <= y iff x is in the closure of {y} (i.e., every open set containing x contains y).
        """
        points_list = list(self.points)
        if not points_list:
            return True

        adj = {p: set() for p in self.points}
        for x in self.points:
            for y in self.points:
                if x == y: 
                    continue
                # x <= y if every open set containing x also contains y
                x_le_y = all(y in u for u in self.open_sets if x in u)
                if x_le_y:
                    adj[x].add(y)
                    adj[y].add(x)

        # BFS to find connected components in the comparability graph
        visited = set()
        queue = [points_list[0]]
        visited.add(points_list[0])

        while queue:
            curr = queue.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return len(visited) == len(self.points)

