import itertools

def action(h, n):
    x, y, z = n
    if h == 0: return (x, y, z)
    if h == 1: return (x, (-y)%3, (-z)%3)
    if h == 2: return ((-x)%3, y, (-z)%3)
    if h == 3: return ((-x)%3, (-y)%3, z)

def multiply(g1, g2):
    n1, h1 = g1
    n2, h2 = g2
    n2_acted = action(h1, n2)
    n_res = ((n1[0] + n2_acted[0]) % 3,
             (n1[1] + n2_acted[1]) % 3,
             (n1[2] + n2_acted[2]) % 3)
    h_res = h1 ^ h2
    return (n_res, h_res)

def inverse(g):
    n, h = g
    neg_n = ((-n[0])%3, (-n[1])%3, (-n[2])%3)
    n_inv = action(h, neg_n)
    return (n_inv, h)

