H_elements = list(range(4))
G = [(n, h) for n in N_elements for h in H_elements]
identity = ((0, 0, 0), 0)

def alpha(g):
    n, h = g
    x, y, z = n
    phi_n = (y, z, (-x)%3)

    if h == 0: psi_h = 0
    elif h == 1: psi_h = 3
    elif h == 2: psi_h = 1
    elif h == 3: psi_h = 2

    return (phi_n, psi_h)

