    comms = set()
    for a in A:
        for b in B:
            comms.add(multiply(multiply(a, b), multiply(inverse(a), inverse(b))))

    subgroup = set(comms)
    queue = list(comms)
    while queue:
        curr = queue.pop(0)
        for g in comms:
            nxt = multiply(curr, g)
            if nxt not in subgroup:
                subgroup.add(nxt)
                queue.append(nxt)
    return subgroup

