class Z4Ring:
    """The ring R = Z/4Z."""
    def __init__(self):
        self.elements = [0, 1, 2, 3]

    def is_commutative(self):
        # Check if a * b == b * a mod 4 for all elements
        return all((a * b) % 4 == (b * a) % 4 for a in self.elements for b in self.elements)

class Z4Ideal:
    """The ideal I = (2) in Z/4Z."""
    def __init__(self):
        self.elements = [0, 2]

    def is_nil(self):
        # An ideal is nil if every element is nilpotent.
        for x in self.elements:
            nilpotent = False
            for n in range(1, 5):
                if (x**n) % 4 == 0:
                    nilpotent = True
                    break
            if not nilpotent:
                return False
        return True

class Z4Module:
    """The module M = Z/4Z over the ring R = Z/4Z."""
    def __init__(self):
        self.elements = [0, 1, 2, 3]

    def is_finitely_generated(self):
        # M is generated by the single element 1, so it is finitely generated.
        return True

    def is_zero_module(self):
        # The zero module contains exactly one element (the identity 0).
        return len(self.elements) == 1

