import itertools

class Ring:
    def __init__(self, elements, add, mul, zero, one):
        self.elements = elements
        self._add = add
        self._mul = mul
        self.zero = zero
        self.one = one

    def add(self, a, b):
        return self._add(a, b)

    def mul(self, a, b):
        return self._mul(a, b)

def is_commutative(ring):
    for a in ring.elements:
        for b in ring.elements:
            if ring.mul(a, b) != ring.mul(b, a):
                return False
    return True

def has_identity(ring):
    for a in ring.elements:
        if ring.mul(a, ring.one) != a or ring.mul(ring.one, a) != a:
            return False
    return True

def get_ideals(ring):
    ideals = []
    n = len(ring.elements)
    for r in range(1, n + 1):
        for subset in itertools.combinations(ring.elements, r):
            subset = set(subset)

            # Check if closed under addition
            closed_add = True
            for a in subset:
                for b in subset:
                    if ring.add(a, b) not in subset:
                        closed_add = False
                        break
                if not closed_add:
                    break
            if not closed_add:
                continue

            # Check if closed under absorption (ideal property)
            closed_mul = True
            for a in subset:
                for r_elem in ring.elements:
                    if ring.mul(a, r_elem) not in subset:
                        closed_mul = False
                        break
                    if ring.mul(r_elem, a) not in subset:
                        closed_mul = False
                        break
                if not closed_mul:
                    break

            if closed_mul:
                ideals.append(subset)
    return ideals

def is_local(ring):
    # A local ring has exactly one maximal ideal.
    # A maximal ideal must be a proper ideal.
    ideals = get_ideals(ring)
    proper_ideals = [I for I in ideals if len(I) < len(ring.elements)]
    max_ideals = []
    for I in proper_ideals:
        is_maximal = True
        for J in proper_ideals:
            if I != J and I.issubset(J):
                is_maximal = False
                break
        if is_maximal:
            max_ideals.append(I)
    return len(max_ideals) == 1

def is_surjective(f, R, S):
    image = set(f(a) for a in R.elements)
    return image == set(S.elements)

def is_homomorphism(f, R, S):
    for a in R.elements:
        for b in R.elements:
            if f(R.add(a, b)) != S.add(f(a), f(b)):
                return False
            if f(R.mul(a, b)) != S.mul(f(a), f(b)):
                return False
    if f(R.one) != S.one:
        return False
    return True

