    elements=[0, 1],
    add=lambda a, b: (a + b) % 2,
    mul=lambda a, b: (a * b) % 2,
    zero=0,
    one=1
)

S = Ring(
    elements=[0],
    add=lambda a, b: 0,
    mul=lambda a, b: 0,
    zero=0,
    one=0
)

# f is the zero map, which is surjective onto the zero ring
def f(x):
    return 0

# ---------------------------------------------------------------------------
# Verification of Remaining Hypotheses
# ---------------------------------------------------------------------------
assert is_commutative(R), "Hypothesis 1 failed: R must be commutative"
assert has_identity(R), "Hypothesis 1 failed: R must have identity"

assert is_local(R), "Hypothesis 2 failed: R must be a local ring"

assert is_commutative(S), "Hypothesis 3 failed: S must be commutative"
assert has_identity(S), "Hypothesis 3 failed: S must have identity"

assert is_homomorphism(f, R, S), "Hypothesis 4 failed: f must be a ring homomorphism"
assert is_surjective(f, R, S), "Hypothesis 4 failed: f must be surjective"

# ---------------------------------------------------------------------------
# Verification that Conclusion Fails
# ---------------------------------------------------------------------------
# The zero ring has NO proper ideals, hence 0 maximal ideals, so it is NOT local.
assert not is_local(S), "Conclusion holds: S is a local ring. Counterexample invalid."

print("Counterexample found!")
print("R = Z_2 (Local Ring)")
print("S = Z_1 (Zero Ring, not local due to having 0 proper ideals)")
print("f(x) = 0 is a surjective ring homomorphism from R to S.")

