    lst = list(iterable)
    if not lst:
        return 0
    return reduce(math.gcd, lst)

class Z_Ideal:
    def __init__(self, gen):
        self.gen = abs(gen)

    def contains(self, x):
        if self.gen == 0:
            return x == 0
        return x % self.gen == 0

    def intersection(self, other):
        if self.gen == 0 and other.gen == 0:
            return Z_Ideal(0)
        elif self.gen == 0 or other.gen == 0:
            return Z_Ideal(0)
        return Z_Ideal(abs(self.gen * other.gen) // math.gcd(self.gen, other.gen))

