import random

class EventConstSeq:
    def __init__(self, default, exceptions=None):
        self.default = default
        self.exceptions = exceptions or {}
        # Clean up exceptions that are equal to the default value
        self.exceptions = {k: v for k, v in self.exceptions.items() if v != default}

    def __eq__(self, other):
        return self.default == other.default and self.exceptions == other.exceptions

    def __add__(self, other):
        new_default = self.default + other.default
        keys = set(self.exceptions.keys()) | set(other.exceptions.keys())
        new_exc = {k: self.get(k) + other.get(k) for k in keys}
        return EventConstSeq(new_default, new_exc)

    def __mul__(self, other):
        new_default = self.default * other.default
        keys = set(self.exceptions.keys()) | set(other.exceptions.keys())
        new_exc = {k: self.get(k) * other.get(k) for k in keys}
        return EventConstSeq(new_default, new_exc)

    def get(self, k):
        return self.exceptions.get(k, self.default)

    def is_zero(self):
        return self.default == 0 and not self.exceptions

