# Domain X: Non-negative integers {0, 1, 2, ...}
# Metric d_X: Discrete metric
def d_X(x1, x2):
    return 0.0 if x1 == x2 else 1.0

# Domain Y: {1/n : n in Z^+} U {0}
# Metric d_Y: Standard Euclidean metric
def d_Y(y1, y2):
    return abs(y1 - y2)

# Bijection f: X -> Y
def f(x):
    if x == 0:
        return 0.0
    return 1.0 / x

# Inverse f^{-1}: Y -> X
def f_inv(y):
    if y == 0.0:
        return 0
    return int(round(1.0 / y))

# ----------------------------------------------------------------
# VERIFY REMAINING HYPOTHESES
# ----------------------------------------------------------------

sample_X = [0, 1, 2, 3, 4, 10, 100]
sample_Y = [f(x) for x in sample_X]

# Hypothesis 1: (X, d_X) and (Y, d_Y) are metric spaces
for a in sample_X:
    for b in sample_X:
        assert d_X(a, b) >= 0
        assert (d_X(a, b) == 0) == (a == b)
        assert d_X(a, b) == d_X(b, a)
        for c in sample_X:
            assert d_X(a, c) <= d_X(a, b) + d_X(b, c)

for a in sample_Y:
    for b in sample_Y:
        assert d_Y(a, b) >= 0
        assert (d_Y(a, b) == 0) == (a == b)
        assert d_Y(a, b) == d_Y(b, a)
        for c in sample_Y:
            assert d_Y(a, c) <= d_Y(a, b) + d_Y(b, c)

# Hypothesis 2: f is a bijective function
for x in sample_X:
    assert f_inv(f(x)) == x
for y in sample_Y:
    assert f(f_inv(y)) == y

# Hypothesis 3: f is continuous
# Since X has the discrete metric, every function from X is continuous.
# For any epsilon > 0, choosing delta = 0.5 ensures d_X(x1, x2) < delta implies x1 == x2.
def is_f_continuous(sample):
    epsilon = 0.01
    delta = 0.5
    for x1 in sample:
        for x2 in sample:
            if d_X(x1, x2) < delta:
                if d_Y(f(x1), f(x2)) >= epsilon:
                    return False
    return True

assert is_f_continuous(sample_X), "f must be continuous"

# ----------------------------------------------------------------
# FALSIFY THE CONCLUSION
# ----------------------------------------------------------------

# Conclusion: The inverse function f^{-1}: Y -> X is continuous.
# We test if f^{-1} is continuous at y = 0.
# If it were continuous, then for epsilon = 0.5, there must exist some delta > 0 
# such that for all y in Y, d_Y(y, 0) < delta implies d_X(f_inv(y), f_inv(0)) < epsilon.
def is_f_inv_continuous_at_zero():
    epsilon = 0.5

    # We check a sequence of shrinking deltas. If f_inv is continuous,
    # one of these deltas (or a smaller one) must satisfy the condition.
    for delta in [1.0, 0.1, 0.01, 0.001, 0.0001, 1e-5]:
        # Construct a y in Y such that d_Y(y, 0) < delta
        n = int(2.0 / delta) + 1
        y = f(n)

        assert d_Y(y, 0.0) < delta, "y must be within delta of 0"

        # Check if the implication holds for this y
        # If d_X(f_inv(y), f_inv(0)) < epsilon, this delta might work.
        if d_X(f_inv(y), f_inv(0.0)) < epsilon:
            return True  # Found a working delta

    # All tested deltas failed. We can find points arbitrarily close to 0 in Y
    # that do NOT map close to f_inv(0) in X.
    return False

# The conclusion MUST FAIL for this to be a valid counterexample
assert not is_f_inv_continuous_at_zero(), "Conclusion holds: f^{-1} is continuous, but it should not be!"

print("Counterexample successfully constructed and verified.")
print("X = N with discrete metric")
print("Y = {1/n : n in Z^+} U {0} with Euclidean metric")
print("f(n) = 1/n if n > 0 else 0")
print("f is a continuous bijection, but f^{-1} is NOT continuous at 0.")

