import itertools

# We construct a counterexample using the finite ring R = Z/6Z.
# Let I = {0} be the zero ideal, and S = R be the multiplicatively closed set.
# We will show that all remaining hypotheses hold, but I is NOT a prime ideal.

# Define the ring R = Z/6Z
R = set(range(6))

def add(a, b):
    return (a + b) % 6

def mul(a, b):
    return (a * b) % 6

# S is a multiplicatively closed subset of R
S = set(R)

# I is the zero ideal
I = {0}

# HYPOTHESIS [1]: R is a commutative ring with identity
identity = 1
assert all(mul(a, identity) == a for a in R), "R lacks identity"
assert all(mul(a, b) == mul(b, a) for a in R for b in R), "R is not commutative"
assert all(add(a, b) == add(b, a) for a in R for b in R), "Addition is not commutative"

# HYPOTHESIS [2]: S is a multiplicatively closed subset of R
assert all(mul(a, b) in S for a in S for b in S), "S is not multiplicatively closed"

# Helper function to check if a subset is an ideal
def is_ideal(subset):
    if not subset:
        return False
    # Closed under addition
    for a in subset:
        for b in subset:
            if add(a, b) not in subset:
                return False
    # Closed under multiplication by any element in R (absorptive property)
    for a in subset:
        for r in R:
            if mul(a, r) not in subset:
                return False
    return True

# Find all ideals of R by exhaustively checking all subsets
all_ideals = [
    set(subset) 
    for r in range(1, len(R) + 1) 
    for subset in itertools.combinations(R, r) 
    if is_ideal(set(subset))
]

assert is_ideal(I), "I is not an ideal"

# HYPOTHESIS [3]: For any ideal J of R strictly containing I, J intersect S is non-empty
for J in all_ideals:
    if I.issubset(J) and I != J:
        assert len(J.intersection(S)) > 0, f"Ideal {J} strictly contains I but is disjoint from S"

# CONCLUSION TO FALSIFY: I is a prime ideal of R
def is_prime_ideal(P):
    if P == R:  # Prime ideals must be proper
        return False
    for a in R:
        for b in R:
            if mul(a, b) in P:
                if a not in P and b not in P:
                    return False
    return True

# Ensure the conclusion FAILS at our counterexample
assert not is_prime_ideal(I), "Logic Error: I is a prime ideal, but we need a counterexample!"

# (Optional check to explicitly show why it fails: 2 * 3 = 0 in Z/6Z, but 2 not in {0} and 3 not in {0})
assert mul(2, 3) in I
assert 2 not in I
assert 3 not in I

