import itertools

# Define the metric spaces X and Y as finite sets (discrete metric spaces)
X = {0}
Y = {0}

# Define subsets A and B
A = {0}
B = {0}

# Define W as the empty set, which is an open subset of X \times Y
W = set()

# In a discrete metric space, all subsets are open.
def get_all_subsets(space):
    subsets = []
    for r in range(len(space) + 1):
        for combo in itertools.combinations(space, r):
            subsets.append(set(combo))
    return subsets

open_sets_X = get_all_subsets(X)
open_sets_Y = get_all_subsets(Y)

# Verify Remaining Hypotheses
# [1] X and Y are metric spaces (True by definition of discrete metric)
# [2] A is a compact subset of X (finite sets in metric spaces are compact)
assert A.issubset(X), "A must be a subset of X"
# [3] B is a compact subset of Y (finite sets in metric spaces are compact)
assert B.issubset(Y), "B must be a subset of Y"
# [4] W is an open subset of X \times Y (the empty set is always open)
X_times_Y = {(x, y) for x in X for y in Y}
assert W.issubset(X_times_Y), "W must be a subset of X \times Y"

# Check Conclusion
# There exist open U subset X, V subset Y such that A subset U, B subset V, U \times V subset W
conclusion_holds = False
for U in open_sets_X:
    for V in open_sets_Y:
        if A.issubset(U) and B.issubset(V):
            U_times_V = {(u, v) for u in U for v in V}
            if U_times_V.issubset(W):
                conclusion_holds = True
                break
    if conclusion_holds:
        break

# The conclusion must FAIL at our counterexample
assert not conclusion_holds, "Conclusion holds, but it should fail for a valid counterexample."

print("Counterexample found!")
print(f"Space X: {X}, Space Y: {Y}")
print(f"Compact set A: {A}, Compact set B: {B}")
print(f"Open set W in X x Y: {W}")
print("There are no open sets U containing A and V containing B such that U x V is a subset of W.")

