import math

a, b, c = 2, 7, -11

assert a != 0 and b != 0 and c != 0

def is_square_free(n):
    n = abs(n)
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % (i * i) == 0:
            return False
    return True

assert is_square_free(a)
assert is_square_free(b)
assert is_square_free(c)

assert math.gcd(a, b) == 1
assert math.gcd(b, c) == 1
assert math.gcd(a, c) == 1

assert not (a > 0 and b > 0 and c > 0)
assert not (a < 0 and b < 0 and c < 0)

def is_quad_residue(n, m):
    m = abs(m)
    if m == 1:
        return True
    for i in range(m):
        if (i * i) % m == n % m:
            return True
    return False

assert is_quad_residue(-b * c, a)
assert is_quad_residue(-a * c, b)

def conclusion_holds_bounded(a, b, c, limit=500):
    c_abs = abs(c)
    for x in range(limit):
        for y in range(limit):
            if x == 0 and y == 0:
                continue
            val = a * x**2 + b * y**2
            if val % c_abs == 0:
                z2 = val // c_abs
                z = math.isqrt(z2)
                if z * z == z2:
                    return True
    return False

assert not conclusion_holds_bounded(a, b, c, 500)

def has_local_obstruction(a, b, c):
    c_abs = abs(c)
    for x in range(c_abs):
        for y in range(c_abs):
            if (a * x**2 + b * y**2) % c_abs == 0:
                if x != 0 or y != 0:
                    return False
    return True

assert has_local_obstruction(a, b, c)

print("Counterexample successfully verified!")
print(f"a = {a}, b = {b}, c = {c}")
